def _cross_border_technology_transaction_context(contract_text: str) -> Dict[str, Any]:
    """Detect a real cross-border technology supply without requiring a legal label.

    Contracts often identify a foreign consultant and a domestic client but do
    not call themselves a "technology import contract".  Party geography and
    the operative technology supply are enough to trigger classification and a
    follow-up regulatory assessment; they do not, by themselves, decide whether
    registration or licensing is legally required.
    """
    compact = _compact(contract_text)
    foreign_markers = (
        "德国", "法国", "英国", "美国", "日本", "韩国", "新加坡", "瑞士", "荷兰",
        "意大利", "西班牙", "奥地利", "加拿大", "澳大利亚", "境外", "外国",
        "GMBH", "LLC", "INC.", "LTD.", "GERMANY", "FRANCE", "UNITEDKINGDOM",
    )
    foreign_party = any(marker in compact.upper() for marker in foreign_markers)
    domestic_party = any(term in compact for term in (
        "中国公司", "中国企业", "中国境内", "中华人民共和国", "有限责任公司", "有限公司",
    ))
    technology_supply = any(term in compact for term in (
        "技术咨询", "咨询报告", "技术服务", "技术许可", "技术转让", "技术资料", "技术方案",
    ))
    foreign_provider = bool(re.search(
        r"(?:德国|法国|英国|美国|日本|韩国|新加坡|瑞士|荷兰|意大利|西班牙|奥地利|加拿大|澳大利亚|境外|外国)"
        r"[^。；]{0,120}(?:咨询方|服务方|许可方|转让方|乙方)",
        compact,
        re.I,
    )) or bool(re.search(
        r"(?:咨询方|服务方|许可方|转让方|乙方)[^。；]{0,160}(?:GERMANY|德国|境外|外国)",
        compact,
        re.I,
    ))
    explicit_no_cross_border = any(term in compact for term in (
        "不涉及跨境技术进出口", "不涉及技术进出口", "无跨境技术交易",
    ))
    present = bool(foreign_party and domestic_party and technology_supply and not explicit_no_cross_border)
    return {
        "present": present,
        "foreign_party_present": foreign_party,
        "domestic_party_present": domestic_party,
        "technology_supply_present": technology_supply,
        "foreign_provider": foreign_provider,
        "direction": "POTENTIAL_TECHNOLOGY_IMPORT" if present and foreign_provider else "CROSS_BORDER_TECHNOLOGY_TRANSACTION" if present else "NONE",
        "requires_regulatory_assessment": present,
        "does_not_prejudge_registration_or_license": True,
    }


def _detect_technology_subtypes(compacted_text: str) -> set[str]:
    classification = classify_technology_transaction(compacted_text)
    resolved = classification.get("subtype")
    resolved_subtypes: set[str] = set()
    primary_mapping = {
        "TECHNICAL_SERVICE": {"service"},
        "COOPERATIVE_DEVELOPMENT": {"development", "cooperative_development"},
        "ENTRUSTED_DEVELOPMENT": {"development", "entrusted_development"},
        "TECHNOLOGY_TRANSFER": {"transfer"},
        "TECHNOLOGY_LICENSE": {"license"},
        "TECHNICAL_CONSULTING": {"consulting"},
    }
    resolved_subtypes.update(primary_mapping.get(str(resolved), set()))
    compacted = _compact(compacted_text)
    explicit_no_import_export = any(term in compacted for term in (
        "不涉及跨境技术进出口", "不涉及技术进出口", "无跨境技术交易",
    ))
    cross_border_context = _cross_border_technology_transaction_context(compacted_text)
    if not explicit_no_import_export and (cross_border_context["present"] or any(term in compacted for term in ("技术进出口", "技术进口", "技术出口", "跨境技术交易", "跨境技术许可")) or bool(
        re.search(r"(?:德国|境外|外国)[^。；]{0,80}(?:向|许可|提供)[^。；]{0,80}(?:中国|境内)[^。；]{0,80}(?:技术|许可)", compacted)
    )):
        resolved_subtypes.add("import_export")
    for module in classification.get("secondary_modules") or []:
        if module == "COMMISSIONED_DEVELOPMENT":
            resolved_subtypes.update({"development", "entrusted_development"})
        elif module == "COOPERATIVE_DEVELOPMENT":
            resolved_subtypes.update({"development", "cooperative_development"})
        elif module == "TECHNICAL_CONSULTING":
            resolved_subtypes.add("consulting")
        elif module == "TECHNICAL_SERVICE":
            # Ancillary service activates TC-09 through its explicit fact route;
            # it must not globally turn every service-only rule on.
            pass
    # Transaction routing must never fall back to a bag of topic keywords.
    # A low-confidence classifier result remains unresolved and is handled by
    # the type-classification review instead of activating every subtype pack.
    return resolved_subtypes


def _technology_subtype_reason(subtypes: set[str], checkpoint: ReviewCheckpoint) -> str:
    labels = "、".join(_TECHNOLOGY_SUBTYPE_LABELS[subtype] for subtype in sorted(subtypes) if subtype in _TECHNOLOGY_SUBTYPE_LABELS)
    if not labels:
        labels = "未识别到明确技术合同子类型"
    return f"当前文本识别为{labels}场景，未触发“{checkpoint.title}”的适用条件：{checkpoint.applicable_if}"


def _technology_third_party_context(contract_text: str) -> Dict[str, Any]:
    compact = _compact(contract_text)
    actor_patterns = (
        r"(?:转委托|分包|外包).{0,20}第三方",
        r"第三方.{0,20}(?:服务人员|服务商|分包商|承包商|受托主体)",
    )
    ip_patterns = (
        r"第三方.{0,24}(?:软件|代码|SDK|数据库组件|开源组件|专利|技术秘密|著作权|知识产权|授权|许可|权利主张|侵权)",
        r"(?:软件|代码|SDK|数据库组件|开源组件|专利|技术秘密|著作权|知识产权).{0,24}第三方",
    )
    standalone_ip_markers = (
        "第三方授权", "第三方权利保证", "第三方权利主张", "第三方侵权主张",
        "知识产权转让", "著作权许可", "技术秘密许可", "专利实施许可",
        "开源组件", "实际许可依赖", "license dependency",
    )
    actor_matches = [pattern for pattern in actor_patterns if re.search(pattern, compact, re.IGNORECASE)]
    ip_matches = [pattern for pattern in ip_patterns if re.search(pattern, compact, re.IGNORECASE)]
    marker_matches = [marker for marker in standalone_ip_markers if _compact(marker) in compact]
    return {
        "third_party_actor": bool(actor_matches),
        "third_party_subcontractor": bool(actor_matches),
        "third_party_ip_trigger": bool(ip_matches or marker_matches),
        "actor_match_count": len(actor_matches),
        "ip_match_count": len(ip_matches) + len(marker_matches),
        "matched_ip_markers": marker_matches,
    }


def _technology_ip_proof_context(contract_text: str) -> Dict[str, Any]:
    """Resolve proof applicability from operative IP facts, independently of subtype."""
    compact = _compact(contract_text)
    third_party = _technology_third_party_context(contract_text)
    clauses = [
        _compact(segment)
        for segment in re.split(r"[。；;\n]", contract_text or "")
        if _compact(segment)
    ]

    def operative_asset_clause(pattern: str) -> bool:
        """A conditional future safeguard is not proof that an asset is in this deal."""
        for clause in clauses:
            if not re.search(pattern, clause, re.IGNORECASE):
                continue
            if any(marker in clause for marker in (
                "如涉及", "若涉及", "如果涉及", "如使用", "若使用", "如果使用",
                "涉及第三方软件许可的", "应形成清单", "不得引入", "不构成",
            )):
                continue
            return True
        return False

    source_delivery = bool(re.search(
        r"(?:提交|交付|提供|移交).{0,30}(?:源代码|软件|脚本|算法|组件)|"
        r"(?:源代码|软件|脚本|算法|组件).{0,30}(?:提交|交付|提供|移交)",
        compact,
    ))
    background_use = bool(re.search(
        r"(?:已有|既有|背景).{0,30}(?:软件|代码|规则引擎|算法|工具|组件|技术框架)|"
        r"(?:软件|代码|规则引擎|算法|工具|组件|技术框架).{0,30}(?:已有|既有|背景)",
        compact,
    ))
    operative_background_ip_use = operative_asset_clause(
        r"(?:使用|采用|基于|依赖|提供|交付)[^。；]{0,45}(?:已有|既有|背景)"
        r"[^。；]{0,30}(?:软件|代码|规则引擎|算法|工具|组件|技术框架)|"
        r"(?:已有|既有|背景)[^。；]{0,30}(?:软件|代码|规则引擎|算法|工具|组件|技术框架)"
        r"[^。；]{0,45}(?:使用|采用|提供|交付|纳入)"
    )
    rights_disposition = bool(re.search(
        r"(?:软件|源代码|脚本|算法|规则库|技术框架|知识产权).{0,45}(?:归.+?所有|转让|许可|共有)|"
        r"(?:所有权|知识产权|著作权).{0,45}(?:软件|源代码|脚本|算法|规则库|技术框架)",
        compact,
    ))
    existing_ip_asset_transaction = operative_asset_clause(
        r"(?:既有|已有|现有|原有|背景)?(?:专利权|专利申请权|软件著作权|技术秘密|既有技术|背景知识产权)"
        r"[^。；]{0,80}(?:转让|实施许可|许可使用|再许可|所有权转移|权利交割)|"
        r"(?:转让|实施许可|许可使用|再许可|所有权转移|权利交割)[^。；]{0,80}"
        r"(?:专利权|专利申请权|软件著作权|技术秘密|既有技术|背景知识产权)"
    )
    third_party_component_dependency = operative_asset_clause(
        r"(?:开发软件|交付成果|项目成果)[^。；]{0,45}(?:已经|实际|明确)?"
        r"(?:包含|集成|采用|依赖|使用了)[^。；]{0,35}(?:第三方软件|第三方组件|第三方SDK|开源组件|数据库组件)|"
        r"(?:履行|提供)[^。；]{0,20}(?:技术)?服务[^。；]{0,25}(?:需要)?(?:使用|采用|依赖)"
        r"[^。；]{0,35}(?:第三方软件|第三方组件|第三方SDK|开源组件|第三方数据库组件)|"
        r"(?:已经|实际|明确)(?:包含|集成|采用|依赖|使用)[^。；]{0,35}"
        r"(?:第三方软件|第三方组件|第三方SDK|开源组件|数据库组件)"
    )
    proof_asset_transaction = (
        existing_ip_asset_transaction
        or operative_background_ip_use
        or third_party_component_dependency
    )
    return {
        "source_or_software_delivery": source_delivery,
        "background_ip_use": background_use,
        "operative_background_ip_use": operative_background_ip_use,
        "rights_disposition": rights_disposition,
        "third_party_ip_trigger": bool(third_party["third_party_ip_trigger"]),
        "existing_ip_asset_transaction": existing_ip_asset_transaction,
        "third_party_component_dependency": third_party_component_dependency,
        "proof_asset_transaction": proof_asset_transaction,
        # Proof attachments follow an actual existing-IP disposition or actual
        # third-party component dependency. Future development deliverables,
        # ownership clauses and non-infringement warranties do not suffice.
        "applicable": proof_asset_transaction,
    }


def _is_technology_checkpoint_applicable(contract_text: str, checkpoint: ReviewCheckpoint) -> tuple[Optional[bool], str]:
    compacted_text = _compact(contract_text)
    subtypes = _detect_technology_subtypes(contract_text)
    classification = classify_technology_transaction(contract_text)
    item_id = checkpoint.item_id
    node_id = checkpoint.node_id
    third_party_context = _technology_third_party_context(contract_text)
    ip_proof_context = _technology_ip_proof_context(contract_text)

    if item_id == "TC-13-04":
        explicit_domestic = any(term in compacted_text for term in (
            "双方均为中国境内企业", "仅在中国境内转让", "中国境内交易",
        ))
        explicit_no_cross_border = any(term in compacted_text for term in (
            "不涉及跨境技术进出口", "不涉及技术进出口", "无跨境技术交易",
        ))
        positive_cross_border = _cross_border_technology_transaction_context(contract_text)["present"] or any(term in compacted_text for term in (
            "跨境技术交易", "技术进口合同", "技术出口合同", "境外许可方", "境外受让方",
        )) and not explicit_no_cross_border
        if (explicit_domestic or explicit_no_cross_border) and not positive_cross_border:
            return False, "当前为中国境内技术转让，未出现跨境技术进出口事实，本项不适用。"

    if item_id in {"TC-10-01", "TC-10-02", "TC-10-03", "TC-10-04"} and (
        classification.get("tertiary_subtype") == "PATENT_RIGHT_TRANSFER"
    ):
        continuing_improvement_triggers = (
            "后续改进成果", "改进成果共享", "改进成果许可", "改进成果通知",
            "返授", "优先许可", "合作研发", "共同研发", "持续合作研发",
        )
        if not any(term in compacted_text for term in continuing_improvement_triggers):
            return False, "当前为完整专利权转让，且未出现持续改进、合作研发、返授、优先许可或改进共享事实，本项不适用。"

    if item_id == "TC-01-04":
        # This is a mixed-performance boundary screen, not a rule applicable to
        # every technology contract.  Route it from operative manufacturing /
        # installation / construction duties instead of the primary subtype.
        strong_boundary_terms = (
            "工程施工", "建设工程", "加工定作", "承揽加工", "承揽制造", "定作物",
            "设备制造与交付", "设备安装", "安装施工", "现场施工", "土建工程",
            "装修工程", "竣工验收", "施工图纸",
        )
        operative_boundary = any(term in compacted_text for term in strong_boundary_terms) or bool(
            re.search(
                r"(?:负责|承担|履行内容包括|服务内容包括|工作内容包括).{0,24}"
                r"(?:加工|定作|制造并交付|设备制造|设备安装|现场安装|施工|土建|装修)",
                compacted_text,
            )
        )
        if not operative_boundary:
            transaction_label = {
                "TECHNICAL_CONSULTING": "技术咨询",
                "TECHNICAL_SERVICE": "技术服务",
                "TECHNOLOGY_LICENSE": "技术许可",
                "TECHNOLOGY_TRANSFER": "技术转让",
                "TECHNICAL_DEVELOPMENT": "技术开发",
            }.get(str(classification.get("primary_subtype") or ""), "技术交易")
            return False, f"当前主交易为{transaction_label}，未出现加工、制造、设备安装、施工或建设工程等混合履约事实，本项不适用。"
        return True, "合同出现加工、制造、设备安装、施工或建设工程等混合履约事实，需要核对技术合同与承揽、建设工程规则的边界。"

    if item_id in {"TC-03-01", "TC-03-02", "TC-03-03"}:
        personal_result_triggers = (
            "自然人以个人名义", "员工个人完成", "离职人员", "科研人员与法人", "职务技术成果",
            "非职务技术成果", "完成人署名", "完成人奖励", "个人技术成果", "权利来源不明",
        )
        if any(term in compacted_text for term in personal_result_triggers):
            return True, ""
        return False, "当前合同未出现自然人签约、员工个人成果、职务/非职务成果争议或完成人署名奖励等触发事实。"

    if item_id == "TC-12-01":
        if {"transfer", "license"} & subtypes and any(term in compacted_text for term in ("专利", "技术秘密", "按约实施", "许可实施")):
            return True, ""
        return False, "该规则仅适用于受让人或被许可人按约实施现有专利、技术秘密的交易。"

    if item_id == "TC-06-04" and classification.get("tertiary_subtype") == "TECHNICAL_SECRET_TRANSFER":
        if any(term in compacted_text for term in ("技术合同认定登记", "登记备案", "备案手续", "权利变更手续")):
            return True, "技术秘密转让不当然发生专利式权利登记，但合同已约定技术合同认定登记、备案或权利变更手续，需要审查其办理安排。"
        return False, "当前标的是技术秘密而非登记型专利权，且合同未约定需要办理的认定登记、备案或权利变更手续，本项不适用。"

    if item_id in {"TC-10-01", "TC-10-02", "TC-10-03", "TC-10-04"} and "consulting" in subtypes:
        return False, "当前技术咨询交易未出现技术转让、技术许可、后续返授、改进共享、优先权或其他持续技术权益安排，本项不适用。"

    if item_id in {"TC-10-01", "TC-10-02", "TC-10-03", "TC-10-04"} and "service" in subtypes and not ({"development", "transfer", "license"} & subtypes):
        return False, "当前技术服务交易仅涉及服务过程中形成的新成果归属，未出现技术转让、技术许可、返授、改进共享、优先权或其他持续技术权益安排，后续改进控制规则不适用。"

    if item_id in {"TC-10-03", "TC-10-04"} and not ({"development", "transfer", "license"} & subtypes):
        return False, "当前技术服务交易不涉及技术开发、技术转让或技术许可项下的后续改进控制，本项不适用。"

    if item_id in {"TC-03-04", "TC-13-02"} and "consulting" in subtypes:
        if not ip_proof_context["applicable"]:
            return False, "当前纯技术咨询交易仅交付分析、评价意见和咨询报告，未触发既有软件、专利、技术秘密许可或第三方组件的权属证明审查。"
        return True, "合同事实涉及软件或源代码交付、背景技术使用、知识产权处分或第三方技术依赖，触发权属证明审查。"

    if item_id in {"TC-03-04", "TC-13-02"} and "service" in subtypes:
        if not ip_proof_context["proof_asset_transaction"]:
            return False, "当前技术服务交易未出现既有专利、软件著作权、技术秘密等知识产权资产的转让或许可，也未出现第三方软件、代码组件或开源许可依赖，转让/许可型权属证明附件规则不适用。"
        return True, "合同存在既有知识产权资产转让/许可或第三方软件组件授权依赖，触发相应权属及授权链证明审查。"

    if item_id in {"TC-03-04", "TC-13-02"}:
        if classification.get("primary_subtype") in {"TECHNOLOGY_TRANSFER", "TECHNOLOGY_LICENSE"}:
            return True, "当前主交易实际处分既有技术或知识产权资产，触发与该交易标的相匹配的权属及授权证明审查。"
        if not ip_proof_context["proof_asset_transaction"]:
            return False, (
                "当前合同仅涉及未来研发成果交付、成果归属或不侵权保证，未出现既有专利、软件著作权、"
                "技术秘密等资产的实际转让/许可，也未确认第三方软件或开源组件已经纳入交付，权属证明附件规则不适用。"
            )
        return True, "合同存在既有知识产权资产处分或已纳入交付的第三方组件授权依赖，触发权属证明附件审查。"

    if item_id == "TC-12-02" and "consulting" in subtypes:
        third_party_ip_triggers = (
            "第三方受保护内容", "第三方软件", "源代码交付", "专利技术", "技术秘密许可",
            "第三方技术许可", "知识产权权利保证", "第三方权利争议", "第三方权利主张",
            "侵权通知", "可直接实施的第三方",
        )
        if not any(term in compacted_text for term in third_party_ip_triggers):
            return False, "当前纯技术咨询成果为分析、评价意见和咨询报告，未出现第三方软件、代码、专利、技术秘密许可或已知权利争议，本项不适用。"

    if item_id == "TC-12-02" and "service" in subtypes and not third_party_context["third_party_ip_trigger"]:
        return False, "合同仅出现第三方服务人员、分包或转委托主体，不存在第三方软件、代码、专利、技术秘密许可、授权依赖或权利主张事实，第三方知识产权主张处理规则不适用。"

    if item_id == "TC-12-04" and "consulting" in subtypes:
        infringement_liability_triggers = (
            "侵权专项责任", "侵犯第三方知识产权", "知识产权侵权", "权利瑕疵责任",
            "第三方权利责任", "无权许可", "侵权赔偿",
        )
        if not any(term in compacted_text for term in infringement_liability_triggers):
            return False, "当前技术咨询合同未约定侵权专项责任、权利瑕疵责任或第三方权利责任，不存在与一般救济衔接的审查基础。"

    if item_id == "TC-13-01" and "consulting" in subtypes:
        attachment_or_list_trigger = any(term in compacted_text for term in (
            "技术资料清单", "图纸清单", "设计资料清单", "交付文件清单", "附件清单",
            "作为本合同附件", "作为合同组成部分", "详见附件", "相关技术资料",
        ))
        if not attachment_or_list_trigger:
            return False, "当前技术咨询交易已在正文明确咨询范围和报告交付，未出现需由附件固定的复杂技术资料清单或笼统资料交付义务，本项不适用。"

    if item_id == "TC-12-04" and "service" in subtypes:
        infringement_liability = any(term in compacted_text for term in (
            "侵权专项责任", "侵犯第三方知识产权", "知识产权侵权责任", "权利瑕疵责任",
            "第三方权利责任", "无权许可责任", "侵权赔偿",
        ))
        general_remedies = any(term in compacted_text for term in (
            "一般损失赔偿", "违约金", "退款", "继续履行", "责任限制", "累计责任",
        ))
        if not (infringement_liability and general_remedies):
            return False, "当前技术服务合同未同时形成侵权/权利瑕疵专项责任与一般合同救济，不存在两类救济适用顺序或累计关系的审查基础。"

    if item_id == "TC-13-03" and "consulting" in subtypes:
        test_triggers = (
            "实验测试", "性能测试", "设备验证", "第三方检测", "实物测试", "测试数据集",
            "测试用例", "复测",
        )
        if not any(term in compacted_text for term in test_triggers):
            return False, "当前交付物为技术咨询报告，未约定实验、性能、设备、实物或第三方检测，软件开发式验收测试附件规则不适用。"

    if item_id == "TC-13-03" and "service" in subtypes:
        independent_test_triggers = (
            "性能测试", "压力测试", "设备检测", "实验验证", "测试数据集", "测试用例",
            "第三方检测", "第三方复测", "技术指标复测", "验收抽样规则", "测试样本",
        )
        if not any(term in compacted_text for term in independent_test_triggers):
            return False, "当前合同未出现性能测试、压力测试、设备检测、第三方检测、测试数据集或测试样本等独立测试性交付事实，专项验收测试附件规则不适用。"

    if item_id == "TC-12-03":
        if classification.get("tertiary_subtype") == "TECHNICAL_SECRET_TRANSFER":
            return True, "当前主交易即为技术秘密转让，技术秘密丧失秘密性后的继续使用、费用和解除边界属于核心审查事项。"
        secret_facts = dict((classification.get("structured_facts") or {}).get("technical_secret") or {})
        if secret_facts.get("scope") and (secret_facts.get("restricted_use") or secret_facts.get("separate_fee")):
            return True, "主交易虽为专利许可，但合同同时存在技术秘密范围、限制使用或独立对价事实，技术秘密附属规则适用。"
        secret_transaction = bool(re.search(r"(?:技术秘密转让|技术秘密许可).{0,30}(?:价款|使用费|所有权|许可)", compacted_text))
        excluded_secret_transfer = bool(re.search(r"(?:不包含|不涉及).{0,12}技术秘密.{0,12}转让|技术秘密转让价款为0元", compacted_text))
        if not secret_transaction or excluded_secret_transfer:
            explicit_secret_scope = bool(
                re.search(r"技术秘密(?:（?Know-how）?)?.{0,100}(?:控制参数|标定数据|实验数据|工程经验|调试方法)", compacted_text, re.I)
                or sum(term in compacted_text for term in ("技术秘密", "保密义务", "返还", "销毁")) >= 3
            )
            if explicit_secret_scope:
                return False, (
                    "合同已明确技术秘密范围并设置保密、限制使用或资料处置安排，但未形成以技术秘密秘密性为独立对价基础的"
                    "持续收费或秘密性丧失后的费用安排，因此本项不适用。"
                )
            return False, "当前合同未形成可识别的技术秘密范围、限制使用或独立对价事实，技术秘密丧失秘密性后的使用与费用处理规则不适用。"

    if item_id == "TC-13-03" and not ({"development", "consulting", "service"} & subtypes):
        has_acceptance_test_facts = (
            any(term in compacted_text for term in (
                "验收", "验收合格", "验收标准", "验收期限", "书面异议",
            ))
            and any(term in compacted_text for term in (
                "测试环境", "测试数据", "测试样本", "测试方法", "测试方案",
                "技术指标", "性能指标", "测试版本", "测试报告", "复测",
            ))
        )
        # Technical-secret transfer and licence contracts may carry an actual
        # testing/acceptance module even though testing is not the main trade.
        if has_acceptance_test_facts and classification.get("tertiary_subtype") in {
            "TECHNICAL_SECRET_TRANSFER", "TECHNICAL_SECRET_LICENSE",
        }:
            return True, (
                "主交易虽非研发或技术服务，但合同实际包含可量化技术指标、测试环境或测试资料及验收义务，"
                "验收测试附件和证据文件完整性规则按事实适用。"
            )
        transaction_label = {
            "TECHNOLOGY_LICENSE": "专利实施许可" if classification.get("tertiary_subtype") == "PATENT_LICENSE" else "技术许可",
            "TECHNOLOGY_TRANSFER": "专利权转让" if classification.get("tertiary_subtype") == "PATENT_RIGHT_TRANSFER" else "技术转让",
            "COOPERATIVE_DEVELOPMENT": "合作开发",
            "ENTRUSTED_DEVELOPMENT": "委托开发",
            "TECHNICAL_CONSULTING": "技术咨询",
            "TECHNICAL_SERVICE": "技术服务",
        }.get(str(classification.get("primary_subtype") or ""), "技术合同")
        return False, f"统一分类结果确认当前主交易为{transaction_label}，不以研发、咨询或技术服务成果验收为核心，验收测试附件规则不适用。"

    if node_id == "technology_contract_type_classification":
        if (classification.get("contract_type_conflict") or {}).get("exists"):
            return True, "合同标题与核心权利处分条款指向不同交易性质，适用合同性质冲突审查。"
        known_subtypes = {"development", "transfer", "license", "consulting", "service"} & subtypes
        return (False, _technology_subtype_reason(subtypes, checkpoint)) if known_subtypes else (True, "")

    if node_id == "fraud_contract_existing_technology":
        triggered = "EXISTING_TECHNOLOGY_AS_DEVELOPMENT_RISK" in (classification.get("factual_triggers") or [])
        return (True, "") if triggered else (False, "未发现将现有技术冒充新研发成果或重复收费的明确风险事实。")

    if node_id == "research_organization_authorization":
        triggered = "RESEARCH_ORGANIZATION_AUTHORITY_RISK" in (classification.get("factual_triggers") or [])
        return (True, "") if triggered else (False, "合同签约方未表现为课题组、实验室或研究中心等内部机构，未触发科研组织授权签约审查。")

    if item_id.startswith("TC-04"):
        if "entrusted_development" in subtypes and "cooperative_development" not in subtypes:
            return True, ""
        return False, _technology_subtype_reason(subtypes, checkpoint)

    if item_id.startswith("TC-05"):
        if node_id == "technical_secret_result_rights":
            return (True, "") if "development" in subtypes else (False, _technology_subtype_reason(subtypes, checkpoint))
        if node_id == "cooperation_breach_and_exit":
            return (True, "") if "development" in subtypes else (False, _technology_subtype_reason(subtypes, checkpoint))
        if "cooperative_development" in subtypes:
            return True, ""
        return False, _technology_subtype_reason(subtypes, checkpoint)

    subtype_by_prefix = {
        "TC-06": "transfer",
        "TC-07": "license",
        "TC-08": "consulting",
        "TC-09": "service",
    }
    for prefix, subtype in subtype_by_prefix.items():
        if item_id.startswith(prefix):
            if prefix == "TC-09" and "technical_service" in set(classification.get("sub_transactions") or []):
                transaction_label = "技术许可" if classification.get("primary_subtype") == "TECHNOLOGY_LICENSE" else "技术转让"
                return True, f"合同主交易为{transaction_label}，同时存在独立技术服务、培训、验收或费用事实，TC-09附属模块适用。"
            return (True, "") if subtype in subtypes else (False, _technology_subtype_reason(subtypes, checkpoint))

    if node_id == "technology_import_export_control":
        return (True, "") if "import_export" in subtypes else (False, _technology_subtype_reason(subtypes, checkpoint))

    return None, ""


def _service_has_fixed_completion_structure(compacted: str) -> bool:
    if any(term in compacted for term in ("无固定期限", "未约定固定期限", "没有固定期限", "无固定服务期限")):
        return False
    fixed_terms = (
        "服务期限", "合同期限", "培训期限", "课程期限", "开课日期", "结课日期", "结束日期",
        "总课时", "课时", "一次性", "固定期限", "固定课程", "完成后", "交付后",
    )
    date_range = bool(
        re.search(r"(?:自|从).{0,16}(?:至|到|截至|截止)", compacted)
        or re.search(r"(?:开课|开始).{0,12}(?:结课|结束|完成)", compacted)
        or re.search(r"\d+\s*(?:课时|次|节)", compacted)
    )
    return date_range or any(term in compacted for term in fixed_terms)


def _service_has_continuing_indefinite_structure(compacted: str) -> bool:
    return any(
        term in compacted
        for term in (
            "不定期服务", "长期服务", "持续服务", "连续服务", "自动续费", "自动续约",
            "会员有效期届满后继续", "随时解除", "按月服务", "长期持续", "无固定期限",
        )
    )


def _service_has_platform_structure(compacted: str) -> bool:
    platform_terms = ("平台", "用户协议", "平台规则", "在线服务", "小程序", "APP", "app", "网站", "平台条款", "规则更新")
    account_terms = ("账号", "账户")
    has_platform = any(term in compacted for term in platform_terms)
    has_account_only = any(term in compacted for term in account_terms) and not has_platform
    if has_account_only:
        return False
    return has_platform and any(
        term in compacted
        for term in ("用户协议", "平台规则", "平台条款", "规则更新", "重大权益", "自动续费", "账号", "账户")
    )


def _service_has_format_clause_trigger(compacted: str) -> bool:
    public_template = any(term in compacted for term in ("示范文本", "政府发布", "协会发布", "公开范本"))
    negotiated = any(term in compacted for term in ("双方协商填写", "双方协商一致", "逐条协商", "可协商修改"))
    prepared_by_one_party = any(term in compacted for term in ("服务方提供", "经营者提供", "甲方提供", "乙方提供", "一方预先拟定"))
    non_negotiable = any(term in compacted for term in ("不可修改", "不得修改", "重复使用", "未与对方协商", "无权修改"))
    restrictive = any(term in compacted for term in ("免除责任", "限制责任", "加重责任", "排除主要权利", "概不退款", "不予退费", "单方变更", "最终解释权"))
    if public_template and negotiated and not (prepared_by_one_party and non_negotiable and restrictive):
        return False
    return (prepared_by_one_party and non_negotiable and restrictive) or ("格式条款" in compacted and restrictive)


_CONSUMER_SERVICE_CONTEXT_NODES = {
    "prepaid_consumption_identification",
    "prepaid_amount_and_balance",
    "prepaid_refund_condition_process",
    "prepaid_partly_provided_refund",
    "health_change_termination",
    "consumer_termination_notice",
    "operator_closure_refund",
    "business_transfer_continuity",
    "consumer_personal_reason_termination",
    "consumer_cooperation_obligation",
    "reasonable_loss_deduction",
    "consumer_excessive_penalty_clause",
    "punitive_damages_closure",
    "prepaid_fund_security",
    "refund_service_contact",
    "closure_notice_obligation",
}


def _is_service_checkpoint_applicable(
    compacted: str,
    checkpoint: ReviewCheckpoint,
    consumer_context: Optional[Dict[str, Any]] = None,
) -> tuple[Optional[bool], str]:
    context = consumer_context or {}
    if checkpoint.node_id in _CONSUMER_SERVICE_CONTEXT_NODES and not any((
        context.get("is_consumer_transaction"),
        context.get("is_prepaid_service"),
        context.get("is_training_primary_transaction"),
    )):
        return False, "未形成消费者、预付式或以培训为主交易的服务语境；附随培训/支持不触发消费者服务规则。"
    condition_text = f"{checkpoint.node_id} {checkpoint.title} {checkpoint.applicable_if}"
    nature = getattr(checkpoint, "review_nature", "CONTRACTUAL_REQUIREMENT")
    if nature == "CONDITIONAL_REQUIREMENT" and any(term in condition_text for term in ("不定期", "长期持续", "继续性服务")):
        if _service_has_continuing_indefinite_structure(compacted) and not _service_has_fixed_completion_structure(compacted):
            return True, "合同体现无固定完成节点或长期持续服务结构，适用不定期继续性服务解除审查。"
        if _service_has_fixed_completion_structure(compacted):
            return False, "合同已体现固定课程、固定课时、明确期限或完成节点，不属于不定期继续性服务。"
        return False, "未发现无固定期限、长期持续履行或无完成节点的服务结构。"
    if nature == "CONDITIONAL_REQUIREMENT" and "平台" in condition_text:
        if _service_has_platform_structure(compacted):
            return True, "合同体现平台、用户协议、账号或平台规则等事实，适用平台条款变更审查。"
        return False, "未发现互联网平台、用户协议、平台规则或平台单方更新机制。"
    if checkpoint.node_id == "format_clause_prompt_explain":
        if _service_has_format_clause_trigger(compacted):
            return True, "合同存在格式条款提示说明的触发事实。"
        return False, "未确认存在一方预先拟定、重复使用且限制责任或排除主要权利的格式条款。"
    return None, ""


def _is_checkpoint_applicable(
    contract_text: str,
    checkpoint: ReviewCheckpoint,
    contract_type_key: str,
    canonical_claims: Optional[Dict[str, Any]] = None,
    classification_context: Optional[Dict[str, Any]] = None,
) -> tuple[bool, str]:
    # Applicability must be resolved before Coverage.
    if checkpoint.applicability_triggers:
        claims = canonical_claims or {}
        resolved = [claims.get(trigger) for trigger in checkpoint.applicability_triggers]
        conflicts = [claim for claim in resolved if claim is not None and claim.status == "CONFLICT"]
        if conflicts or any(claim is None or claim.status == "UNKNOWN" for claim in resolved):
            return False, f"触发事实不足，暂不确定是否适用：{', '.join(checkpoint.applicability_triggers)}。"
        if all(bool(claim.object) for claim in resolved):
            return True, f"触发事实已满足：{', '.join(checkpoint.applicability_triggers)}。"
        return False, f"触发事实明确不成立：{', '.join(checkpoint.applicability_triggers)}。"
    applicability_text = _construction_contract_body(contract_text) if contract_type_key == "construction" else contract_text
    compacted = _compact(applicability_text)
    if contract_type_key == "technology":
        applicable, reason = _is_technology_checkpoint_applicable(applicability_text, checkpoint)
        if applicable is not None:
            return applicable, reason
    if contract_type_key == "service":
        applicable, reason = _is_service_checkpoint_applicable(
            compacted,
            checkpoint,
            (classification_context or {}).get("consumer_service_context") or {},
        )
        if applicable is not None:
            return applicable, reason

    keywords = _CONTRACT_APPLICABILITY_KEYWORDS.get(contract_type_key, {}).get(checkpoint.node_id)
    if not keywords:
        return True, ""

    if contract_type_key == "guarantee" and checkpoint.node_id == "post_period_signature_new_guarantee":
        period_triggered = any(
            _has_unnegated_word(compacted, keyword, window=18)
            for keyword in ("保证期间届满", "期间届满后", "保证期间届满后")
        )
        signature_triggered = any(
            _has_unnegated_word(compacted, keyword, window=18)
            for keyword in ("催收通知签字", "催收通知上签字", "签字", "签收", "重新保证", "新的保证合同", "继续承担保证责任", "责任恢复")
        )
        if period_triggered and signature_triggered:
            return True, "合同文本同时出现保证期间届满后和催收签字/重新保证类表述，适用该专项审查点。"
        return False, f"未发现保证期间届满后催收签字或重新保证的组合情形：{checkpoint.applicable_if}"

    if checkpoint.node_id == "sale_installment_payment" and _has_installment_pattern(compacted):
        return True, "合同文本出现分期付款结构，适用该专项审查点。"
    if checkpoint.node_id == "common_format_clause_notice":
        public_template = any(term in compacted for term in ("示范文本", "政府发布", "协会发布", "公开范本"))
        negotiated = any(term in compacted for term in ("双方协商填写", "双方协商一致", "逐条协商", "可协商修改"))
        prepared_by_one_party = any(term in compacted for term in ("卖方提供", "买方提供", "甲方提供", "乙方提供", "一方预先拟定"))
        non_negotiable = any(term in compacted for term in ("不可修改", "不得修改", "重复使用", "未与对方协商", "无权修改"))
        restrictive = any(term in compacted for term in ("免除责任", "限制责任", "加重责任", "排除主要权利", "不承担任何"))
        if public_template and negotiated and not (prepared_by_one_party and non_negotiable):
            return False, "公开示范文本且合同记载双方协商填写，不能仅因文件具有范本外观推定为一方提供的格式条款。"
        if prepared_by_one_party and non_negotiable and restrictive:
            return True, "合同存在一方预先提供、缺乏实质协商且限制责任或权利的重要条款，触发格式条款提示说明审查。"
        return False, "仅能确认文本具有模板或范本外观，不能确认一方预先拟定、重复使用及缺乏实质协商；适用性暂不确定。"
    if checkpoint.node_id == "sale_risk_goods_in_transit":
        transit_sale_patterns = (
            "路货买卖",
            "在途货物交易",
            "买卖在途货物",
            "买卖运输途中的标的物",
            "已经发运正在运输途中的货物",
            "发运后转卖",
            "运输途中转卖",
        )
        composite_trigger = (
            "买卖" in compacted
            and any(term in compacted for term in ("已发运", "已经发运"))
            and any(term in compacted for term in ("运输途中", "正在运输途中", "在途货物"))
        )
        if composite_trigger or any(_has_unnegated_word(compacted, pattern, window=18) for pattern in transit_sale_patterns):
            return True, "合同明确涉及已发运或运输途中货物的转售，适用路货买卖专项审查。"
        return False, "普通运输交付不等于路货买卖；未发现已发运后转卖或运输途中买卖的触发事实。"
    if checkpoint.node_id == "sale_sample_quality":
        legal_sample_sale = any(
            phrase in compacted
            for phrase in ("凭样品买卖", "按样品交付", "按封样样品交付", "样品作为交付标准", "样品质量标准", "以样品为准")
        )
        if legal_sample_sale:
            return True, "合同明确以样品作为买卖标的质量或交付标准，适用凭样品买卖专项审查。"
        return False, "技术封样或承认书仅是质量标准证据，不当然构成凭样品买卖。"
    for keyword in keywords:
        if _has_unnegated_word(compacted, keyword, window=18):
            return True, f"合同文本出现“{keyword}”，适用该专项审查点。"
    return False, f"未发现触发该专项审查点的交易类型表述：{checkpoint.applicable_if}"


def _applicability_result_for_checkpoint(
    checkpoint: ReviewCheckpoint,
    clauses: List[Any],
    applicable: bool,
    reason: str,
    canonical_claims: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    conditional = bool(checkpoint.applicable_if)
    trigger_terms = list(_CONTRACT_APPLICABILITY_KEYWORDS.get("sale", {}).get(checkpoint.node_id, ()))
    required_triggers = list(checkpoint.applicability_triggers) or trigger_terms
    if checkpoint.node_id == "common_format_clause_notice":
        trigger_terms = [
            "卖方提供", "买方提供", "甲方提供", "乙方提供", "一方预先拟定",
            "不可修改", "不得修改", "重复使用", "未与对方协商", "限制责任", "免除责任",
        ]
    trigger_evidence = []
    trigger_facts = []
    for clause in clauses:
        matched = [term for term in trigger_terms if term and term in _compact(clause.text)]
        if not matched:
            continue
        trigger_facts.extend(matched)
        trigger_evidence.append({
            "clause_id": clause.clause_id,
            "location": clause.location,
            "quote": clause.text[:260],
            "block_type": clause.block_type,
        })
    uncertain = conditional and not applicable and "暂不确定" in reason
    status = "UNCERTAIN" if uncertain else "APPLICABLE" if applicable else "NOT_APPLICABLE"
    confidence = "low" if uncertain else "high" if (trigger_evidence or not conditional) else "medium"
    claim_rows = [canonical_claims.get(trigger) for trigger in checkpoint.applicability_triggers if canonical_claims and canonical_claims.get(trigger)]
    satisfied = [claim.claim_id for claim in claim_rows if bool(claim.object) and claim.status != "CONFLICT"]
    unsatisfied = [trigger for trigger in checkpoint.applicability_triggers if trigger not in satisfied]
    conflicting = [claim.claim_id for claim in claim_rows if claim.status == "CONFLICT"]
    claim_evidence_ids = [evidence_id for claim in claim_rows for evidence_id in claim.evidence_ids]
    return ApplicabilityResult(
        review_id=checkpoint.item_id,
        applicable=None if uncertain else applicable,
        trigger_facts=list(dict.fromkeys(trigger_facts)),
        trigger_evidence=trigger_evidence,
        missing_triggers=[] if applicable else trigger_terms,
        reason=reason or "未声明条件审查规则，默认适用于当前合同。",
        confidence=confidence,
        status=status,
        machine_reason=reason or "未声明条件审查规则，默认适用于当前合同。",
        user_reason=(
            f"现有合同信息不足以确认是否满足“{checkpoint.applicable_if}”，需结合相关材料核对。"
            if uncertain else
            reason
            if checkpoint.item_id in {"TC-03-04", "TC-13-02"} and reason else
            f"合同已触发“{checkpoint.applicable_if}”这一适用条件。"
            if conditional and applicable else
            (
                reason
                if checkpoint.item_id.startswith("TC-") and reason
                else f"合同未触发“{checkpoint.applicable_if}”这一适用条件，本审查事项不适用。"
            )
            if conditional else
            "该审查事项适用于当前合同。"
        ),
        required_triggers=required_triggers,
        satisfied_triggers=satisfied,
        unsatisfied_triggers=unsatisfied,
        conflicting_triggers=conflicting,
        trigger_fact_ids=[fact_id for claim in claim_rows for fact_id in claim.fact_ids],
        trigger_evidence_ids=claim_evidence_ids,
    ).to_public_dict()


def _get_fact_path_value(facts: Any, path: str) -> Any:
    value: Any = facts
    for part in path.split("."):
        if value is None:
            return None
        if isinstance(value, dict):
            value = value.get(part)
        else:
            value = getattr(value, part, None)
    return value


def _compare_applicability_value(actual: Any, operator: str, expected: Any = None) -> bool:
    if operator == "exists":
        return actual is not None and actual is not False
    if operator == "not_exists":
        return actual is None or actual is False
    if operator == "eq":
        return actual == expected
    if operator == "neq":
        return actual != expected
    if operator == "in":
        return actual in (expected or [])
    if operator in {"gt", "gte", "lt", "lte"}:
        if actual is None or expected is None:
            return False
        try:
            actual_num = float(actual)
            expected_num = float(expected)
        except (TypeError, ValueError):
            return False
        return {
            "gt": actual_num > expected_num,
            "gte": actual_num >= expected_num,
            "lt": actual_num < expected_num,
            "lte": actual_num <= expected_num,
        }[operator]
    return True


def _evaluate_applicability_condition(expr: Dict[str, Any], facts: HouseLeaseContractFacts) -> tuple[bool, List[str], List[Dict[str, Any]]]:
    if "all" in expr:
        evaluations: List[Dict[str, Any]] = []
        depends_on: List[str] = []
        results = []
        for child in expr.get("all") or []:
            result, child_depends, child_evals = _evaluate_applicability_condition(child, facts)
            results.append(result)
            depends_on.extend(child_depends)
            evaluations.extend(child_evals)
        return all(results), list(dict.fromkeys(depends_on)), evaluations
    if "any" in expr:
        evaluations = []
        depends_on = []
        results = []
        for child in expr.get("any") or []:
            result, child_depends, child_evals = _evaluate_applicability_condition(child, facts)
            results.append(result)
            depends_on.extend(child_depends)
            evaluations.extend(child_evals)
        return any(results), list(dict.fromkeys(depends_on)), evaluations
    if "not" in expr:
        result, depends_on, evaluations = _evaluate_applicability_condition(expr.get("not") or {}, facts)
        return (not result), depends_on, evaluations

    fact_path = expr.get("fact", "")
    operator = expr.get("operator", "exists")
    expected = expr.get("value")
    actual = _get_fact_path_value(facts, fact_path)
    passed = _compare_applicability_value(actual, operator, expected)
    return passed, [fact_path] if fact_path else [], [
        {
            "fact": fact_path,
            "operator": operator,
            "expected": expected,
            "actual": actual,
            "passed": passed,
        }
    ]


def _evaluate_applicability_rule(rule: Dict[str, Any], facts: HouseLeaseContractFacts) -> tuple[bool, List[str], List[Dict[str, Any]]]:
    if "applicability" in rule:
        return _evaluate_applicability_condition(rule.get("applicability") or {}, facts)
    conditions = rule.get("conditions") or []
    evaluations: List[Dict[str, Any]] = []
    depends_on: List[str] = []
    for condition in conditions:
        fact_path = condition.get("fact", "")
        operator = condition.get("operator", "exists")
        expected = condition.get("value")
        actual = _get_fact_path_value(facts, fact_path)
        passed = _compare_applicability_value(actual, operator, expected)
        depends_on.append(fact_path)
        evaluations.append(
            {
                "fact": fact_path,
                "operator": operator,
                "expected": expected,
                "actual": actual,
                "passed": passed,
            }
        )
    logic = (rule.get("logic") or "AND").upper()
    applicable = any(item["passed"] for item in evaluations) if logic == "OR" else all(item["passed"] for item in evaluations)
    return applicable, depends_on, evaluations


def _evaluate_lease_fact_applicability(checkpoint: ReviewCheckpoint, facts: HouseLeaseContractFacts) -> Dict[str, Any]:
    """Fact-driven applicability for mutually exclusive house-lease checkpoints."""
    rule = LEASE_APPLICABILITY_RULES.get(checkpoint.item_id)
    if rule:
        applicable, depends_on, evaluations = _evaluate_applicability_rule(rule, facts)
        machine_reason = rule["applicable_reason"] if applicable else rule["not_applicable_reason"]
        condition_label = checkpoint.applicable_if or checkpoint.title
        return {
            "status": "applicable" if applicable else "not_applicable",
            "applicable": applicable,
            "reason": machine_reason,
            "machine_reason": machine_reason,
            "user_reason": (
                f"合同现有安排满足“{condition_label}”的审查条件。"
                if applicable else
                f"合同现有安排不满足“{condition_label}”这一适用条件，本审查事项不适用。"
            ),
            "depends_on": depends_on,
            "evaluations": evaluations,
        }
    return {
        "status": "applicable",
        "applicable": True,
        "reason": "未触发事实层排除条件，继续执行审查。",
        "machine_reason": "未触发事实层排除条件，继续执行审查。",
        "user_reason": "该审查事项适用于当前合同。",
        "depends_on": [],
    }


def _not_applicable_item(checkpoint: ReviewCheckpoint, reason: str) -> ReviewItemResult:
    item = ReviewItemResult(
        item_id=checkpoint.item_id,
        node_id=checkpoint.node_id,
        title=checkpoint.title,
        risk_level=NotApplicableRisk(),
        status="不适用",
        risk_point_description="该审查点仅适用于特定交易场景，当前合同文本未触发对应适用条件。",
        suggested_clause_example=checkpoint.suggested_clause,
        legal_basis_index=checkpoint.legal_basis,
        legal_consequence_if_missing=checkpoint.legal_consequence_if_missing,
        applicable_if=checkpoint.applicable_if,
        matched_terms=[],
        coverage_status=COVERAGE_NOT_APPLICABLE,
        issue_type=ISSUE_NOT_APPLICABLE,
        evidence_clauses=[],
        evidence_location="",
        reasoning_summary=reason,
        judge_source="applicability_filter",
    )
    item.applicability = {
        "status": "not_applicable", "applicable": False, "reason": reason,
        "machine_reason": reason, "user_reason": _user_facing_reasoning(reason), "depends_on": [],
    }
    item.action_suggestion = "不适用"
    return item


def _insufficient_context_item(checkpoint: ReviewCheckpoint, reason: str) -> ReviewItemResult:
    generic_reason = "现有合同材料不足以确认该事项是否适用，建议结合相关交易背景或补充材料核对。"
    specific_reason = (reason or "").strip()
    user_reason = specific_reason if specific_reason else generic_reason
    item = ReviewItemResult(
        item_id=checkpoint.item_id,
        node_id=checkpoint.node_id,
        title=checkpoint.title,
        risk_level="中",
        status="需人工复核",
        risk_point_description=user_reason,
        suggested_clause_example="",
        legal_basis_index=checkpoint.legal_basis,
        legal_consequence_if_missing=user_reason,
        applicable_if=checkpoint.applicable_if,
        matched_terms=[],
        coverage_status=INSUFFICIENT_CONTEXT,
        issue_type="人工复核",
        evidence_clauses=[],
        evidence_location="",
        reasoning_summary=user_reason,
        judge_source="applicability_filter",
        needs_manual_review=True,
        quality_gate_failure_reason=user_reason,
    )
    item.applicability = {
        "status": INSUFFICIENT_CONTEXT,
        "applicable": None,
        "reason": reason or user_reason,
        "machine_reason": reason or user_reason,
        "user_reason": user_reason,
        "depends_on": [],
    }
    item.action_priority = DISPOSITION_MANUAL_REVIEW
    item.review_priority = DISPOSITION_MANUAL_REVIEW
    item.action_suggestion = "建议人工复核"
    item.decision_trace["insufficient_context"] = {
        "reason": user_reason,
        "review_instruction": user_reason,
        "missing_context": specific_reason or "未提供足以确认适用性的交易背景或附件材料。",
    }
    return item


def _checkpoint_metadata(checkpoint: ReviewCheckpoint) -> Dict[str, Any]:
    return {
        "review_mode": "ABSENCE_REQUIRED" if checkpoint.kind == "forbidden" else "PRESENCE_REQUIRED",
        "review_polarity": checkpoint.polarity,
        "review_nature": getattr(checkpoint, "review_nature", "CONTRACTUAL_REQUIREMENT"),
        "requirement_medium": getattr(checkpoint, "requirement_medium", "CONTRACT_TEXT"),
        "legal_requirement_strength": getattr(checkpoint, "legal_requirement_strength", "RISK_CONTROL"),
        "action_type": getattr(checkpoint, "action_type", "CONTRACT_EDIT"),
        "domain_owner": checkpoint.domain_owner,
        "material_group": checkpoint.material_group,
        "allowed_subject_matters": list(checkpoint.allowed_subject_matters),
        "satisfaction_semantics": {
            "polarity": checkpoint.polarity,
            "pass_meaning": "NO_ADVERSE_CLAUSE_FOUND" if checkpoint.polarity == "NEGATIVE_CLAUSE_CHECK" else "REQUIRED_PROTECTION_PRESENT",
            "partial_meaning": "REQUIRES_FURTHER_REVIEW",
            "missing_meaning": "REQUIRED_PROTECTION_ABSENT",
            "risk_meaning": "ADVERSE_CLAUSE_FOUND",
            "not_applicable_meaning": "TRIGGER_NOT_PRESENT",
        },
    }


def _apply_checkpoint_metadata(
    items: List[ReviewItemResult],
    checklist: Sequence[ReviewCheckpoint],
    searched_scope: Optional[List[str]] = None,
) -> None:
    checkpoint_by_id = {row.item_id: row for row in checklist}
    searched = list(searched_scope or [])
    for item in items:
        checkpoint = checkpoint_by_id.get(item.item_id)
        if not checkpoint:
            continue
        classification_ontology = bool((item.decision_trace or {}).get("classification_ontology_check"))
        negative_check_basis = dict((item.decision_trace or {}).get("negative_check_basis") or {})
        item.decision_trace.update(_checkpoint_metadata(checkpoint))
        if classification_ontology:
            item.decision_trace["review_nature"] = "INTERNAL_CLASSIFICATION"
        if negative_check_basis:
            item.decision_trace["review_mode"] = "ABSENCE_REQUIRED"
            item.decision_trace["review_polarity"] = "NEGATIVE_CLAUSE_CHECK"
        if checkpoint.polarity == "NEGATIVE_CLAUSE_CHECK" or negative_check_basis:
            adverse_candidates = list(item.evidence_clauses or []) if item.coverage_status == "风险条款" else []
            search_sufficient = bool(searched) or item.coverage_status in {"通过", "风险条款"}
            item.decision_trace["negative_clause_check"] = {
                "review_id": item.item_id,
                "searched_scope": searched,
                "candidate_adverse_clauses": adverse_candidates,
                "counter_evidence": [],
                "search_coverage": "SUFFICIENT" if search_sufficient else "INSUFFICIENT",
                "adverse_clause_exists": bool(adverse_candidates),
                "confidence": "high" if search_sufficient else "low",
                "coverage_result": item.coverage_status,
            }


def _mark_internal_classification_item(item: ReviewItemResult, reason: str) -> None:
    item.risk_level = "低"
    item.status = "已完成内部法律定性"
    item.coverage_status = "通过"
    item.issue_type = "通过"
    item.risk_point_description = "该审查点用于系统内部法律定性，不因合同未单列分类表述而形成合同缺陷。"
    item.legal_consequence_if_missing = "该事项属于内部法律定性结果，不构成独立合同缺口。"
    item.reasoning_summary = reason
    item.action_priority = ACTION_PRIORITY_NONE
    item.review_priority = ACTION_PRIORITY_NONE
    item.action_suggestion = "无需处理"
    item.risk_severity = SEVERITY_NONE
    item.residual_risk = "内部法律定性已完成，不形成独立风险。"
    item.related_risks = []
    item.decision_trace["internal_classification_result"] = {
        "status": "CLASSIFIED",
        "confidence": "high",
        "reason": reason,
        "risk_entity_created": False,
        "formal_recommendation_allowed": False,
        "final_disposition_allowed": False,
    }


def _apply_review_nature_outcomes(items: List[ReviewItemResult]) -> List[ReviewItemResult]:
    for item in items:
        nature = str((item.decision_trace or {}).get("review_nature") or "")
        if nature == "INTERNAL_CLASSIFICATION":
            _mark_internal_classification_item(
                item,
                item.reasoning_summary
                or f"系统已根据合同文本完成“{item.title}”的内部法律定性；该定性用于后续适用规则，不要求合同正文写入分类结论。",
            )
        if (item.decision_trace or {}).get("review_polarity") == "NEGATIVE_CLAUSE_CHECK" and item.coverage_status == "通过":
            item.status = "未发现明显风险条款"
            item.issue_type = "通过"
            item.risk_level = "低"
            item.risk_point_description = f"未发现“{item.title}”对应的不利或违法表述。"
            item.reasoning_summary = item.reasoning_summary or "正式合同条款和附件中未召回该类明显风险表述。"
            item.action_priority = ACTION_PRIORITY_NONE
            item.review_priority = ACTION_PRIORITY_NONE
            item.action_suggestion = "无需处理"
            item.risk_severity = SEVERITY_NONE
            item.residual_risk = "未发现不利条款，不形成对应风险。"
            item.related_risks = []
    return items


def _is_case_document_excerpt(text: str) -> bool:
    compacted = _compact(text)
    if "原告" in compacted and "被告" in compacted and ("租赁合同" in compacted or "房屋租赁合同" in compacted):
        return True
    hit_count = sum(1 for hint in CASE_DOCUMENT_HINTS if hint in compacted)
    return hit_count >= 2 and ("合同" in compacted or "租赁" in compacted)


def _apply_source_exemptions(item: ReviewItemResult, contract_text: str) -> ReviewItemResult:
    if item.item_id != "HL-002" or not _is_case_document_excerpt(contract_text):
        return item
    if item.coverage_status == "通过":
        item.risk_level = "低"
        return item

    item.risk_level = "低"
    item.status = "已覆盖"
    item.coverage_status = "通过"
    item.issue_type = "通过"
    item.risk_point_description = (
        "输入文本呈现为案件文书摘录，通常只会保留出租人、承租人的诉讼身份或角色摘要，"
        "不能按完整签约合同要求其载明证件号、住所和联系方式。正式合同原文仍建议补全主体身份信息。"
    )
    item.reasoning_summary = (
        "检测到文本具有案件文书摘录特征，本项按来源豁免处理：只要能够识别出租人与承租人的角色，"
        "不因摘录中缺少证件号、住所、联系方式而认定为条款缺陷。"
    )
    focused_evidence = [
        clause
        for clause in item.evidence_clauses
        if ("原告" in clause.get("text", "") and "被告" in clause.get("text", ""))
        or ("出租人" in clause.get("text", "") and "承租人" in clause.get("text", ""))
    ]
    if focused_evidence:
        item.evidence_clauses = focused_evidence[:1]
        item.evidence_location = item.evidence_clauses[0].get("location", "")
    item.fallback_reason = "案件文书摘录来源豁免"
    return item


def _apply_gift_consideration_override(item: ReviewItemResult, contract_text: str) -> ReviewItemResult:
    if item.item_id != "G-01-04" or item.coverage_status != "风险条款":
        return item
    if _has_gift_paid_consideration_risk(contract_text):
        return item

    item.risk_level = "低"
    item.status = "未发现明显风险条款"
    item.coverage_status = "通过"
    item.issue_type = "通过"
    item.risk_point_description = (
        "合同已明确无偿赠与，且未发现未被无偿声明排除的价款、收益、回购、还款或其他实质有偿对价安排。"
    )
    item.reasoning_summary = (
        "检测到合同已声明无偿赠与或无需支付对价，G-01-04 不再因“对价”等否定语境中的词语误判为风险条款。"
    )
    item.matched_terms = []
    item.evidence_clauses = []
    item.evidence_location = ""
    item.fallback_reason = "赠与无偿性专项校正"
    return item


_DEPENDENCY_BAD_COVERAGE = {"部分覆盖", "缺失", "风险条款"}
_DEPENDENCY_BAD_ISSUES = {"模板空白", "条款缺陷", "完全缺失", "风险条款"}
_GIFT_CHECKPOINT_DEPENDENCIES: Dict[str, Dict[str, str]] = {
    "G-09-03": {
        "depends_on": "G-09-01",
        "risk_level": "中",
        "mode": "partial",
        "reason": "不履行附义务的救济以受赠人义务内容为前提；前置义务内容未完整填写时，救济条款不能单独视为完整通过。",
    },
    "G-10-04": {
        "depends_on": "G-09-01",
        "risk_level": "中",
        "mode": "sync",
        "reason": "附义务赠与瑕疵担保范围以受赠人义务内容为计算和适用前提；前置义务内容缺失或空白时，本项应同步前置条款状态。",
    },
    "G-11-01": {
        "depends_on": "G-01-02",
        "risk_level": "中",
        "mode": "sync",
        "reason": "撤销后返还规则以赠与的无偿性基础为前提；无偿赠与意思表示未完整覆盖时，本项应同步前置条款状态。",
    },
}


def _dependency_is_incomplete(item: ReviewItemResult | None) -> bool:
    if not item:
        return False
    return item.coverage_status in _DEPENDENCY_BAD_COVERAGE or item.issue_type in _DEPENDENCY_BAD_ISSUES


def _dependency_status(dep: ReviewItemResult) -> str:
    if dep.coverage_status == "缺失":
        return "缺失或不明确"
    if dep.coverage_status == "风险条款":
        return "发现风险条款"
    return "部分覆盖，需先补全前置条款"


def _apply_gift_dependency_rules(items: List[ReviewItemResult]) -> List[ReviewItemResult]:
    by_id = {item.item_id: item for item in items}
    for item_id, rule in _GIFT_CHECKPOINT_DEPENDENCIES.items():
        item = by_id.get(item_id)
        dependency = by_id.get(rule["depends_on"])
        if not item or not _dependency_is_incomplete(dependency):
            continue

        assert dependency is not None
        item.risk_level = rule["risk_level"]
        if rule["mode"] == "sync":
            item.coverage_status = dependency.coverage_status
            item.issue_type = dependency.issue_type
            item.status = _dependency_status(dependency)
        else:
            item.coverage_status = "部分覆盖"
            item.issue_type = dependency.issue_type if dependency.issue_type == "模板空白" else "条款缺陷"
            item.status = "部分覆盖，需先补全前置条款"
        item.reasoning_summary = f"{rule['reason']} 当前前置审查点 {dependency.item_id}（{dependency.title}）状态为“{dependency.coverage_status}/{dependency.issue_type}”。"
        item.risk_point_description = f"该审查点依赖前置条款“{dependency.title}”。前置条款未完整覆盖时，本项不能单独认定为完整通过。"
        item.fallback_reason = "赠与合同跨条款依赖校正"
    return items


def _apply_development_improvement_applicability(
    items: List[ReviewItemResult],
    contract_text: str,
) -> List[ReviewItemResult]:
    """Gate development-contract improvement rules on actual continuing-right facts."""
    improvement_classification = classify_technology_transaction(contract_text)
    service_improvement_mode = (
        str(improvement_classification.get("primary_subtype") or "") == "TECHNICAL_SERVICE"
    )
    clauses = parse_contract_clauses(contract_text)
    improvement_terms = (
        "后续改进", "改进成果", "后续开发成果", "进一步开发", "进一步形成",
        "技术改进", "优化成果", "升级成果", "新算法", "新模型", "软件模块", "二次开发成果",
    )
    entitlement_terms = (
        "归属", "归甲方", "归乙方", "无偿归", "分享", "共享", "许可", "转让", "返授", "优先权", "优先许可", "优先购买", "收益", "共有", "共同成果",
    )
    entitlement_clauses = [
        clause for clause in clauses
        if any(term in _compact(clause.text) for term in improvement_terms)
        and any(term in _compact(clause.text) for term in entitlement_terms)
    ]
    notice_clauses = [
        clause for clause in clauses
        if any(term in _compact(clause.text) for term in improvement_terms)
        and any(term in _compact(clause.text) for term in ("通知", "告知", "披露", "提供资料"))
    ]

    restriction_patterns = (
        re.compile(r"(?:禁止|不得|无权).{0,12}(?:进行|从事|开展|继续|自行).{0,8}(?:研究开发|研发|后续改进|技术改进|二次开发)"),
        re.compile(r"(?:后续改进|改进成果).{0,30}(?:必须|应当|须).{0,12}(?:无偿共享|无偿许可|无偿转让|无偿提供)"),
        re.compile(r"(?:无偿共享|无偿许可|无偿转让|非互惠返授).{0,30}(?:后续改进|改进成果)"),
        re.compile(r"(?:进一步开发|进一步形成|技术改进|改进成果).{0,80}(?:知识产权).{0,20}(?:无偿归|无偿转归|免费归)"),
        re.compile(r"(?:独立形成|进一步形成).{0,100}(?:改进成果|专利申请权|知识产权).{0,25}(?:无偿归|无偿转归|免费归)"),
        re.compile(r"(?:禁止|不得).{0,25}(?:采购|购买|使用|推荐).{0,35}(?:替代技术|替代方案|解决方案|竞争技术)"),
        re.compile(r"(?:禁止|不得).{0,30}(?:竞争对手).{0,35}(?:相同|类似).{0,20}(?:服务|技术)"),
    )
    restriction_clauses = [
        clause for clause in clauses
        if any(pattern.search(_compact(clause.text)) for pattern in restriction_patterns)
        and not re.search(
            r"不得.{0,12}(?:非法|不合理)?限制.{0,12}(?:另一方|对方|任何一方).{0,18}"
            r"(?:研究开发|研发|技术改进|技术发展)",
            _compact(clause.text),
        )
    ]
    competition_clauses = [
        clause for clause in restriction_clauses
        if re.search(
            r"(?:禁止|不得).{0,35}(?:自行|独立)?(?:开发|研发|购买|采购|使用|推荐).{0,40}"
            r"(?:相同|类似|竞争|替代|竞争对手)",
            _compact(clause.text),
        )
        or re.search(
            r"(?:禁止|不得|无权).{0,18}(?:继续开展|继续|自行|独立)?.{0,8}"
            r"(?:研究开发|研发|后续改进|技术改进|二次开发)",
            _compact(clause.text),
        )
        or re.search(
            r"(?:限制|义务).{0,25}(?:合同)?(?:终止|解除|届满)后.{0,15}(?:继续|有效|[一二三四五六七八九十\d]+年)",
            _compact(clause.text),
        )
    ]
    has_follow_on_trigger = bool(entitlement_clauses or notice_clauses)
    by_id = {item.item_id: item for item in items}

    def mark_not_applicable(item: ReviewItemResult, reason: str, trigger: str) -> None:
        _set_item_not_applicable(item, reason)
        item.coverage_elements = []
        item.review_evidence_supports_element_ids = []
        item.coverage_presence = "NOT_APPLICABLE"
        item.risk_status = "NOT_APPLICABLE"
        item.recommended_action = "NONE"
        item.review_priority = ACTION_PRIORITY_NONE
        item.action_priority = ACTION_PRIORITY_NONE
        item.needs_manual_review = False
        item.quality_gate_failure_reason = ""
        item.review_status = "不适用"
        item.applicability = {
            "status": "NOT_APPLICABLE",
            "applicable": False,
            "conditional": True,
            "reason": reason,
            "depends_on": [trigger],
        }
        item.decision_trace["entrusted_improvement_applicability"] = {
            "status": "NOT_APPLICABLE",
            "trigger": trigger,
            "matched_clause_ids": [],
        }

    if not has_follow_on_trigger:
        reason = "当前技术开发合同未出现后续改进、返授、共享、许可、优先权或收益等持续权益事实。"
        for review_id in ("TC-10-01", "TC-10-02", "TC-10-03"):
            if item := by_id.get(review_id):
                mark_not_applicable(item, reason, "follow_on_improvement_entitlement")
    else:
        matched_ids = list(dict.fromkeys(
            clause.clause_id for clause in [*entitlement_clauses, *notice_clauses]
        ))
        for review_id in ("TC-10-01", "TC-10-02", "TC-10-03"):
            if item := by_id.get(review_id):
                item.applicability = {
                    "status": "APPLICABLE",
                    "applicable": True,
                    "conditional": True,
                    "reason": "合同出现后续改进及持续权益或通知安排，触发对应审查。",
                    "depends_on": ["follow_on_improvement_entitlement"],
                }
                item.decision_trace["entrusted_improvement_applicability"] = {
                    "status": "APPLICABLE",
                    "trigger": "follow_on_improvement_entitlement",
                    "matched_clause_ids": matched_ids,
                }

    assignment_clauses = [
        clause for clause in restriction_clauses
        if any(term in _compact(clause.text) for term in ("改进成果", "进一步开发", "独立形成"))
        and any(term in _compact(clause.text) for term in ("无偿归", "无偿转归", "免费归"))
    ]

    # The service-contract branch below intentionally separates downstream
    # activity restrictions from ownership/share mechanics.  Other technology
    # scenarios retain their established TC-10-04 evidence projection while the
    # shared TC-02/TC-10-01/02 fact handling below remains available to them.
    if not service_improvement_mode:
        boundary = by_id.get("TC-10-04")
        if boundary and not restriction_clauses:
            mark_not_applicable(
                boundary,
                "合同未出现禁止继续研发、强制无偿共享改进成果或非互惠返授等不利限制条款。",
                "affirmative_improvement_restriction",
            )
        elif boundary and restriction_clauses:
            evidence = [
                _specialized_evidence(clause, "UNREASONABLE_IMPROVEMENT_RESTRICTION", "DIRECT")
                for clause in restriction_clauses[:4]
            ]
            restriction_text = _compact(" ".join(clause.text for clause in restriction_clauses[:4]))
            boundary_facts: List[str] = []
            if re.search(r"(?:禁止|不得).{0,35}(?:自行|独立)?.{0,10}(?:开发|研发)", restriction_text):
                boundary_facts.append("限制继续或独立研发")
            if re.search(r"(?:禁止|不得).{0,35}(?:采购|购买|使用|推荐).{0,45}(?:替代|竞争|解决方案)", restriction_text):
                boundary_facts.append("限制合法采购或使用替代技术")
            if assignment_clauses:
                boundary_facts.append("强制将改进成果无偿转归另一方")
            _mark_technology_semantic_risk(
                boundary,
                title="改进限制边界",
                group="improvement_no_unlawful_restriction",
                description=(
                    "合同" + "；".join(boundary_facts) + "。"
                    if boundary_facts
                    else "合同存在禁止继续研发、强制无偿共享改进成果或非互惠返授等限制性安排。"
                ),
                consequence="不合理限制后续研究开发或强制处分改进成果，可能削弱开发方创新空间并引发条款效力争议。",
                recommendation="删除不合理研发限制；确需保护技术秘密或约定改进权益的，应限定对象、范围、期限、对价及互惠条件。",
                evidence=evidence,
                risk_level="中",
            )
            boundary.applicability = {
                "status": "APPLICABLE",
                "applicable": True,
                "reason": "合同存在明确的后续研发或改进成果限制条款。",
                "depends_on": ["affirmative_improvement_restriction"],
            }
            boundary.decision_trace["entrusted_improvement_applicability"] = {
                "status": "APPLICABLE",
                "trigger": "affirmative_improvement_restriction",
                "matched_clause_ids": [clause.clause_id for clause in restriction_clauses[:4]],
            }

    boundary = by_id.get("TC-10-04") if service_improvement_mode else None
    if boundary and not competition_clauses:
        mark_not_applicable(
            boundary,
            "合同未出现限制继续研发、独立改进、采购替代技术或使用竞争技术等后续技术活动的条款。",
            "affirmative_improvement_restriction",
        )
    elif boundary and competition_clauses:
        evidence = [
            _specialized_evidence(clause, "UNREASONABLE_IMPROVEMENT_RESTRICTION", "DIRECT")
            for clause in competition_clauses[:4]
        ]
        restriction_text = _compact(" ".join(clause.text for clause in competition_clauses[:4]))
        restriction_facts: List[str] = []
        if re.search(r"(?:禁止|不得|无权).{0,25}(?:继续|自行|独立).{0,15}(?:研究开发|开发|研发|后续改进|技术改进|二次开发)", restriction_text):
            restriction_facts.append("限制一方继续或独立开展后续研发")
        if re.search(r"(?:禁止|不得).{0,30}(?:采购|购买|使用|推荐).{0,35}(?:替代|竞争)", restriction_text):
            restriction_facts.append("限制合法采购或使用替代技术")
        if re.search(r"(?:终止后|合同终止后).{0,20}(?:继续有效|持续).{0,12}(?:\d+|[一二三四五六七八九十]+)年", restriction_text):
            restriction_facts.append("技术竞争限制在合同终止后仍长期持续")
        evidence_bound_description = (
            "合同" + "；".join(restriction_facts) + "。"
            if restriction_facts else "合同存在有直接条款证据支持的改进成果限制性安排。"
        )
        _mark_technology_semantic_risk(
            boundary,
            title="改进限制边界",
            group="improvement_no_unlawful_restriction",
            description=evidence_bound_description,
            consequence="对后续独立研发、改进或替代技术使用的限制过宽，可能妨碍技术发展并引发限制条款效力及可执行性争议。",
            recommendation="将后续技术活动限制收窄至保护项目成果和技术秘密所必需的对象、范围及合理期限，并保留合法独立研发和替代技术使用空间。",
            evidence=evidence,
            risk_level="中",
        )
        boundary.legal_basis_index = (
            "《中华人民共和国民法典》第850条、第875条；"
            "《最高人民法院关于审理技术合同纠纷案件适用法律若干问题的解释》第10条"
        )
        _set_multi_element_state(boundary, [
            {
                "element_id": "independent_research_restriction",
                "status": "ADVERSE" if any("研发" in fact for fact in restriction_facts) else "NOT_APPLICABLE",
                "presence_status": "COVERED" if any("研发" in fact for fact in restriction_facts) else "NOT_APPLICABLE",
                "risk_relevant": any("研发" in fact for fact in restriction_facts),
                "direction": "LEGALITY_RISK",
                "proposition": "合同限制一方继续或独立开展后续研发。",
                "evidence_terms": ["不得自行开发", "不得独立开发", "不得研发", "禁止研发"],
            },
            {
                "element_id": "alternative_technology_restriction",
                "status": "ADVERSE" if any("替代" in fact for fact in restriction_facts) else "NOT_APPLICABLE",
                "presence_status": "COVERED" if any("替代" in fact for fact in restriction_facts) else "NOT_APPLICABLE",
                "risk_relevant": any("替代" in fact for fact in restriction_facts),
                "direction": "LEGALITY_RISK",
                "proposition": "合同限制一方合法采购或使用替代技术。",
                "evidence_terms": ["不得采购", "不得购买", "不得使用", "替代技术", "替代方案"],
            },
            {
                "element_id": "post_termination_restriction_term",
                "status": "ADVERSE" if any("终止后" in fact for fact in restriction_facts) else "NOT_APPLICABLE",
                "presence_status": "COVERED" if any("终止后" in fact for fact in restriction_facts) else "NOT_APPLICABLE",
                "risk_relevant": any("终止后" in fact for fact in restriction_facts),
                "direction": "LEGALITY_RISK",
                "proposition": "技术竞争限制在合同终止后仍长期持续。",
                "evidence_terms": ["终止后", "继续有效"],
            },
        ], evidence)
        boundary.applicability = {
            "status": "APPLICABLE",
            "applicable": True,
            "reason": "合同存在明确的后续研发或改进成果限制条款。",
            "depends_on": ["affirmative_improvement_restriction"],
        }
        boundary.decision_trace["entrusted_improvement_applicability"] = {
            "status": "APPLICABLE",
            "trigger": "affirmative_improvement_restriction",
            "matched_clause_ids": [clause.clause_id for clause in competition_clauses[:4]],
        }

    shared_clauses: List[Any] = []
    seen_shared_clause_ids: set[str] = set()
    for shared_clause in [*competition_clauses, *assignment_clauses]:
        shared_clause_id = str(shared_clause.clause_id)
        if shared_clause_id in seen_shared_clause_ids:
            continue
        seen_shared_clause_ids.add(shared_clause_id)
        shared_clauses.append(shared_clause)
    if shared_clauses:
        competition_rule_clauses = competition_clauses or assignment_clauses
        competition_evidence = [
            _specialized_evidence(clause, "SHARED_TECHNOLOGY_RESTRICTION", "DIRECT")
            for clause in competition_rule_clauses[:6]
        ]
        competition_text = _compact(" ".join(clause.text for clause in competition_clauses))
        facts: List[str] = []
        if re.search(r"不得.{0,18}自行开发.{0,25}(?:相同|类似)", competition_text):
            facts.append("限制自行开发相同或类似技术方案")
        if re.search(r"不得.{0,30}(?:采购|购买|使用|推荐).{0,35}(?:替代|竞争)", competition_text):
            facts.append("限制合法采购或使用替代技术")
        if re.search(r"(?:终止后|合同终止后).{0,20}继续有效.{0,12}(?:\d+|[一二三四五六七八九十]+)年", competition_text):
            facts.append("技术竞争限制在合同终止后长期持续")
        # A compulsory free transfer is itself a competition/development risk
        # when it is the only restriction.  Where direct R&D/procurement
        # restrictions also exist, keep TC-02-01 focused on those clauses and
        # leave ownership/assignment evidence to the TC-10 rules.
        if assignment_clauses and not competition_clauses:
            facts.append("强制一方将自行形成的改进成果无偿转归另一方")
        if facts and (competition_item := by_id.get("TC-02-01")):
            _mark_technology_semantic_risk(
                competition_item,
                title="非法限制技术竞争和发展",
                group="illegal_monopoly_technology",
                description="合同" + "；".join(facts) + "。",
                consequence="过度限制持续研发、合法获取替代技术或强制无偿处分改进成果，可能产生限制技术竞争、技术发展及相关条款效力风险。",
                recommendation="将限制缩减至保护合同成果和技术秘密所必需的范围及合理期限；独立改进成果原则上归改进方。",
                evidence=competition_evidence,
                risk_level="高",
            )
            competition_item.legal_basis_index = (
                "《中华人民共和国民法典》第850条；"
                "《最高人民法院关于审理技术合同纠纷案件适用法律若干问题的解释》第10条"
            )
            competition_item.legal_consequence_if_missing = (
                "该约定高度符合司法解释列举的非法垄断技术情形，"
                "可能构成对技术竞争和技术发展的不当限制，相关限制条款存在被认定无效或难以执行的较高风险；"
                "具体效力仍应结合限制对象、范围、期限和合同目的判断。"
            )
            competition_elements: List[Dict[str, Any]] = []
            for element_id, proposition, terms, present in (
                (
                    "independent_research_restriction",
                    "合同限制一方自行开发相同或类似技术方案。",
                    ["不得自行开发", "不得独立开发", "相同或类似"],
                    any("自行开发" in fact for fact in facts),
                ),
                (
                    "alternative_technology_restriction",
                    "合同限制一方合法采购或使用替代技术。",
                    ["不得采购", "不得购买", "不得使用", "采购或者使用", "可以替代", "替代技术", "替代方案", "解决方案"],
                    any("替代技术" in fact for fact in facts),
                ),
                (
                    "post_termination_competition_term",
                    "技术竞争限制在合同终止后长期持续。",
                    ["终止后", "继续有效"],
                    any("终止后" in fact for fact in facts),
                ),
                (
                    "compulsory_free_improvement_assignment",
                    "一方自行形成的改进成果被要求无偿转归另一方。",
                    ["改进", "无偿归"],
                    any("无偿转归" in fact for fact in facts),
                ),
            ):
                if not present:
                    continue
                competition_elements.append({
                    "element_id": element_id,
                    "status": "ADVERSE",
                    "presence_status": "COVERED",
                    "direction": "LEGALITY_RISK",
                    "risk_relevant": True,
                    "proposition": proposition,
                    "evidence_terms": terms,
                })
            _set_multi_element_state(competition_item, competition_elements, competition_evidence)
            competition_item.decision_trace["shared_technology_restriction_facts"] = facts
        if assignment_clauses:
            assignment_evidence = [
                _specialized_evidence(clause, "COMPULSORY_FREE_IMPROVEMENT_ASSIGNMENT", "DIRECT")
                for clause in assignment_clauses[:4]
            ]
            assignment_evidence_ids = [
                str(row.get("evidence_id") or row.get("clause_id") or "")
                for row in assignment_evidence
                if row.get("evidence_id") or row.get("clause_id")
            ]
            if improvement_item := by_id.get("TC-10-01"):
                _mark_technology_semantic_risk(
                    improvement_item,
                    title="后续改进成果所有权被强制无偿转归",
                    group="improvement_no_unlawful_restriction",
                    description="合同已明确后续改进成果归属，但要求一方将其自行形成的算法、模型、软件模块及其他改进成果所有权无偿转归另一方。",
                    consequence="该所有权安排会改变改进成果的权利申请、处分和商业化收益归属，并可能因单向无偿转归而引发效力与执行争议。",
                    recommendation="区分项目依赖型改进与一方独立成果，分别明确所有权、申请权、处分权和合理对价；避免以无限范围的无偿转归替代可执行的项目保护。",
                    evidence=assignment_evidence,
                    risk_level="高",
                )
                improvement_item.legal_basis_index = (
                    "《中华人民共和国民法典》第850条、第875条；"
                    "《最高人民法院关于审理技术合同纠纷案件适用法律若干问题的解释》第10条"
                )
                improvement_item.legal_consequence_if_missing = (
                    "单向强制无偿取得一方独立形成的改进成果，高度符合司法解释列举的非法垄断技术情形，"
                    "可能构成对技术发展的不当限制，相关权利转归条款存在效力及可执行性风险；"
                    "但不因此机械认定整份合同必然无效。"
                )
                _set_multi_element_state(improvement_item, [
                    {"element_id": "improvement_ownership_arrangement", "status": "COVERED", "presence_status": "COVERED", "risk_relevant": False, "proposition": "后续改进成果的所有权及申请权已有明文安排。", "bound_evidence_ids": assignment_evidence_ids},
                    {"element_id": "compulsory_free_improvement_assignment", "status": "ADVERSE", "presence_status": "COVERED", "direction": "LEGALITY_RISK", "risk_relevant": True, "proposition": "一方自行形成的改进成果所有权被要求无偿转归另一方。", "bound_evidence_ids": assignment_evidence_ids},
                ], assignment_evidence)
                improvement_item.applicability = {"status": "APPLICABLE", "applicable": True, "reason": "合同出现改进成果及无偿权利转移安排。", "depends_on": ["follow_on_improvement_entitlement"]}
            if improvement_item := by_id.get("TC-10-02"):
                _mark_technology_semantic_risk(
                    improvement_item,
                    title="改进成果分享及许可机制不完整",
                    group="improvement_no_unlawful_restriction",
                    description="合同以改进成果所有权无偿转归替代了双方对改进成果使用、返授许可、商业利用、分许可、期限和对价的具体安排。",
                    consequence="分享许可边界未独立约定时，双方对项目内使用、商业化、向关联方或第三方授权及终止后继续使用的权限可能发生争议。",
                    recommendation="在不改变必要项目控制的前提下，分别明确改进成果使用范围、返授许可、许可期限、商业用途、分许可条件及合理对价。",
                    evidence=assignment_evidence,
                    risk_level="高",
                )
                sharing_elements = [
                    {"element_id": "sharing_arrangement_exists", "status": "PARTIALLY_COVERED", "presence_status": "COVERED", "risk_relevant": True, "proposition": "合同通过所有权转归处理改进成果权益，但未独立形成完整的分享许可机制。", "bound_evidence_ids": assignment_evidence_ids},
                    {"element_id": "improvement_use_scope", "status": "MISSING", "risk_relevant": True, "proposition": "改进成果的使用范围尚未独立明确。", "required_fact": "明确改进成果的使用范围"},
                    {"element_id": "improvement_license_term", "status": "MISSING", "risk_relevant": True, "proposition": "改进成果许可期限尚未独立明确。", "required_fact": "明确改进成果许可期限"},
                    {"element_id": "improvement_commercial_and_sublicense", "status": "MISSING", "risk_relevant": True, "proposition": "改进成果商业用途及分许可条件尚未独立明确。", "required_fact": "明确改进成果商业用途及分许可条件"},
                    {"element_id": "improvement_license_consideration", "status": "ADVERSE", "presence_status": "COVERED", "direction": "LEGALITY_RISK", "risk_relevant": True, "proposition": "改进成果权益被无偿取得，未形成独立合理对价。", "bound_evidence_ids": assignment_evidence_ids},
                ]
                if not service_improvement_mode:
                    sharing_elements.append({
                        "element_id": "compulsory_free_improvement_assignment",
                        "status": "ADVERSE",
                        "presence_status": "COVERED",
                        "direction": "LEGALITY_RISK",
                        "risk_relevant": True,
                        "proposition": "一方自行形成的改进成果被要求无偿转归另一方。",
                        "bound_evidence_ids": assignment_evidence_ids,
                    })
                _set_multi_element_state(improvement_item, sharing_elements, assignment_evidence)
                improvement_item.applicability = {"status": "APPLICABLE", "applicable": True, "reason": "合同出现改进成果权益安排，需进一步审查分享和许可机制。", "depends_on": ["follow_on_improvement_entitlement"]}
    return items


def _apply_technology_license_subtransaction_rules(
    items: List[ReviewItemResult], contract_text: str, classification: Dict[str, Any],
) -> List[ReviewItemResult]:
    """Activate fact-proven ancillary modules without changing the main transaction."""
    primary_subtype = str(classification.get("primary_subtype") or "")
    if primary_subtype not in {"TECHNOLOGY_LICENSE", "TECHNOLOGY_TRANSFER"}:
        return items
    main_transaction = "technology_license" if primary_subtype == "TECHNOLOGY_LICENSE" else "technology_transfer"
    main_transaction_label = "技术许可" if primary_subtype == "TECHNOLOGY_LICENSE" else "技术转让"
    sub_transactions = set(classification.get("sub_transactions") or [])
    structured = dict(classification.get("structured_facts") or {})
    clauses = _operative_technology_clauses(contract_text)
    by_id = {item.item_id: item for item in items}

    def activate(item: ReviewItemResult, module: str, evidence: List[Dict[str, Any]]) -> None:
        item.applicability = {
            "status": "APPLICABLE", "applicable": True,
            "reason": f"主交易为{main_transaction_label}，但合同存在可核验的{module}附属履行事实。",
            "depends_on": [f"technology_classification.sub_transactions.{module}"],
            "trigger_evidence_ids": [str(row.get("clause_id") or row.get("evidence_id") or "") for row in evidence],
        }
        item.decision_trace["subtransaction_activation"] = {
            "main_transaction": main_transaction, "sub_transaction": module, "fact_driven": True,
        }
        if item.item_id.startswith("TC-09-"):
            item.applicable_if = "适用于技术服务合同，或其他合同中实际包含独立技术服务义务的场景。"

    if "technical_service" in sub_transactions:
        service_evidence = _direct_technology_evidence(clauses, (
            ("技术服务和技术指导", "技术服务内容", "技术服务与培训", "技术服务：需要"),
            ("实施说明", "部署指导", "参数配置培训", "故障排查指导", "部署支持", "现场技术指导"),
            ("远程视频会议", "电子邮件", "现场技术培训"),
            ("技术服务和指导内容", "系统部署", "参数调试", "模型训练", "生产环境调试", "技术人员培训", "技术培训", "远程技术支持"),
        ), 8)
        support_item = by_id.get("TC-07-04")
        if primary_subtype == "TECHNOLOGY_LICENSE" and support_item and service_evidence:
            _set_specialized_requirement_state(
                support_item, "PRESENT", service_evidence, "licensor_support_obligation",
                "许可方应明确提供与专利实施有关的技术服务、技术指导、部署调试、培训或持续支持。",
                "合同已明确许可方提供系统部署、模型训练、生产环境调试、人员培训及远程技术支持。", "低",
            )
            _set_multi_element_state(support_item, [{
                "element_id": "licensor_technical_support",
                "status": "COVERED",
                "proposition": "许可方技术服务、技术指导、部署调试、培训及远程支持义务已有明确安排。",
                "evidence_terms": ["技术服务和指导", "系统部署", "模型训练", "生产环境调试", "技术人员培训", "远程技术支持"],
            }], service_evidence)
            activate(support_item, "technical_service", service_evidence)
            support_item.fallback_reason = "技术许可附属技术服务对许可方协助义务的事实复用"
        item = by_id.get("TC-09-01")
        if item and service_evidence:
            frequency = bool(re.search(r"(?:不少于|不超过)?\s*\d+\s*次", contract_text))
            _set_specialized_requirement_state(
                item, "PRESENT", service_evidence, "ancillary_technical_service_content",
                "主交易中的独立技术服务内容、方式和频次应按附属交易事实审查。",
                "合同已明确与主交易相关的技术服务、技术指导、培训或部署支持。", "低",
            )
            _set_multi_element_state(item, [
                {"element_id": "service_content", "status": "COVERED", "proposition": "技术服务和技术指导内容明确。", "evidence_terms": ["技术服务", "技术指导", "实施说明", "部署指导"]},
                {"element_id": "service_method", "status": "COVERED", "proposition": "远程、邮件或现场服务方式明确。", "evidence_terms": ["远程", "电子邮件", "现场"]},
                {"element_id": "service_frequency", "status": "COVERED" if frequency else "PARTIALLY_COVERED", "proposition": "服务频次或最低培训次数已有约定。", "evidence_terms": ["次", "小时"]},
            ], service_evidence)
            activate(item, "technical_service", service_evidence)
            item.fallback_reason = "技术许可附属技术服务事实路由"

        acceptance_evidence = _direct_technology_evidence(clauses, (
            ("验收", "验收标准", "按照以下标准验收"), ("准确率", "稳定运行", "测试数据集"),
            ("首次验收不合格", "整改", "重新验收", "解除合同"),
            ("补救期限", "再次验收次数", "第二次仍不合格", "返还已支付转让费", "赔偿损失"),
        ), 8)
        acceptance_evidence = [
            row for row in acceptance_evidence
            if any(term in _compact(str(row.get("text") or row.get("quote") or "")) for term in (
                "验收", "整改", "重新验收", "再次验收", "复验",
            ))
        ]
        item = by_id.get("TC-09-02")
        if item and acceptance_evidence:
            acceptance_facts = dict(structured.get("acceptance") or {})
            objective = any(term in _compact(contract_text) for term in (
                "准确率", "稳定运行", "测试数据集", "严重故障", "验收标准", "按照以下标准验收",
                "能够在甲方测试环境运行", "能够输出", "完成两次培训", "完成首次生产环境部署",
            ))
            remedy_deadline = bool(acceptance_facts.get("remedy_deadline"))
            reinspection_procedure = bool(acceptance_facts.get("reinspection_procedure"))
            reinspection_count = bool(acceptance_facts.get("reinspection_count"))
            final_failure_remedy = bool(acceptance_facts.get("final_failure_remedy"))
            refund_remedy = bool(acceptance_facts.get("refund_remedy"))
            damage_remedy = bool(acceptance_facts.get("damage_remedy"))
            legacy_rectification = all(term in _compact(contract_text) for term in ("整改", "重新验收"))
            if primary_subtype == "TECHNOLOGY_TRANSFER":
                acceptance_remedies_covered = all((
                    remedy_deadline,
                    reinspection_procedure,
                    reinspection_count,
                    final_failure_remedy,
                    refund_remedy,
                    damage_remedy,
                ))
                acceptance_elements = [
                    {"element_id": "remedy_deadline", "status": "COVERED" if remedy_deadline else "MISSING", "proposition": "验收不合格后的补救期限明确。", "evidence_terms": ["补救期限", "整改期限"]},
                    {"element_id": "reinspection_procedure", "status": "COVERED" if reinspection_procedure else "MISSING", "proposition": "再次验收程序明确。", "evidence_terms": ["再次验收", "重新验收"]},
                    {"element_id": "reinspection_count", "status": "COVERED" if reinspection_count else "MISSING", "proposition": "再次验收次数明确。", "evidence_terms": ["再次验收次数"]},
                    {"element_id": "final_failure_remedy", "status": "COVERED" if final_failure_remedy else "MISSING", "proposition": "最终仍不合格时的解除等处理机制明确。", "evidence_terms": ["第二次仍不合格", "解除合同"]},
                    {"element_id": "refund_remedy", "status": "COVERED" if refund_remedy else "MISSING", "proposition": "最终验收失败后的退款救济明确。", "evidence_terms": ["返还已支付转让费", "退款"]},
                    {"element_id": "damage_remedy", "status": "COVERED" if damage_remedy else "MISSING", "proposition": "最终验收失败后的损失赔偿救济明确。", "evidence_terms": ["赔偿损失"]},
                ]
            else:
                # Keep the established licence checklist boundary unchanged.
                acceptance_remedies_covered = legacy_rectification
                acceptance_elements = [{
                    "element_id": "rectification_and_retest",
                    "status": "COVERED" if legacy_rectification else "MISSING",
                    "proposition": "验收不合格后的整改及再次验收机制已有明确约定。" if legacy_rectification else "验收不合格后的整改及再次验收机制",
                    "evidence_terms": ["整改", "重新验收"],
                }]
            _set_specialized_requirement_state(
                item, "PRESENT" if objective and acceptance_remedies_covered else "PARTIAL", acceptance_evidence,
                "ancillary_service_quality_acceptance", "附属技术服务应有可核验的质量指标、验收程序和整改机制。",
                "合同已设置客观验收标准、补救期限、再次验收程序和次数，以及最终不合格时的解除、退款与损失赔偿救济。", "低",
            )
            _set_multi_element_state(item, [
                {
                    "element_id": "objective_acceptance_standard",
                    "status": "COVERED" if objective else "PARTIALLY_COVERED",
                    "proposition": "客观验收指标明确。" if objective else "合同已设置验收安排，但客观质量指标仍不完整。",
                    "evidence_terms": ["准确率", "稳定运行", "严重故障", "验收", "测试"],
                },
                *acceptance_elements,
            ], acceptance_evidence)
            acceptance_text = _compact(" ".join(
                str(row.get("text") or row.get("quote") or "") for row in acceptance_evidence
            ))
            unilateral_test_control = bool(re.search(
                r"(?:测试环境|测试数据|性能指标|验收标准|测试方法)"
                r".{0,80}由(?:许可方|卖方|服务方)(?:单方)?(?:确定|决定|制定)|"
                r"(?:许可方|卖方|服务方)(?:有权|可以)(?:单方)?(?:确定|决定|制定|调整|修改)"
                r".{0,50}(?:测试条件|测试环境|测试数据|性能指标|验收标准|测试方法)",
                acceptance_text,
            ))
            deemed_acceptance = bool(re.search(
                r"(?:未提出|逾期未提出).{0,30}(?:书面)?异议.{0,30}视为.{0,8}(?:验收合格|通过)|"
                r"未在.{0,20}内.{0,20}提出.{0,20}异议.{0,20}视为.{0,8}(?:验收合格|通过)",
                acceptance_text,
            ))
            if unilateral_test_control:
                _mark_technology_semantic_risk(
                    item,
                    title="验收标准和测试条件由许可方单方控制",
                    group="unilateral_acceptance_control",
                    description=(
                        "合同已设置验收流程，但测试环境、测试数据、性能指标或测试方法由许可方单方确定或调整，"
                        "缺少被许可方事先确认和争议复测机制。"
                    ),
                    consequence="许可方可以通过单方控制测试条件影响验收结论，增加交付、整改和付款争议。",
                    recommendation=(
                        "建议将测试环境、测试数据、性能指标和测试方法作为双方事先书面确认的验收方案；"
                        "任何调整应经双方一致同意，并设置结果争议时的复测程序。"
                    ),
                    evidence=acceptance_evidence,
                    risk_level="中",
                )
                existing_acceptance_elements = [
                    {
                        "element_id": str(row.get("element_id") or ""),
                        "status": str(row.get("status") or "MISSING"),
                        "proposition": str(row.get("proposition") or ""),
                        "bound_evidence_ids": list(row.get("evidence_ids") or []),
                    }
                    for row in item.coverage_elements
                    if row.get("element_id") and row.get("proposition")
                ]
                _set_multi_element_state(item, [*existing_acceptance_elements,
                    {
                        "element_id": "unilateral_acceptance_standard_control",
                        "status": "ADVERSE", "direction": "ADVERSE",
                        "proposition": "验收标准或测试条件由许可方单方确定或调整。",
                        "evidence_terms": ["由卖方确定", "由许可方确定", "调整测试条件", "调整验收方法"],
                    },
                    {
                        "element_id": "deemed_acceptance",
                        "status": "COVERED" if deemed_acceptance else "MISSING",
                        "direction": "ADVERSE" if deemed_acceptance else None,
                        "proposition": "逾期未提书面异议即视为验收通过。",
                        "evidence_terms": ["未在5个工作日内提出书面异议", "视为全部验收合格"],
                    },
                    {
                        "element_id": "joint_test_plan_confirmation",
                        "status": "MISSING",
                        "proposition": "测试和验收方案由双方事先书面确认。",
                    },
                ], acceptance_evidence)
            if not acceptance_remedies_covered and not unilateral_test_control:
                item.suggested_clause_example = (
                    "建议明确验收不合格后的整改期限、再次验收程序、验收次数及最终仍不合格时的处理机制。"
                )
                item.action_suggestion = item.suggested_clause_example
            activate(item, "acceptance", acceptance_evidence)
            item.fallback_reason = "技术许可附属验收事实路由"

            test_attachment_item = by_id.get("TC-13-03")
            if test_attachment_item:
                test_attachment_evidence = list(acceptance_evidence)
                seen_test_ids = {
                    str(row.get("clause_id") or row.get("evidence_id") or "")
                    for row in test_attachment_evidence
                }
                attachment_source_clauses = [
                    clause for clause in parse_contract_clauses(contract_text)
                    if clause.section_type in {"正式合同条款", "附件"}
                ]
                for row in _direct_technology_evidence(
                    attachment_source_clauses,
                    (("项目测试与验收方案", "测试与验收方案", "测试方案"),),
                    4,
                ):
                    identity = str(row.get("clause_id") or row.get("evidence_id") or "")
                    if identity and identity not in seen_test_ids:
                        seen_test_ids.add(identity)
                        test_attachment_evidence.append(row)
                test_text = _compact(" ".join(
                    str(row.get("text") or row.get("quote") or "") for row in test_attachment_evidence
                ))
                attachment_arranged = any(term in _compact(contract_text) for term in (
                    "项目测试与验收方案", "测试与验收方案", "测试方案附件",
                ))
                test_record = any(term in test_text for term in ("测试记录", "测试报告", "验收记录"))
                retest = any(term in test_text for term in ("复测", "重新测试", "第三方检测"))
                _set_specialized_requirement_state(
                    test_attachment_item, "PARTIAL", test_attachment_evidence,
                    "ancillary_acceptance_test_attachment",
                    "合同实际包含测试验收时，应以附件或双方确认文件固化测试条件、记录和复测机制。",
                    "合同已安排测试验收场景和相关方案附件，但具体测试记录、双方确认及争议复测机制仍不完整。",
                    "低",
                )
                _set_multi_element_state(test_attachment_item, [
                    {"element_id": "acceptance_test_scene", "status": "COVERED", "proposition": "合同存在实际测试和验收场景。", "evidence_terms": ["验收", "测试环境", "测试数据"]},
                    {"element_id": "test_plan_attachment_arrangement", "status": "COVERED" if attachment_arranged else "MISSING", "proposition": "项目测试与验收方案的附件安排。", "evidence_terms": ["项目测试与验收方案", "测试与验收方案", "测试方案"]},
                    {"element_id": "test_record_requirement", "status": "COVERED" if test_record else "MISSING", "proposition": "测试记录、测试报告及最终验收确认文件。", "evidence_terms": ["测试记录", "测试报告", "验收记录"]},
                    {"element_id": "retest_mechanism", "status": "COVERED" if retest else "MISSING", "proposition": "测试结果争议时的复测机制。", "evidence_terms": ["复测", "重新测试", "第三方检测"]},
                ], test_attachment_evidence)
                test_attachment_item.suggested_clause_example = (
                    "建议以双方书面确认的验收附件固化测试环境、数据、指标和方法，"
                    "并明确测试记录、最终验收确认文件及结果争议时的复测程序。"
                )
                test_attachment_item.action_suggestion = test_attachment_item.suggested_clause_example
                activate(test_attachment_item, "acceptance", test_attachment_evidence)
                test_attachment_item.fallback_reason = "技术许可附属验收测试事实路由"

        service_result_evidence = [
            row for row in _direct_technology_evidence(clauses, (
                ("技术服务过程中", "技术指导过程中", "因技术服务形成", "服务成果"),
                ("形成", "产生", "交付", "归属", "归甲方", "归乙方", "使用权"),
                ("调试报告", "培训材料", "实施方案", "服务报告", "独立成果"),
            ), 8)
            if (
                any(term in _compact(str(row.get("text") or row.get("quote") or "")) for term in (
                    "技术服务过程中", "技术指导过程中", "因技术服务形成", "服务成果",
                ))
                and any(term in _compact(str(row.get("text") or row.get("quote") or "")) for term in (
                    "形成", "产生", "交付", "归属", "归甲方", "归乙方", "使用权",
                ))
            )
        ]
        item = by_id.get("TC-09-03")
        if item and service_result_evidence:
            service_result_text = _compact(" ".join(
                str(row.get("text") or row.get("quote") or "") for row in service_result_evidence
            ))
            ownership_covered = any(term in service_result_text for term in (
                "归甲方", "归乙方", "归双方", "归属", "享有所有权", "享有知识产权",
            ))
            use_boundary_covered = any(term in service_result_text for term in (
                "使用权", "许可使用", "商业使用", "不得使用", "可使用",
            ))
            _set_specialized_requirement_state(
                item, "PARTIAL" if ownership_covered else "MISSING", service_result_evidence,
                "ancillary_service_new_result_ownership",
                "技术服务本身形成独立成果时，应明确该服务成果的归属、交付和使用边界。",
                "合同显示技术服务本身可能形成独立成果；其归属或使用边界已有部分安排。", "低",
            )
            _set_multi_element_state(item, [
                {"element_id": "service_generated_result_ownership", "status": "COVERED" if ownership_covered else "MISSING", "proposition": "技术服务本身形成的独立成果归属", "evidence_terms": ["归甲方", "归乙方", "归双方", "归属", "所有权", "知识产权"]},
                {"element_id": "service_generated_result_use_boundary", "status": "COVERED" if use_boundary_covered else "MISSING", "proposition": "技术服务本身形成的独立成果使用和许可边界", "evidence_terms": ["使用权", "许可使用", "商业使用", "不得使用", "可使用"]},
            ], service_result_evidence)
            item.risk_point_description = "技术服务本身形成的独立成果已有事实触发，但其归属、交付或使用边界仍需完整约定。"
            item.legal_consequence_if_missing = "独立服务成果的归属或使用边界不清时，可能产生交付、复用和商业化争议。"
            item.suggested_clause_example = "建议明确技术服务本身形成的调试报告、实施方案、培训材料等独立成果的交付范围、知识产权归属及双方后续使用权限。"
            item.action_suggestion = item.suggested_clause_example
            activate(item, "technical_service", service_result_evidence)
            item.fallback_reason = "技术许可附属服务独立成果事实路由"
        elif item:
            _set_item_not_applicable(
                item,
                "合同虽含技术服务，但未发现技术服务本身形成独立成果的事实；后续专利或许可技术改进成果由TC-10规则单独审查。",
            )
            item.coverage_elements = []
            item.suggested_clause_example = ""
            item.legal_consequence_if_missing = ""
            item.related_risks = []
            item.decision_trace["service_generated_result_applicability"] = {
                "status": "NOT_APPLICABLE",
                "reason": "NO_SERVICE_GENERATED_INDEPENDENT_RESULT_FACT",
                "improvement_result_reused": False,
            }

        fee_evidence = _direct_technology_evidence(clauses, (
            ("技术服务和指导费", "技术服务费", "技术服务和培训费用", "技术服务与培训费用"),
            ("已包含在转让费中", "已包含在许可费中", "不另行收费"),
            ("现场技术服务", "另行协商收费", "超过"),
            ("分期支付", "第一期", "第二期", "第三期"),
        ), 8)
        item = by_id.get("TC-09-04")
        if item and fee_evidence:
            service_fee_facts = dict(structured.get("technical_service") or {})
            fee_defined = bool(service_fee_facts.get("separate_fee"))
            fee_included = bool(
                service_fee_facts.get("included_in_main_price")
                or service_fee_facts.get("included_service_scope")
            )
            extra_charge = bool(service_fee_facts.get("extra_service_charge_trigger"))
            extra_pricing = bool(service_fee_facts.get("extra_service_pricing_standard"))
            extra_billing = bool(service_fee_facts.get("extra_service_billing_method"))
            extra_payment = bool(service_fee_facts.get("extra_service_payment_node"))
            schedule = any(term in _compact(contract_text) for term in ("分期支付", "第一期", "第二期", "第三期"))
            extra_gaps = []
            if extra_charge and not extra_pricing:
                extra_gaps.append("超出约定工作量后的额外技术服务收费标准")
            if extra_charge and not extra_billing:
                extra_gaps.append("额外技术服务的计价和工作量确认方式")
            if extra_charge and not extra_payment:
                extra_gaps.append("额外技术服务费的支付节点")
            base_fee_covered = fee_defined or fee_included
            coverage = (
                "PRESENT"
                if base_fee_covered and (not extra_charge or not extra_gaps)
                else "PARTIAL"
                if base_fee_covered or fee_defined
                else "MISSING"
            )
            _set_specialized_requirement_state(
                item, coverage, fee_evidence,
                "ancillary_service_payment", "附属技术服务的费用应明确单独计价或已包含在主交易价款中。",
                (
                    "约定工作量范围内的技术服务费用已纳入主交易付款安排；"
                    f"仍需完善：{'；'.join(extra_gaps)}。"
                    if extra_gaps
                    else "技术服务费用及付款安排已有明确约定。"
                ), "低",
            )
            service_fee_elements = [
                {
                    "element_id": "service_fee_amount",
                    "status": "COVERED" if base_fee_covered else "MISSING",
                    "proposition": "约定工作量范围内的技术服务费用已有明确安排。",
                    "evidence_terms": ["技术服务", "现场技术服务", "不超过", "包含在转让费中", "包含在许可费中", "另行协商收费"],
                },
                {
                    "element_id": "service_payment_schedule",
                    "status": "COVERED" if schedule or fee_included else "PARTIALLY_COVERED",
                    "proposition": "技术服务费用纳入合同统一付款安排。" if schedule or fee_included else "技术服务费用的支付安排仍不完整。",
                    "evidence_terms": ["分期支付", "第一期", "第二期", "第三期", "技术服务", "指导费"],
                },
            ]
            if extra_charge:
                service_fee_elements.extend([
                    {
                        "element_id": "extra_service_pricing_standard",
                        "status": "COVERED" if extra_pricing else "MISSING",
                        "proposition": "超出约定工作量后的额外技术服务收费标准。",
                        "evidence_terms": ["每人日", "每小时", "每次", "单价", "费率", "计价标准"],
                    },
                    {
                        "element_id": "extra_service_billing_method",
                        "status": "COVERED" if extra_billing else "MISSING",
                        "proposition": "额外技术服务的计价和工作量确认方式。",
                        "evidence_terms": ["工时确认单", "服务记录", "工作量确认", "按实际工时", "按人日", "按小时"],
                    },
                    {
                        "element_id": "extra_service_payment_node",
                        "status": "COVERED" if extra_payment else "MISSING",
                        "proposition": "额外技术服务费的支付节点。",
                        "evidence_terms": ["额外服务费", "超出服务费", "支付", "结算"],
                    },
                ])
            _set_multi_element_state(item, service_fee_elements, fee_evidence)
            _reconcile_specialized_coverage_from_elements(item)
            if extra_gaps:
                item.suggested_clause_example = (
                    "建议仅针对超出约定工作量的额外技术服务，明确收费标准、计价及工作量确认方式和支付节点；"
                    "约定工作量范围内的技术服务费用继续按现有统一付款安排执行。"
                )
                item.action_suggestion = item.suggested_clause_example
            activate(item, "technical_service", fee_evidence)
            item.fallback_reason = "技术许可附属技术服务费用事实路由"

    if "technical_secret" in sub_transactions:
        item = by_id.get("TC-12-03")
        secret_evidence = _direct_technology_evidence(clauses, (
            ("技术秘密内容", "技术秘密"), ("仅可为实施", "不得向", "保密期限"),
            ("技术秘密使用费", "技术秘密许可使用费", "进入公共领域", "依法已经公开"),
            ("第三方公开", "行业发展", "进入公共领域", "申请专利导致"),
            ("继续支付", "停止支付", "不予退还", "不得", "解除合同"),
        ), 8)
        if item and secret_evidence:
            secret = dict(structured.get("technical_secret") or {})
            loss = analyze_technical_secret_loss_arrangement(contract_text)
            secret_is_main_subject = classification.get("tertiary_subtype") == "TECHNICAL_SECRET_LICENSE"
            if loss.get("adverse"):
                _mark_technology_semantic_risk(
                    item,
                    title="技术秘密丧失秘密性后仍须持续付款且限制解除",
                    group="technical_secret_loss_fee_adverse",
                    description=(
                        "合同已约定技术秘密全部或部分被第三方公开、进入公共领域或因许可方申请专利而公开后的处理，"
                        "但仍要求被许可方继续支付未来许可费、技术服务费或提成，已付款不退且原则上不得解除合同。"
                    ),
                    consequence=(
                        "非因被许可方原因丧失秘密性时，被许可方可能在不再取得相应秘密性利益的情况下继续承担未来对价，"
                        "且缺少调减、停止、解除和分项结算机制。"
                    ),
                    recommendation=(
                        "建议区分全部公开、部分公开、第三方合法公开及许可方主动申请专利导致公开等情形；"
                        "对尚未履行期间设置许可费、服务费和提成的停止或调减机制，并允许被许可方解除合同，"
                        "对技术服务等仍有独立价值的部分按实际履行情况分项结算。"
                    ),
                    evidence=secret_evidence,
                    risk_level="高",
                )
                item.issue_type = "ADVERSE_CLAUSE"
            else:
                coverage = "PRESENT" if loss.get("reasonable") else "PARTIAL"
                _set_specialized_requirement_state(
                    item, coverage, secret_evidence, "ancillary_technical_secret_good_faith_use",
                    "技术秘密许可应审查秘密范围、对价基础及秘密性丧失后的费用调整、解除和结算机制。",
                    (
                        "技术秘密丧失秘密性后的费用停止、解除及结算机制已有合理安排。"
                        if loss.get("reasonable")
                        else "技术秘密范围和对价已有安排，但秘密性丧失后的费用调整、解除或结算机制仍不完整。"
                    ), "中",
                )
            _set_multi_element_state(item, [
                {"element_id": "technical_secret_scope", "status": "COVERED" if secret.get("scope") else "MISSING", "proposition": "技术秘密范围明确。", "evidence_terms": ["技术秘密", "未公开"]},
                {"element_id": "technical_secret_consideration", "status": "COVERED" if secret.get("separate_fee") else "PARTIALLY_COVERED", "proposition": "技术秘密许可对价已有安排。", "evidence_terms": ["技术秘密使用费", "技术秘密许可使用费"]},
                {
                    "element_id": "secret_loss_trigger",
                    "status": "COVERED" if loss.get("secret_loss_trigger") else "MISSING",
                    "proposition": (
                        "技术秘密全部或部分公开、进入公共领域及许可方主动公开等触发情形已有约定。"
                        if loss.get("secret_loss_trigger")
                        else "技术秘密全部或部分公开、进入公共领域及转让方主动公开等触发情形。"
                    ),
                    "evidence_terms": ["第三方公开", "公共领域", "申请专利导致"],
                },
                {"element_id": "future_fee_after_secret_loss", "status": "ADVERSE" if loss.get("unconditional_future_payment") else "COVERED" if loss.get("fee_stop_or_reduction") else "MISSING", "presence_status": "COVERED" if loss.get("unconditional_future_payment") or loss.get("fee_stop_or_reduction") else "MISSING", "direction": "ADVERSE" if loss.get("unconditional_future_payment") else "NEUTRAL", "proposition": "秘密性丧失后未来许可费、服务费或提成的停止、调减及结算规则。", "evidence_terms": ["继续支付", "停止支付", "许可费", "技术服务费", "提成"]},
                {"element_id": "termination_after_secret_loss", "status": "ADVERSE" if loss.get("termination_restricted") else "COVERED" if loss.get("termination_available") else "MISSING", "presence_status": "COVERED" if loss.get("termination_restricted") or loss.get("termination_available") else "MISSING", "direction": "ADVERSE" if loss.get("termination_restricted") else "NEUTRAL", "proposition": "非因被许可方原因丧失秘密性后的解除权。", "evidence_terms": ["解除合同", "不得"]},
                {"element_id": "separate_value_settlement", "status": "COVERED" if loss.get("separate_value_settlement") else "MISSING", "proposition": "技术服务等仍有独立价值部分的分项结算机制。"},
            ], secret_evidence)
            activate(item, "technical_secret", secret_evidence)
            item.decision_trace["technical_secret_loss_arrangement"] = dict(loss)
            item.decision_trace["technical_secret_is_main_subject"] = secret_is_main_subject
            item.fallback_reason = "技术秘密许可丧失秘密性后的存在性与内容合理性审查"
    return items


def _apply_technology_development_mode_rules(items: List[ReviewItemResult], contract_text: str) -> List[ReviewItemResult]:
    subtypes = _detect_technology_subtypes(contract_text)
    classification = classify_technology_transaction(contract_text)
    primary_subtype = str(classification.get("primary_subtype") or "")
    if primary_subtype == "TECHNICAL_CONSULTING":
        items = _apply_technical_consulting_semantic_rules(items, contract_text)
        return _apply_technology_common_semantic_rules(items, contract_text, classification)
    if primary_subtype == "TECHNICAL_SERVICE":
        items = _apply_technical_service_semantic_rules(items, contract_text)
        items = _apply_technology_common_semantic_rules(items, contract_text, classification)
        return _apply_development_improvement_applicability(items, contract_text)
    if "transfer" in subtypes and classification.get("tertiary_subtype") == "PATENT_RIGHT_TRANSFER":
        items = _apply_patent_transfer_semantic_rules(items, contract_text)
        items = _apply_technology_license_subtransaction_rules(items, contract_text, classification)
        return _apply_technology_common_semantic_rules(items, contract_text, classification)
    if "cooperative_development" in subtypes:
        items = _apply_cooperative_development_semantic_rules(items, contract_text)
        items = _apply_technology_common_semantic_rules(items, contract_text, classification)
        return _apply_development_improvement_applicability(items, contract_text)
    if (
        "entrusted_development" not in subtypes
        or "cooperative_development" in subtypes
        or classification.get("primary_subtype") != "ENTRUSTED_DEVELOPMENT"
    ):
        items = _apply_composite_technology_semantic_rules(items, contract_text)
        items = _apply_technology_license_subtransaction_rules(items, contract_text, classification)
        return _apply_technology_common_semantic_rules(items, contract_text, classification)

    items = _apply_entrusted_development_semantic_rules(items, contract_text)
    for item in items:
        if item.item_id != "TC-05-03" or item.coverage_status == COVERAGE_NOT_APPLICABLE:
            continue
        item.risk_level = "中"
        item.risk_point_description = (
            "委托开发合同中，技术秘密成果使用转让规则仍建议明确；但该项可由委托开发成果归属、保密和验收交付条款部分承接，"
            "缺失通常不属于直接阻碍合同履行的高风险。"
        )
        item.reasoning_summary = (
            f"{item.reasoning_summary} 当前合同识别为委托开发合同，TC-05-03 按委托开发场景降为中风险；"
            "如技术秘密成果具有核心商业价值，仍建议补充使用、转让、许可、收益分配和保密限制。"
        )
        item.fallback_reason = "技术合同开发方式风险校正"
    items = _apply_composite_technology_semantic_rules(items, contract_text)
    items = _apply_technology_common_semantic_rules(items, contract_text, classification)
    by_id = {item.item_id: item for item in items}
    for review_id, reason in {
        "TC-05-03": "委托开发预期形成源代码、技术信息及可能构成技术秘密的前景成果；规则在实际形成该类成果时适用。",
    }.items():
        item = by_id.get(review_id)
        if not item or item.coverage_status == COVERAGE_NOT_APPLICABLE:
            continue
        item.applicability = {
            "status": "CONDITIONALLY_APPLICABLE",
            "applicable": True,
            "conditional": True,
            "reason": reason,
            "machine_reason": reason,
            "user_reason": reason,
            "depends_on": ["technology_classification.primary_subtype", "contract_result_facts"],
        }
        item.needs_manual_review = False
        item.quality_gate_failure_reason = ""
        item.decision_trace["applicability_resolution"] = {
            "status": "CONDITIONALLY_APPLICABLE",
            "condition": "实际形成对应的技术秘密型成果或后续改进成果",
            "evidence_basis": "合同的研发性质及成果类型条款",
        }
    return _apply_development_improvement_applicability(items, contract_text)


