def _evidence_sentence(text: str, terms: tuple[str, ...]) -> str:
    segments = [segment.strip() for segment in re.split(r"(?<=[。；;])|\n", text or "") if segment.strip()]
    matched = [segment for segment in segments if any(term in _compact(segment) for term in terms)]
    return " ".join(matched[:3]) or (text or "").strip()


def _technical_evidence_candidate_matches(risk_group: str, fact_type: str, clause: ParsedClause) -> bool:
    text = _compact(clause if isinstance(clause, str) else clause.text)
    if risk_group == "technical_uncapped_cumulative_liability":
        provider_term = lambda pattern: bool(re.search(rf"(?:^|[。；;])乙方[^。；;]*{pattern}", text))
        checks = {
            "penalty": provider_term("违约金"),
            "refund": provider_term("(?:应返还|应退还|返还甲方|退还全部)"),
            "continued_performance": bool(re.search(r"乙方.{0,60}继续履行", text)),
            "damages": bool(re.search(r"乙方.{0,60}(?:赔偿损失|赔偿甲方|损害赔偿)", text)),
            "cumulative_application": "责任" in text and "同时适用" in text,
            "uncapped_liability": "乙方" in text and "责任" in text and any(term in text for term in ("不设最高限额", "无最高限额")),
        }
        return checks.get(fact_type, True)
    if risk_group == "short_data_objection_deemed_acceptance":
        if fact_type == "material_review_deadline":
            return "资料" in text and "接收后3个工作日" in text and any(term in text for term in ("提出", "通知", "改进", "更换"))
        if fact_type == "deemed_complete_data":
            return "视为" in text and "资料" in text and any(term in text for term in ("符合合同约定", "全部资料"))
        return any(term in text for term in ("数据源", "测试数据", "技术资料")) and bool(re.search(r"\d+", text))
    if risk_group == "data_retention_warranty_conflict":
        if fact_type == "data_deletion_deadline":
            return "资料" in text and any(term in text for term in ("归还", "删除"))
        if fact_type == "warranty_period":
            return any(term in text for term in ("12个月", "十二个月"))
        return "保证期内" in text and any(term in text for term in ("无偿修正", "返工", "替代方案"))
    if risk_group == "external_change_free_remediation":
        if fact_type == "external_change":
            return sum(term in text for term in ("调整业务规则", "修改测试环境", "更新第三方系统", "变更数据结构")) >= 2
        return "乙方" in text and any(term in text for term in ("无偿修正", "先行完成修正"))
    if risk_group == "personal_injury_liability_exclusion":
        if fact_type == "counterparty_fault":
            return "甲方过错" in text and "保险" in text
        return any(term in text for term in ("未购买保险", "保险金额不足")) and any(
            term in text for term in ("不予赔偿", "不承担责任")
        )
    if risk_group == "technical_timeline_conflict":
        if fact_type == "service_start_date":
            return bool(re.search(r"20\d{2}年\d{1,2}月\d{1,2}日至", text)) and any(
                term in text for term in ("服务期限", "服务开始", "履行期限", "合同期限", "有效期限")
            )
        if fact_type == "data_delivery_deadline":
            has_date = bool(re.search(r"20\d{2}年\d{1,2}月\d{1,2}日", text))
            is_technical_material_delivery = any(
                term in text for term in ("技术资料", "资料交付", "资料提供", "提交资料", "提供资料")
            )
            is_service_input_delivery = "甲方应在" in text and any(
                term in text for term in ("资料", "数据", "提供")
            )
            return has_date and (is_technical_material_delivery or is_service_input_delivery)
        if fact_type == "effective_condition":
            return any(term in text for term in ("签字", "签名")) and any(
                term in text for term in ("盖章", "加盖")
            ) and "生效" in text
        return "签订时间" in text or "签署日期" in text or "签订日期" in text
    if risk_group == "personal_information_processing_gap":
        if fact_type == "business_data_processing":
            explicit_delegation = any(term in text for term in (
                "个人信息委托处理", "受托处理个人信息", "受托处理个人数据",
                "委托乙方处理", "乙方受托处理", "授权乙方处理", "服务方受托处理", "开发方受托处理",
            ))
            actual_delivery = bool(re.search(
                r"(?:甲方|委托方|客户)[^。；]{0,25}(?:向|提供给|交付给|传输给)乙方[^。；]{0,45}"
                r"(?:个人信息|个人数据|员工信息|员工账号信息|用户信息|客户信息|消费者信息|订单数据|数据库备份|数据可能包括|数据包括)",
                text,
            ))
            actual_access_or_operation = bool(re.search(
                r"(?:乙方|服务方|开发方|受托方)[^。；]{0,30}(?:(?:可以|可|有权|需要|应当)?(?:访问|接入|操作|维护)"
                r"[^。；]{0,35}(?:生产数据库|生产环境|真实数据|个人信息|个人数据)|"
                r"(?:负责|承担)[^。；]{0,25}(?:云端托管|云托管|生产环境运维|数据迁移|数据备份|真实数据测试|生产数据测试))",
                text,
            ))
            copy_or_analysis = bool(re.search(
                r"(?:乙方|服务方|开发方|受托方)[^。；]{0,45}(?:复制|传输|保存|存储)[^。；]{0,45}"
                r"(?:乙方|服务方|开发方|受托方)[^。；]{0,20}(?:服务器|测试服务器|环境)|"
                r"(?:复制|传输)[^。；]{0,60}(?:服务器|测试服务器)[^。；]{0,30}(?:分析|测试|诊断)",
                text,
            ))
            return explicit_delegation or actual_delivery or actual_access_or_operation or copy_or_analysis
        explicit_personal = any(term in text for term in (
            "个人信息", "个人数据", "员工信息", "员工数据", "用户信息", "用户数据", "消费者信息", "消费者数据",
        ))
        explicit_categories = any(term in text for term in (
            "姓名", "工号", "电话号码", "手机号码", "手机号", "企业邮箱", "身份证", "人脸", "定位信息",
            "用户账号", "个人账号", "员工账号信息", "订单数据", "操作日志", "行为日志", "收货地址", "联系地址",
        ))
        return explicit_personal or explicit_categories
    if risk_group == "generic_demand_reduction_exit_cost":
        mechanism = (
            any(term in text for term in ("项目变更", "需求变更", "减少开发软件", "减少需求", "需求减少"))
            and any(term in text for term in ("费用下降", "价款下降", "开发费用下降", "调整后的开发费用"))
            and any(term in text for term in ("补贴", "补偿", "不得低于", "重新协商", "有权解除"))
        )
        return bool(mechanism)
    if risk_group == "generic_cumulative_liability_overlap":
        checks = {
            "daily_fixed_penalty": bool(re.search(r"(?:每超过|每逾期)[^。；]{0,50}(?:10,?000|壹万元)[^。；]{0,20}违约金", text)),
            "daily_percentage_penalty": bool(re.search(r"每逾期一天[^。；]{0,50}(?:1%|百分之一)[^。；]{0,30}违约金|(?:1%|百分之一)[^。；]{0,30}违约金", text)),
            "termination_penalty": "20%" in text and "违约金" in text and any(term in text for term in ("解除", "因甲方违约", "因乙方原因")),
            "all_loss_and_enforcement_costs": "全部损失" in text and sum(term in text for term in ("可得利益", "第三方", "律师费用", "诉讼费用")) >= 2,
        }
        return checks.get(fact_type, False)
    return True


def _evidence_span(
    text: str,
    terms: tuple[str, ...],
    risk_group: str = "",
    fact_type: str = "",
) -> tuple[str, int, int]:
    if risk_group == "personal_information_processing_gap" and _technical_evidence_candidate_matches(risk_group, fact_type, text):
        compact_start = min(
            (text.find(term) for term in (
                "个人信息委托处理", "受托处理个人信息", "受托处理个人数据",
                "委托乙方处理", "乙方受托处理", "授权乙方处理", "服务方受托处理", "开发方受托处理",
                "甲方向乙方提供的数据", "向乙方提供的数据可能包括",
                "乙方访问生产数据库", "乙方负责云端托管", "乙方负责生产环境运维",
            ) if text.find(term) >= 0),
            default=0,
        )
        quote = (text[compact_start:] or text).strip()
        return quote, compact_start, compact_start + len(quote)
    matches = list(re.finditer(r"[^。；;\n]*(?:[。；;\n]|$)", text or ""))
    candidates = [
        match for match in matches
        if match.group(0).strip() and any(_compact(term) in _compact(match.group(0)) for term in terms)
        and (
            not risk_group
            or risk_group in {"generic_demand_reduction_exit_cost", "generic_cumulative_liability_overlap"}
            or _technical_evidence_candidate_matches(risk_group, fact_type, match.group(0))
        )
    ]
    if not candidates:
        if risk_group:
            return "", -1, -1
        value = (text or "").strip()
        return value, 0, len(value)
    match = max(candidates, key=lambda row: sum(_compact(term) in _compact(row.group(0)) for term in terms))
    quote = match.group(0).strip()
    return quote, match.start(), match.end()


def _technical_evidence_role(risk_group: str, fact_type: str) -> str:
    if fact_type in {"business_data_processing", "background_ip_exists"}:
        return "TRIGGER_FACT"
    if risk_group == "technical_timeline_conflict":
        return "TIMELINE_INPUT"
    if risk_group in {"technical_background_ip_overtransfer", "data_retention_warranty_conflict"}:
        return "CONFLICTING_TERM"
    if risk_group == "personal_injury_liability_exclusion":
        return "LEGAL_VALIDITY_TERM"
    return "ADVERSE_TERM"


def _liability_parties(text: str) -> tuple[str, str]:
    """Resolve the direction of a liability clause without using its amount."""
    compact = _compact(text)
    termination = re.search(
        r"因(?P<liable>[甲乙]方)(?:违约|原因)[^。；]{0,80}导致(?P<beneficiary>[甲乙]方)解除",
        compact,
    )
    if termination:
        return termination.group("liable"), termination.group("beneficiary")
    directed = re.findall(
        r"(?P<liable>[甲乙]方)[^。；]{0,220}?应(?:当)?(?:同时)?[^。；]{0,100}?向"
        r"(?P<beneficiary>[甲乙]方)(?:支付|赔偿)",
        compact,
    )
    if directed:
        liable, beneficiary = directed[-1]
        return liable, beneficiary
    if "任何一方" in compact and "守约方" in compact:
        return "违约方", "守约方"
    return "", ""


def _liability_trigger(text: str, remedy_type: str, liable_party: str) -> tuple[str, str]:
    compact = _compact(text)
    if "逾期付款" in compact:
        return "逾期付款", "PAYMENT_DELAY"
    if "逾期交付" in compact:
        return "逾期交付", "DELIVERY_DELAY"
    if any(term in compact for term in ("修改各类错误", "整改")) and any(term in compact for term in ("每超过", "每逾期")):
        return "验收整改超时", "RECTIFICATION_DELAY"
    if remedy_type == "termination_penalty":
        return f"因{liable_party}违约或原因解除合同", "TERMINATION_FOR_BREACH"
    if remedy_type == "all_loss_and_enforcement_costs":
        return "其他违反合同情形", "GENERAL_BREACH_LOSS"
    return "违约", "OTHER_BREACH"


def _liability_amount_formula(text: str, remedy_type: str) -> str:
    compact = _compact(text)
    if remedy_type == "daily_fixed_penalty":
        amount = re.search(r"(?:￥|¥)?\s*([\d,]+(?:\.\d+)?)\s*元", compact)
        return f"{amount.group(1)}元/日" if amount else "固定金额/日"
    if remedy_type == "daily_percentage_penalty":
        rate = re.search(r"(\d+(?:\.\d+)?\s*(?:%|‰|‱)|百分之[^，。；]+|千分之[^，。；]+|万分之[^，。；]+)", compact)
        base = next((term for term in ("开发费用", "逾期金额", "合同价款", "合同总价款") if term in compact), "责任基数")
        return f"{base}×{rate.group(1)}/日" if rate else f"{base}×约定比例/日"
    if remedy_type == "termination_penalty":
        rate = re.search(r"(\d+(?:\.\d+)?%)", compact)
        base = next((term for term in ("剩余合同总价款", "合同总价款", "合同价款") if term in compact), "合同价款")
        return f"{base}×{rate.group(1)}" if rate else f"{base}×约定比例"
    return "全部实际损失及实现权利费用"


def _analyze_liability_clause_facts(clauses: List[ParsedClause]) -> Dict[str, Any]:
    """Build party-directed liability facts and clusters from parsed clauses.

    General loss clauses are attached to each otherwise qualifying directed
    cluster, but concrete liabilities are never moved across party directions.
    """
    facts: List[Dict[str, Any]] = []
    for clause in clauses:
        compact = _compact(clause.text)
        remedy_types: List[str] = []
        if "违约金" in compact and re.search(r"(?:每超过|每逾期)[^。；]{0,80}(?:元|￥|¥)", compact):
            remedy_types.append("daily_fixed_penalty")
        if "违约金" in compact and re.search(r"每逾期一天[^。；]{0,100}(?:%|‰|‱|百分之|千分之|万分之)", compact):
            remedy_types.append("daily_percentage_penalty")
        if (
            "违约金" in compact
            and re.search(r"因[甲乙]方(?:违约|原因)[^。；]{0,100}导致[甲乙]方解除", compact)
            and re.search(r"\d+(?:\.\d+)?%[^。；]{0,80}违约金", compact)
        ):
            remedy_types.append("termination_penalty")
        if "全部损失" in compact and sum(term in compact for term in ("可得利益", "第三方", "律师费用", "诉讼费用")) >= 2:
            remedy_types.append("all_loss_and_enforcement_costs")
        if not remedy_types:
            continue
        liable_party, beneficiary_party = _liability_parties(clause.text)
        for remedy_type in dict.fromkeys(remedy_types):
            trigger, breach_type = _liability_trigger(clause.text, remedy_type, liable_party)
            facts.append({
                "fact_id": f"LIAB-{clause.clause_id}-{remedy_type}",
                "liable_party": liable_party,
                "beneficiary_party": beneficiary_party,
                "trigger": trigger,
                "breach_type": breach_type,
                "remedy_type": remedy_type,
                "amount_formula": _liability_amount_formula(clause.text, remedy_type),
                "source_clause": {
                    "clause_id": clause.clause_id,
                    "clause_number": clause.location,
                    "clause_node_id": clause.node_id or clause.clause_id,
                    "text": clause.text,
                    "start_offset": clause.start_offset,
                    "source_text_hash": _stable_hash(_compact(clause.text)),
                },
            })

    general = [row for row in facts if row["remedy_type"] == "all_loss_and_enforcement_costs"]
    directed = [
        row for row in facts
        if row["remedy_type"] != "all_loss_and_enforcement_costs"
        and row["liable_party"] in {"甲方", "乙方"}
        and row["beneficiary_party"] in {"甲方", "乙方"}
        and row["liable_party"] != row["beneficiary_party"]
    ]
    pairs = sorted({(row["liable_party"], row["beneficiary_party"]) for row in directed})
    clusters: List[Dict[str, Any]] = []
    for liable_party, beneficiary_party in pairs:
        concrete = [
            dict(row) for row in directed
            if row["liable_party"] == liable_party and row["beneficiary_party"] == beneficiary_party
        ]
        # Two independent concrete remedies plus a general damages clause are
        # the minimum evidence of a possibly cumulative chain.
        source_ids = {row["source_clause"]["clause_id"] for row in concrete}
        if len(source_ids) < 2 or not general:
            continue
        attached_general = []
        for row in general:
            attached = dict(row)
            attached["declared_liable_party"] = row["liable_party"]
            attached["declared_beneficiary_party"] = row["beneficiary_party"]
            attached["liable_party"] = liable_party
            attached["beneficiary_party"] = beneficiary_party
            attached["cluster_attachment"] = "general breach damages applies to this directed party pair"
            attached_general.append(attached)
        cluster_facts = concrete + attached_general
        clusters.append({
            "cluster_id": f"LIABILITY-{liable_party}-TO-{beneficiary_party}",
            "liable_party": liable_party,
            "beneficiary_party": beneficiary_party,
            "facts": cluster_facts,
            "concrete_fact_count": len(concrete),
            "source_clause_ids": list(dict.fromkeys(row["source_clause"]["clause_id"] for row in cluster_facts)),
            "coexistence_basis": "same directed party pair; specific remedies plus general breach damages",
        })
    selected = max(
        clusters,
        key=lambda row: (row["concrete_fact_count"], len(row["source_clause_ids"])),
        default=None,
    )
    return {"facts": facts, "clusters": clusters, "selected_cluster": selected, "present": selected is not None}


def _build_liability_evidence_bundle(clauses: List[ParsedClause]) -> Dict[str, Any]:
    risk_group = "generic_cumulative_liability_overlap"
    analysis = _analyze_liability_clause_facts(clauses)
    cluster = analysis.get("selected_cluster") or {}
    items: List[Dict[str, Any]] = []
    for fact in cluster.get("facts") or []:
        source = fact["source_clause"]
        clause = next((row for row in clauses if row.clause_id == source["clause_id"]), None)
        if not clause:
            continue
        fact_type = fact["remedy_type"]
        quote = clause.text.strip()
        numeric_path = re.match(r"第(?P<path>\d+(?:\.\d+)*)项", str(clause.location or ""))
        parent_clause_id = numeric_path.group("path").split(".", 1)[0] if numeric_path else (clause.article_number or clause.section_number or "")
        items.append({
            "evidence_id": f"{risk_group}-{fact_type}-{clause.clause_id}",
            "clause_node_id": clause.node_id or clause.clause_id,
            "claim_id": f"{risk_group}:{fact_type}",
            "clause_id": clause.clause_id,
            "clause_number": clause.location,
            "heading_path": list(clause.heading_path or clause.section_path),
            "source_type": clause.source_type,
            "article_number": clause.article_number or None,
            "paragraph_number": clause.section_number or None,
            "sentence_index": clause.sentence_index,
            "start_offset": 0,
            "end_offset": len(quote),
            "document_offset": clause.start_offset,
            "source_text_hash": _stable_hash(_compact(quote)),
            "source_identity": {
                "document_id": clause.document_id,
                "section_id": clause.section_type,
                "parent_clause_id": parent_clause_id,
                "clause_id": clause.clause_id,
                "document_offset": clause.start_offset,
                "source_text_hash": _stable_hash(_compact(quote)),
            },
            "evidence_role": "ADVERSE_TERM",
            "fact_type": fact_type,
            "quoted_text": quote,
            "supports": fact_type,
            "polarity": "ADVERSE_OR_TRIGGER",
            "entailment_score": 0.99,
            "confidence": "high",
            "liable_party": fact["liable_party"],
            "beneficiary_party": fact["beneficiary_party"],
            "trigger": fact["trigger"],
            "breach_type": fact["breach_type"],
            "remedy_type": fact["remedy_type"],
            "amount_formula": fact["amount_formula"],
        })
    required = list(TECHNICAL_EVIDENCE_REQUIREMENTS[risk_group])
    covered = list(dict.fromkeys(row["fact_type"] for row in items))
    missing = [fact_type for fact_type in required if fact_type not in covered]
    for row in items:
        row["supports_claim_ids"] = [row["claim_id"]]
        row["fact_types"] = [row["fact_type"]]
        row["quoted_text_hash"] = _stable_hash(_compact(row["quoted_text"]))[:16]
        row["evidence_id"] = f"EV-{_stable_hash('|'.join(map(str, (row['clause_node_id'], row['fact_type'], row['quoted_text_hash']))))[:16]}"
    return {
        "bundle_id": f"EB-{risk_group}",
        "risk_id": "",
        "items": items,
        "evidence_items": items,
        "pre_dedup_item_count": len(items),
        "post_dedup_item_count": len(items),
        "required_fact_types": required,
        "covered_fact_types": covered,
        "missing_fact_types": missing,
        "required_claim_ids": [f"{risk_group}:{fact_type}" for fact_type in required],
        "supported_claim_ids": list(dict.fromkeys(row["claim_id"] for row in items)),
        "unsupported_claim_ids": [f"{risk_group}:{fact_type}" for fact_type in missing],
        "missing_element_types": [],
        "derived_facts": [],
        "liability_analysis": analysis,
        "liability_cluster": cluster,
        "entailment_status": "PASSED" if cluster and not missing else "FAILED",
    }


def _timeline_date_literal(iso_date: str) -> str:
    match = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", str(iso_date or ""))
    if not match:
        return ""
    return f"{int(match.group(1))}年{int(match.group(2))}月{int(match.group(3))}日"


def _build_timeline_evidence_bundle(
    clauses: List[ParsedClause], timeline: Dict[str, Any],
) -> Dict[str, Any]:
    """Bind a temporal conflict to the two dates that mathematically prove it."""
    risk_group = "technical_timeline_conflict"
    duration_conflicts = [
        row for row in timeline.get("conflicts") or []
        if row.get("type") == "MILESTONE_AFTER_PERFORMANCE_DURATION"
    ]
    if duration_conflicts and not timeline.get("primary_conflict_subject"):
        duration_months = timeline.get("performance_duration_months")
        duration_facts = list(timeline.get("performance_duration_facts") or [])
        milestone_facts = list(timeline.get("relative_milestone_facts") or [])

        def relative_evidence(fact: Dict[str, Any], fact_type: str) -> Optional[Dict[str, Any]]:
            raw_text = str(fact.get("raw_text") or "").strip()
            if not raw_text:
                return None
            clause = next(
                (row for row in clauses if _compact(raw_text) in _compact(row.text) or _compact(row.text) in _compact(raw_text)),
                None,
            )
            clause_id = str((clause.clause_id if clause else fact.get("fact_id")) or "")
            evidence_id = f"EV-{_stable_hash('|'.join((clause_id, fact_type, _compact(raw_text))))[:16]}"
            return {
                "evidence_id": evidence_id,
                "clause_node_id": str((clause.node_id if clause else clause_id) or clause_id),
                "claim_id": f"{risk_group}:{fact_type}",
                "supports_claim_ids": [f"{risk_group}:{fact_type}"],
                "fact_types": [fact_type],
                "clause_id": str((clause.clause_id if clause else "") or ""),
                "clause_number": str((clause.location if clause else fact.get("source_location")) or ""),
                "heading_path": list((clause.heading_path or clause.section_path) if clause else ["相对期限条款"]),
                "source_type": str((clause.source_type if clause else "CONTRACT_TEXT") or "CONTRACT_TEXT"),
                "start_offset": 0,
                "end_offset": len(raw_text),
                "document_offset": int((clause.start_offset if clause else -1) or -1),
                "source_text_hash": _stable_hash(_compact(raw_text)),
                "evidence_role": "TIMELINE_INPUT",
                "fact_type": fact_type,
                "quoted_text": raw_text,
                "supports": fact_type,
                "polarity": "TEMPORAL_INPUT",
                "entailment_score": 1.0,
                "confidence": "high",
            }

        items: List[Dict[str, Any]] = []
        if duration_facts:
            row = relative_evidence(duration_facts[0], "performance_duration_months")
            if row:
                items.append(row)
        conflicting_offsets = {
            Decimal(str(row.get("milestone_offset_months"))) for row in duration_conflicts
            if row.get("milestone_offset_months") is not None
        }
        for milestone in milestone_facts:
            if Decimal(str(milestone.get("months"))) not in conflicting_offsets:
                continue
            row = relative_evidence(milestone, "delivery_or_acceptance_offset_months")
            if row:
                items.append(row)
        milestone_offsets = sorted(conflicting_offsets)
        calculation = (
            f"合同约定服务在{duration_months}个月内完成；交付/验收节点位于第"
            f"{'、'.join(str(int(value) if value == value.to_integral_value() else float(value)) for value in milestone_offsets)}个月；"
            f"晚于{duration_months}个月的履行期限。"
        )
        input_ids = [str(row.get("evidence_id") or "") for row in items]
        calculation_row = {
            "evidence_id": f"EV-{_stable_hash('timeline-duration|' + _compact(calculation))[:16]}",
            "clause_node_id": "CALCULATION-RELATIVE-TIMELINE-CONSISTENCY",
            "claim_id": f"{risk_group}:calculation_result",
            "supports_claim_ids": [f"{risk_group}:calculation_result"],
            "fact_types": ["calculation_result"],
            "clause_id": "",
            "clause_number": "确定性相对期限校验",
            "heading_path": ["结构化计算"],
            "source_type": "CALCULATION",
            "start_offset": 0,
            "end_offset": len(calculation),
            "document_offset": -1,
            "source_text_hash": _stable_hash(_compact(calculation)),
            "evidence_role": "CALCULATION_RESULT",
            "fact_type": "calculation_result",
            "quoted_text": calculation,
            "supports": "timeline_conflict",
            "polarity": "CALCULATION",
            "entailment_score": 1.0,
            "confidence": "high",
            "derived_from_evidence_ids": input_ids,
        }
        items.append(calculation_row)
        required = ["performance_duration_months", "delivery_or_acceptance_offset_months", "calculation_result"]
        covered = list(dict.fromkeys(
            fact_type for row in items for fact_type in row.get("fact_types") or [row.get("fact_type")]
        ))
        missing = [fact_type for fact_type in required if fact_type not in covered]
        return {
            "bundle_id": f"EB-{risk_group}",
            "risk_id": "",
            "items": items,
            "evidence_items": items,
            "pre_dedup_item_count": len(items),
            "post_dedup_item_count": len(items),
            "required_fact_types": required,
            "covered_fact_types": covered,
            "missing_fact_types": missing,
            "required_claim_ids": [f"{risk_group}:{fact_type}" for fact_type in required],
            "supported_claim_ids": list(dict.fromkeys(
                claim_id for row in items for claim_id in row.get("supports_claim_ids") or []
            )),
            "unsupported_claim_ids": [f"{risk_group}:{fact_type}" for fact_type in missing],
            "missing_element_types": [],
            "derived_facts": [{
                "fact_type": "relative_timeline_conflict",
                "performance_duration_months": duration_months,
                "milestone_offsets_months": [
                    int(value) if value == value.to_integral_value() else float(value)
                    for value in milestone_offsets
                ],
                "operator": ">",
                "result": True,
            }],
            "entailment_status": "PASSED" if not missing else "FAILED",
        }
    effective_date = str(timeline.get("effective_date") or "")
    signing_date = str(timeline.get("contract_sign_date") or "")
    comparison_date = str(timeline.get("comparison_date") or effective_date or signing_date)
    comparison_basis = str(timeline.get("comparison_basis") or ("EFFECTIVE_DATE" if effective_date else "SIGNING_DATE"))
    comparison_fact_type = "contract_effective_date" if comparison_basis == "EFFECTIVE_DATE" else "contract_signing_date"
    conflict_subject = str(timeline.get("primary_conflict_subject") or "")
    performance_date = str(
        timeline.get("data_delivery_deadline")
        if conflict_subject == "TECHNICAL_MATERIAL_DELIVERY"
        else timeline.get("license_start_date")
        if conflict_subject == "LICENSE_START"
        else timeline.get("transfer_start_date")
        if conflict_subject == "TRANSFER_START"
        else timeline.get("service_start_date")
        if conflict_subject == "SERVICE_START"
        else timeline.get("earliest_performance_date")
        or ""
    )
    performance_literal = _timeline_date_literal(performance_date)
    comparison_literal = _timeline_date_literal(comparison_date)

    performance_markers = {
        "TECHNICAL_MATERIAL_DELIVERY": (
            "技术资料", "资料交付", "首批", "第一批", "相关资料",
            "甲方应在", "向乙方提供", "数据源", "测试数据",
        ),
        "SERVICE_START": ("服务期限", "服务开始", "履行期限", "合作期限", "合作开始", "开发周期", "合同期限", "有效期限"),
        "LICENSE_START": ("许可期限", "许可开始", "许可起始", "实施许可期限", "实施许可"),
        "TRANSFER_START": ("技术转让期限", "受让方使用权", "甲方使用权", "权利起始"),
        "PERFORMANCE_START": ("第一阶段", "第一期", "需求分析", "开发开始", "项目启动", "合作期限", "合作开始", "履行开始", "性能诊断"),
    }.get(conflict_subject, ("第一阶段", "开发开始", "履行开始", "项目进度", "开发进度"))
    performance_candidates = [
        clause for clause in clauses
        if performance_literal and performance_literal in clause.text
        and any(marker in clause.text for marker in performance_markers)
    ]
    def direct_clause_rank(clause: ParsedClause, markers: tuple[str, ...] = tuple()) -> tuple[int, int, int, str]:
        return (
            1 if str(clause.location or "") not in {"", "全文"} else 0,
            sum(marker in clause.text for marker in markers),
            -len(clause.text or ""),
            str(clause.clause_id),
        )

    performance_clause = max(
        performance_candidates,
        key=lambda clause: direct_clause_rank(clause, performance_markers),
        default=None,
    )
    direct_effective_date_candidates = [
        clause for clause in clauses
        if comparison_basis == "EFFECTIVE_DATE"
        and comparison_literal and comparison_literal in clause.text and "生效" in clause.text
    ]
    effective_condition_candidates = [
        clause for clause in clauses
        if "生效" in clause.text
        and any(marker in clause.text for marker in ("签字", "签名", "盖章", "加盖"))
    ]
    signature_candidates = [
        clause for clause in clauses
        if comparison_literal and comparison_literal in clause.text
        and any(marker in clause.text for marker in ("签订时间", "签署日期", "签订日期"))
    ]
    direct_effective_date_clause = max(
        direct_effective_date_candidates,
        key=lambda clause: direct_clause_rank(clause, ("生效日期", "签订时间", "签署日期", "签订日期")),
        default=None,
    )
    effective_condition_clause = (
        max(effective_condition_candidates, key=lambda clause: direct_clause_rank(clause, ("签字", "签名", "盖章", "生效")))
        if effective_condition_candidates
        else direct_effective_date_clause
    )
    signature_clause = max(
        signature_candidates,
        key=lambda clause: direct_clause_rank(clause, ("签订时间", "签署日期", "签订日期")),
        default=direct_effective_date_clause,
    )

    def evidence_row(
        clause: ParsedClause, fact_type: str, quote: str, supports: List[str],
    ) -> Dict[str, Any]:
        local_start = max(0, clause.text.find(quote))
        local_end = local_start + len(quote)
        quote_hash = _stable_hash(_compact(quote))[:16]
        evidence_id = f"EV-{_stable_hash('|'.join((clause.node_id or clause.clause_id, fact_type, quote_hash)))[:16]}"
        return {
            "evidence_id": evidence_id,
            "clause_node_id": clause.node_id or clause.clause_id,
            "claim_id": supports[0],
            "supports_claim_ids": supports,
            "fact_types": [fact_type],
            "clause_id": clause.clause_id,
            "clause_number": clause.location,
            "heading_path": list(clause.heading_path or clause.section_path),
            "source_type": clause.source_type,
            "article_number": clause.article_number or None,
            "paragraph_number": clause.section_number or None,
            "sentence_index": clause.sentence_index,
            "start_offset": local_start,
            "end_offset": local_end,
            "document_offset": clause.start_offset + local_start if clause.start_offset >= 0 else -1,
            "source_text_hash": _stable_hash(_compact(quote)),
            "source_identity": {
                "document_id": clause.document_id,
                "section_id": clause.section_type,
                "parent_clause_id": clause.article_number or clause.section_number or "",
                "clause_id": clause.clause_id,
                "document_offset": clause.start_offset + local_start if clause.start_offset >= 0 else -1,
                "source_text_hash": _stable_hash(_compact(quote)),
            },
            "evidence_role": "TIMELINE_INPUT",
            "fact_type": fact_type,
            "quoted_text": quote,
            "quoted_text_hash": quote_hash,
            "supports": fact_type,
            "polarity": "TEMPORAL_INPUT",
            "entailment_score": 1.0,
            "confidence": "high",
        }

    def focused_quote(
        clause: ParsedClause,
        literal: str,
        markers: tuple[str, ...],
    ) -> str:
        """Return the smallest source span that proves one timeline input.

        Signature pages often live in one large parsed clause together with
        addresses, e-mail addresses and both parties' signature blocks.  The
        timeline evidence must bind the date/condition itself, not serialize
        that unrelated material into the report.
        """
        text = clause.text or ""
        anchor = text.find(literal) if literal else -1
        if anchor < 0:
            marker_positions = [text.find(marker) for marker in markers if text.find(marker) >= 0]
            anchor = min(marker_positions) if marker_positions else 0
        line_start = text.rfind("\n", 0, anchor) + 1
        line_end = text.find("\n", anchor)
        if line_end < 0:
            line_end = len(text)
        quote = text[line_start:line_end].strip()
        if quote and (not literal or literal in quote):
            return quote
        marker_positions = [text.rfind(marker, 0, anchor + 1) for marker in markers]
        marker_positions = [position for position in marker_positions if position >= 0]
        start = max(marker_positions) if marker_positions else max(0, anchor - 40)
        end = min(len(text), anchor + len(literal) + 24)
        return text[start:end].strip()

    items: List[Dict[str, Any]] = []
    if performance_clause:
        date_position = performance_clause.text.find(performance_literal)
        marker_positions = [
            performance_clause.text.rfind(marker, 0, date_position)
            for marker in performance_markers
            if performance_clause.text.rfind(marker, 0, date_position) >= 0
        ]
        quote_start = min(marker_positions) if marker_positions else max(0, date_position - 80)
        quote_end = performance_clause.text.find("\n", date_position)
        if quote_end < 0:
            quote_end = min(len(performance_clause.text), date_position + len(performance_literal) + 40)
        performance_quote = performance_clause.text[quote_start:quote_end].strip()
        items.append(evidence_row(
            performance_clause,
            "performance_start_date",
            performance_quote,
            [f"{risk_group}:performance_start_date"],
        ))
    requires_effective_condition = (
        str(timeline.get("effective_date_basis") or "") == "SIGNATURE_DATE_PLUS_EFFECTIVE_CONDITION"
    )
    # Preserve the signed-effective condition as supporting context whenever
    # it exists, while only making it a required proof input for derived
    # signature-date effective dates.
    if effective_condition_candidates and effective_condition_clause:
        condition_quote = focused_quote(
            effective_condition_clause,
            "",
            ("签字", "签名", "盖章", "加盖"),
        )
        # A heading such as "第二十五条 生效" is not the effective
        # condition itself; only retain the operative signature sentence.
        if any(term in condition_quote for term in ("签字", "签名", "盖章", "加盖")):
            items.append(evidence_row(
                effective_condition_clause,
                "effective_condition",
                condition_quote,
                [f"{risk_group}:effective_condition"],
            ))
    if comparison_basis == "SIGNING_DATE" and signature_clause:
        signature_quote = focused_quote(
            signature_clause,
            comparison_literal,
            ("签订时间", "签署日期", "签订日期", "生效日期"),
        )
        items.append(evidence_row(
            signature_clause,
            "contract_signing_date",
            signature_quote,
            [f"{risk_group}:contract_signing_date"],
        ))
    elif comparison_basis == "EFFECTIVE_DATE" and str(timeline.get("effective_date_basis") or "") == "EXPLICIT_EFFECTIVE_DATE" and direct_effective_date_clause:
        direct_quote = focused_quote(
            direct_effective_date_clause,
            comparison_literal,
            ("生效日期", "签订时间", "签署日期", "签订日期"),
        )
        items.append(evidence_row(
            direct_effective_date_clause,
            "contract_effective_date",
            direct_quote,
            [f"{risk_group}:contract_effective_date"],
        ))
    elif comparison_basis == "EFFECTIVE_DATE" and signature_clause:
        signature_quote = focused_quote(
            signature_clause,
            comparison_literal,
            ("签订时间", "签署日期", "签订日期"),
        )
        items.append(evidence_row(
            signature_clause,
            "contract_effective_date",
            signature_quote,
            [f"{risk_group}:contract_effective_date"],
        ))
    elif effective_condition_clause:
        # Keep the condition as contextual evidence when no dated signature
        # line was parsed; it cannot by itself prove the comparison date.
        if not requires_effective_condition:
            items.append(evidence_row(
                effective_condition_clause,
                "effective_condition",
                focused_quote(
                    effective_condition_clause,
                    "",
                    ("签字", "签名", "盖章", "加盖", "生效"),
                ),
                [f"{risk_group}:effective_condition"],
            ))
    pre_dedup_item_count = len(items)
    deduplicated_inputs: Dict[tuple[str, str, str], Dict[str, Any]] = {}
    for row in items:
        source_key = (
            str(row.get("clause_node_id") or row.get("clause_id") or ""),
            str(row.get("quoted_text_hash") or _stable_hash(_compact(str(row.get("quoted_text") or "")))[:16]),
            str(row.get("source_type") or ""),
        )
        existing = deduplicated_inputs.get(source_key)
        if existing is None:
            deduplicated_inputs[source_key] = row
            continue
        existing["fact_types"] = list(dict.fromkeys(
            list(existing.get("fact_types") or [existing.get("fact_type")])
            + list(row.get("fact_types") or [row.get("fact_type")])
        ))
        existing["supports_claim_ids"] = list(dict.fromkeys(
            list(existing.get("supports_claim_ids") or [])
            + list(row.get("supports_claim_ids") or [])
        ))
    items = list(deduplicated_inputs.values())
    if performance_date and comparison_date:
        comparison_label = "合同生效日期" if comparison_basis == "EFFECTIVE_DATE" else "合同签订日期"
        result_label = "生效前履行" if comparison_basis == "EFFECTIVE_DATE" else "签订前履行"
        calculation = (
            f"履行开始日期 = {performance_date}；{comparison_label} = {comparison_date}；"
            f"{performance_date} < {comparison_date}，存在{result_label}事实。"
        )
        quote_hash = _stable_hash(_compact(calculation))[:16]
        calculation_input_ids = [str(row.get("evidence_id") or "") for row in items if row.get("evidence_id")]
        items.append({
            "evidence_id": f"EV-{_stable_hash('timeline|' + quote_hash)[:16]}",
            "clause_node_id": "CALCULATION-TIMELINE-CONSISTENCY",
            "claim_id": f"{risk_group}:calculation_result",
            "supports_claim_ids": [f"{risk_group}:calculation_result"],
            "fact_types": ["calculation_result"],
            "clause_id": "",
            "clause_number": "确定性时间一致性校验",
            "heading_path": ["结构化计算"],
            "source_type": "CALCULATION",
            "article_number": None,
            "paragraph_number": None,
            "sentence_index": 1,
            "start_offset": 0,
            "end_offset": len(calculation),
            "document_offset": -1,
            "source_text_hash": _stable_hash(_compact(calculation)),
            "evidence_role": "CALCULATION_RESULT",
            "fact_type": "calculation_result",
            "quoted_text": calculation,
            "quoted_text_hash": quote_hash,
            "supports": "timeline_conflict",
            "polarity": "CALCULATION",
            "entailment_score": 1.0,
            "confidence": "high",
            "derived_from_evidence_ids": calculation_input_ids,
        })
    required = ["performance_start_date", comparison_fact_type, "calculation_result"]
    if str(timeline.get("effective_date_basis") or "") == "SIGNATURE_DATE_PLUS_EFFECTIVE_CONDITION":
        required.insert(1, "effective_condition")
    covered = list(dict.fromkeys(
        fact_type for row in items for fact_type in row.get("fact_types") or [row.get("fact_type")]
    ))
    missing = [fact_type for fact_type in required if fact_type not in covered]
    return {
        "bundle_id": f"EB-{risk_group}",
        "risk_id": "",
        "items": items,
        "evidence_items": items,
        "pre_dedup_item_count": pre_dedup_item_count + 1,
        "post_dedup_item_count": len(items),
        "required_fact_types": required,
        "covered_fact_types": covered,
        "missing_fact_types": missing,
        "required_claim_ids": [f"{risk_group}:{fact_type}" for fact_type in required],
        "supported_claim_ids": list(dict.fromkeys(
            claim_id for row in items for claim_id in row.get("supports_claim_ids") or []
        )),
        "unsupported_claim_ids": [f"{risk_group}:{fact_type}" for fact_type in missing],
        "missing_element_types": [],
        "derived_facts": (
            [{
                "fact_type": "contract_effective_date",
                "value": effective_date,
                "source_node_ids": list(dict.fromkeys(
                    clause.node_id or clause.clause_id
                    for clause in (effective_condition_clause, signature_clause)
                    if clause
                )),
                "derivation": "effective_condition + signature_date",
            }]
            if str(timeline.get("effective_date_basis") or "") == "SIGNATURE_DATE_PLUS_EFFECTIVE_CONDITION"
            else []
        ) + [{
            "fact_type": "timeline_conflict",
            "performance_start_date": performance_date,
            comparison_fact_type: comparison_date,
            "comparison_basis": comparison_basis,
            "operator": "<",
            "result": bool(performance_date and comparison_date and performance_date < comparison_date),
        }],
        "entailment_status": "PASSED" if not missing and performance_date < comparison_date else "FAILED",
    }


def _build_technical_evidence_bundle(
    risk_group: str,
    clauses: List[ParsedClause],
    payment: Dict[str, Any],
    timeline: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    if risk_group == "generic_cumulative_liability_overlap":
        return _build_liability_evidence_bundle(clauses)
    if risk_group == "technical_timeline_conflict":
        return _build_timeline_evidence_bundle(
            clauses,
            timeline or analyze_timeline("\n".join(clause.text for clause in clauses)),
        )
    requirements = TECHNICAL_EVIDENCE_REQUIREMENTS.get(risk_group, {})
    items: List[Dict[str, Any]] = []
    covered: List[str] = []
    absence_missing_elements: List[str] = []
    for fact_type, terms in requirements.items():
        candidates = [
            clause for clause in clauses
            if any(_compact(term) in _compact(clause.text) for term in terms)
            and _technical_evidence_candidate_matches(risk_group, fact_type, clause)
        ]
        if not candidates:
            continue
        clause = max(
            candidates,
            key=lambda row: (
                sum(_compact(term) in _compact(row.text) for term in terms)
                + (
                    sum(
                        any(_compact(term) in _compact(row.text) for term in related_terms)
                        for related_terms in requirements.values()
                    )
                    if risk_group == "technical_uncapped_cumulative_liability" else 0
                )
            ),
        )
        quote, start_offset, end_offset = _evidence_span(clause.text, terms, risk_group, fact_type)
        if not quote:
            continue
        claim_id = f"{risk_group}:{fact_type}"
        numeric_path = re.match(r"第(?P<path>\d+(?:\.\d+)*)项", str(clause.location or ""))
        parent_clause_id = numeric_path.group("path").split(".", 1)[0] if numeric_path else (clause.article_number or clause.section_number or "")
        document_offset = clause.start_offset + start_offset if clause.start_offset >= 0 and start_offset >= 0 else -1
        calculation_input_ids = [str(row.get("evidence_id") or "") for row in items if row.get("evidence_id")]
        items.append({
            "evidence_id": f"{risk_group}-{fact_type}",
            "clause_node_id": clause.node_id or clause.clause_id,
            "claim_id": claim_id,
            "clause_id": clause.clause_id,
            "clause_number": clause.location,
            "heading_path": list(clause.heading_path or clause.section_path),
            "source_type": clause.source_type,
            "article_number": clause.article_number or None,
            "paragraph_number": clause.section_number or None,
            "sentence_index": clause.sentence_index,
            "start_offset": start_offset,
            "end_offset": end_offset,
            "document_offset": document_offset,
            "source_text_hash": _stable_hash(_compact(quote)),
            "source_identity": {
                "document_id": clause.document_id,
                "section_id": clause.section_type,
                "parent_clause_id": parent_clause_id,
                "clause_id": clause.clause_id,
                "document_offset": document_offset,
                "source_text_hash": _stable_hash(_compact(quote)),
            },
            "evidence_role": _technical_evidence_role(risk_group, fact_type),
            "fact_type": fact_type,
            "quoted_text": quote,
            "supports": fact_type,
            "polarity": "ADVERSE_OR_TRIGGER",
            "entailment_score": 0.98,
            "confidence": "high",
        })
        covered.append(fact_type)

    if risk_group == "personal_information_processing_gap":
        strong_fact_detectors = {
            "production_database_access": lambda value: (
                any(term in value for term in ("乙方", "服务方", "开发方", "受托方"))
                and "访问" in value and "生产数据库" in value
            ),
            "data_transfer_to_provider": lambda value: (
                any(term in value for term in ("甲方向乙方提供", "甲方可以向乙方提供", "委托方向乙方提供", "客户向乙方提供"))
                and any(term in value for term in ("订单数据", "员工账号信息", "数据库备份", "个人信息", "个人数据"))
            ),
            "data_copy_to_provider_server": lambda value: (
                any(term in value for term in ("复制至乙方", "复制到乙方", "传输至乙方", "保存至乙方"))
                and any(term in value for term in ("服务器", "测试服务器", "测试环境"))
            ),
            "data_analysis_by_provider": lambda value: (
                bool(re.search(
                    r"(?:复制|传输|保存|存储)[^。；]{0,60}(?:服务器|测试服务器)[^。；]{0,35}(?:分析|诊断|测试|优化)|"
                    r"(?:乙方|服务方|开发方|受托方)[^。；]{0,30}(?:对|将)[^。；]{0,25}"
                    r"(?:甲方|委托方|客户)?[^。；]{0,15}(?:数据|数据库备份|订单数据|员工账号信息)"
                    r"[^。；]{0,20}(?:进行)?(?:分析|诊断|测试|优化)",
                    value,
                ))
            ),
        }
        strong_fact_matches: Dict[str, ParsedClause] = {}
        for fact_type, detector in strong_fact_detectors.items():
            candidates = [
                clause for clause in clauses
                if detector(_compact(clause.text))
            ]
            if candidates:
                strong_fact_matches[fact_type] = min(
                    candidates,
                    key=lambda row: (
                        0 if row.section_type in {"正式合同条款", "附件"} and str(row.location or "") not in {"", "全文"} else 1,
                        len(row.text or ""),
                        str(row.clause_id),
                    ),
                )
        # One already-covered generic processing clause does not need a
        # duplicate evidence row.  Preserve atomic strong-fact rows only when
        # the contract contains a real multi-step access/transfer/copy chain.
        if len(strong_fact_matches) >= 2:
            for fact_type, clause in strong_fact_matches.items():
                clause_text = _compact(clause.text)
                claim_id = f"{risk_group}:{fact_type}"
                row = _clause_public_dict(clause)
                quote = _technology_proposition_quote(clause.text, tuple(
                    term for term in (
                        "生产数据库", "订单数据", "员工账号信息", "数据库备份",
                        "复制至乙方测试服务器", "复制到乙方测试服务器", "分析",
                    ) if term in clause_text
                )) or clause.text.strip()
                row.update({
                    "clause_node_id": clause.node_id or clause.clause_id,
                    "claim_id": claim_id,
                    "clause_number": clause.location,
                    "fact_type": fact_type,
                    "quoted_text": quote,
                    "start_offset": max(0, clause.text.find(quote)),
                    "end_offset": max(0, clause.text.find(quote)) + len(quote),
                    "evidence_role": "STRONG_PROCESSING_FACT",
                    "supports": fact_type,
                    "polarity": "AFFIRMATIVE",
                    "entailment_score": 1.0,
                    "confidence": "high",
                })
                items.append(row)
                covered.append(fact_type)
                requirements = {**requirements, fact_type: tuple()}
        full_text = _compact(" ".join(clause.text for clause in clauses))
        structured_personal = analyze_personal_information_processing(
            "\n".join(clause.text for clause in clauses)
        )
        structured_categories = list(structured_personal.get("personal_data_categories") or [])
        control_terms = {
            "处理目的": ("处理目的", "使用目的"),
            "处理期限": ("处理期限", "保存期限"),
            "处理方式": ("处理方式", "处理活动"),
            "信息种类": ("信息种类", "数据范围", "处理范围"),
            "安全措施": ("安全措施", "加密", "访问控制", "权限控制"),
            "监督机制": ("监督", "审计", "检查权"),
            "安全事件通知": ("安全事件", "数据泄露", "事件通知"),
            "转委托限制": ("转委托", "再委托", "分包处理"),
            "终止后的返还、删除及证明机制": ("删除证明", "销毁证明", "返还并删除", "终止后删除"),
        }
        absence_missing_elements = [
            name for name, aliases in control_terms.items()
            if not any(_compact(alias) in full_text for alias in aliases)
            and not (name == "信息种类" and structured_categories)
        ]
        if absence_missing_elements:
            fact_type = "absence_search"
            claim_id = f"{risk_group}:{fact_type}"
            searched_scope = "合同正文及全部附件"
            items.append({
                "evidence_id": f"{risk_group}-{fact_type}",
                "clause_node_id": f"SEARCH-AUDIT-{risk_group}",
                "claim_id": claim_id,
                "clause_id": "",
                "clause_number": "SEARCH_AUDIT",
                "heading_path": ["结构化缺失检索"],
                "source_type": "SEARCH_AUDIT",
                "article_number": None,
                "paragraph_number": None,
                "sentence_index": 1,
                "start_offset": -1,
                "end_offset": -1,
                "evidence_role": "ABSENCE_EVIDENCE",
                "fact_type": fact_type,
                "quoted_text": f"已检索{searched_scope}，未发现完整约定：{'、'.join(absence_missing_elements)}。",
                "supports": fact_type,
                "polarity": "ABSENCE_CONFIRMED",
                "entailment_score": 1.0,
                "confidence": "high",
                "searched_scope": searched_scope,
                "search_scope": searched_scope,
                "missing_elements": absence_missing_elements,
            })
            covered.append(fact_type)

    if risk_group == "payment_formula_inconsistency":
        requirements = {"contract_total": tuple()}

        def source_clause_for(start: int, raw_text: str) -> Optional[ParsedClause]:
            exact = next((row for row in clauses if row.start_offset <= start < row.end_offset), None)
            return exact or next((row for row in clauses if _compact(raw_text) in _compact(row.text)), None)

        def add_payment_input(
            fact_type: str, raw_text: str, absolute_start: int, absolute_end: int,
            *, evidence_role: str = "CALCULATION_INPUT", polarity: str = "NUMERIC_INPUT",
        ) -> None:
            clause = source_clause_for(absolute_start, raw_text)
            if not clause:
                return
            local_start = max(0, absolute_start - clause.start_offset) if clause.start_offset >= 0 else 0
            local_end = local_start + len(raw_text)
            items.append({
                "evidence_id": f"{risk_group}-{fact_type}", "clause_node_id": clause.node_id or clause.clause_id,
                "claim_id": f"{risk_group}:{fact_type}", "clause_id": clause.clause_id,
                "clause_number": clause.location, "heading_path": list(clause.heading_path or clause.section_path),
                "source_type": clause.source_type, "article_number": clause.article_number or None,
                "paragraph_number": clause.section_number or None, "sentence_index": clause.sentence_index,
                "start_offset": local_start, "end_offset": local_end,
                "document_offset": absolute_start,
                "evidence_role": evidence_role, "fact_type": fact_type, "quoted_text": raw_text.strip(),
                "supports": fact_type, "polarity": polarity, "entailment_score": 0.99, "confidence": "high",
            })
            covered.append(fact_type)

        total_fact = payment.get("global_total_candidate") or next(iter(payment.get("contract_total_candidates") or []), None)
        if total_fact:
            add_payment_input(
                "contract_total", str(total_fact.get("raw_text") or ""),
                int(total_fact.get("start_offset") or 0), int(total_fact.get("end_offset") or 0),
            )
        for index, base_fact in enumerate(payment.get("component_total_candidates") or [], start=1):
            fact_type = f"payment_base_{index}"
            requirements[fact_type] = tuple()
            add_payment_input(
                fact_type, str(base_fact.get("raw_text") or ""),
                int(base_fact.get("start_offset") or 0), int(base_fact.get("end_offset") or 0),
            )
        for index, node in enumerate(payment.get("nodes") or [], start=1):
            fact_type = f"payment_node_{index}"
            requirements[fact_type] = tuple()
            add_payment_input(
                fact_type, str(node.get("raw_text") or ""),
                int(node.get("start_offset") or 0), int(node.get("end_offset") or 0),
            )
        for index, direction_fact in enumerate(payment.get("payment_direction_outliers") or [], start=1):
            fact_type = f"payment_direction_outlier_{index}"
            source_text = str(direction_fact.get("source_text") or "").strip()
            if not source_text:
                continue
            requirements[fact_type] = tuple()
            add_payment_input(
                fact_type, source_text,
                int(direction_fact.get("start_offset") or 0),
                int(direction_fact.get("end_offset") or len(source_text)),
                evidence_role="DIRECT_CONTRACT_EVIDENCE",
                polarity="FACT_OR_AUDIT",
            )
        currency = str(payment.get("currency") or "CNY")
        is_budget_investment = payment.get("consistency_context") == "BUDGET_INVESTMENT"
        payment_groups = list(payment.get("payment_groups") or [])
        component_reconciliation = ""
        if payment.get("component_total_sum") is not None and payment.get("contract_total") is not None:
            component_amounts = " + ".join(
                str(row.get("value")) for row in payment.get("component_total_candidates") or []
            )
            component_reconciliation = (
                f"分项价款{component_amounts} = {payment.get('component_total_sum')} {currency}，"
                f"合同固定总额{payment.get('contract_total')} {currency}，"
                f"分项差额{payment.get('component_total_delta')} {currency}；"
            )
        if len(payment_groups) > 1:
            group_formulas = []
            for group in payment_groups:
                if str(group.get("status") or "") != "INCONSISTENT":
                    continue
                pct_formula = " + ".join(f"{value}%" for value in group.get("percentages") or [] if value is not None)
                amount_formula = " + ".join(str(value) for value in group.get("amounts") or [] if value is not None)
                pct_calculation = (
                    f"{pct_formula} = {group.get('percentage_total')}%；"
                    if pct_formula and not group.get("percentage_total_inferred") else ""
                )
                group_formulas.append(
                    f"{group.get('label')}基数{group.get('base_amount')} {currency}："
                    f"{pct_calculation}"
                    f"{amount_formula} = {group.get('amount_total')} {currency}；"
                    f"差额{group.get('amount_delta')} {currency}"
                )
            inconsistent_group_text = ("；".join(group_formulas) + "；") if group_formulas else ""
            inferred_overall_percentage = (
                f"，折合合同固定总额的{payment.get('percentage_total')}%"
                if payment.get("percentage_total") is not None else ""
            )
            calculation = (
                component_reconciliation + inconsistent_group_text
                + f"固定付款合计{payment.get('amount_total')} {currency}{inferred_overall_percentage}，"
                f"合同固定总额{payment.get('contract_total')} {currency}，"
                f"总差额{payment.get('amount_delta')} {currency}。"
            )
        elif is_budget_investment:
            calculation = (
                f"研发预算总额：{payment.get('contract_total')} {currency}；"
                f"双方投入金额：{' + '.join(str(row.get('effective_amount')) for row in payment.get('nodes', []) if row.get('effective_amount') is not None)}"
                f" = {payment.get('amount_total')} {currency}；差额：{payment.get('amount_delta')} {currency}。"
            )
        else:
            calculation = (
                f"合同总价：{payment.get('contract_total')} {currency}；付款比例："
                f"{' + '.join(str(row.get('effective_percentage')) + '%' for row in payment.get('nodes', []) if row.get('effective_percentage') is not None)} = {payment.get('percentage_total')}%；"
                f"付款金额：{' + '.join(str(row.get('effective_amount')) for row in payment.get('nodes', []) if row.get('effective_amount') is not None)} = {payment.get('amount_total')} {currency}；"
                f"差额：{payment.get('amount_delta')} {currency}。"
            )
        calculation_input_ids = [str(row.get("evidence_id") or "") for row in items if row.get("evidence_id")]
        items.append({
            "evidence_id": f"{risk_group}-calculation_result", "clause_node_id": "CALCULATION-PAYMENT-SCHEDULE",
            "claim_id": f"{risk_group}:calculation_result",
            "clause_id": "", "clause_number": "确定性付款公式校验", "heading_path": ["结构化计算"],
            "source_type": "CALCULATION",
            "article_number": None, "paragraph_number": None, "sentence_index": 1,
            "start_offset": 0, "end_offset": len(calculation),
            "evidence_role": "CALCULATION_RESULT", "fact_type": "calculation_result", "quoted_text": calculation,
            "supports": "payment_formula_inconsistency", "polarity": "CALCULATION", "entailment_score": 1.0, "confidence": "high",
            "derived_from_evidence_ids": calculation_input_ids,
        })
        covered.append("calculation_result")
        requirements = {**requirements, "calculation_result": tuple()}

    derived_facts: List[Dict[str, Any]] = []
    if risk_group == "technical_timeline_conflict":
        condition = next((row for row in items if row["fact_type"] == "effective_condition"), None)
        signature = next((row for row in items if row["fact_type"] == "signature_date"), None)
        if condition and signature:
            derived_claim = f"{risk_group}:contract_effective_date"
            condition.setdefault("supports_claim_ids", [condition["claim_id"]]).append(derived_claim)
            signature.setdefault("supports_claim_ids", [signature["claim_id"]]).append(derived_claim)
            date_match = re.search(r"20\d{2}年\d{1,2}月\d{1,2}日", signature["quoted_text"])
            derived_facts.append({
                "fact_type": "contract_effective_date",
                "value": date_match.group(0) if date_match else "",
                "source_node_ids": [condition["clause_node_id"], signature["clause_node_id"]],
                "derivation": "effective_condition + signature_date",
            })
            requirements = {**requirements, "contract_effective_date": tuple()}
            covered.append("contract_effective_date")

    required = list(requirements)
    missing = [fact_type for fact_type in required if fact_type not in covered]
    required_claim_ids = [f"{risk_group}:{fact_type}" for fact_type in required]
    deduplicated: List[Dict[str, Any]] = []
    seen_evidence: Dict[tuple[Any, ...], Dict[str, Any]] = {}
    evidence_id_remap: Dict[str, str] = {}
    for row in items:
        original_evidence_id = str(row.get("evidence_id") or "")
        quote_hash = _stable_hash(_compact(str(row.get("quoted_text") or "")))[:16]
        key = (row["clause_node_id"], row["start_offset"], row["end_offset"], quote_hash)
        claim_ids = list(dict.fromkeys(row.get("supports_claim_ids") or [row["claim_id"]]))
        fact_types = list(dict.fromkeys(row.get("fact_types") or [row["fact_type"]]))
        if key in seen_evidence:
            existing = seen_evidence[key]
            existing["supports_claim_ids"] = list(dict.fromkeys(existing["supports_claim_ids"] + claim_ids))
            existing["fact_types"] = list(dict.fromkeys(existing["fact_types"] + fact_types))
            continue
        row["supports_claim_ids"] = claim_ids
        row["fact_types"] = fact_types
        row["quoted_text_hash"] = quote_hash
        row["evidence_id"] = f"EV-{_stable_hash('|'.join(map(str, key)))[:16]}"
        if original_evidence_id:
            evidence_id_remap[original_evidence_id] = row["evidence_id"]
        seen_evidence[key] = row
        deduplicated.append(row)
    for row in deduplicated:
        if row.get("derived_from_evidence_ids"):
            row["derived_from_evidence_ids"] = list(dict.fromkeys(
                evidence_id_remap.get(str(evidence_id), str(evidence_id))
                for evidence_id in row.get("derived_from_evidence_ids") or []
                if str(evidence_id)
            ))
    supported_claim_ids = list(dict.fromkeys(
        claim_id for row in deduplicated for claim_id in row.get("supports_claim_ids") or []
    ))
    unsupported_claim_ids = [claim_id for claim_id in required_claim_ids if claim_id not in supported_claim_ids]
    return {
        "bundle_id": f"EB-{risk_group}",
        "risk_id": "",
        "items": deduplicated,
        "evidence_items": deduplicated,
        "pre_dedup_item_count": len(items),
        "post_dedup_item_count": len(deduplicated),
        "required_fact_types": required,
        "covered_fact_types": covered,
        "missing_fact_types": missing,
        "required_claim_ids": required_claim_ids,
        "supported_claim_ids": supported_claim_ids,
        "unsupported_claim_ids": unsupported_claim_ids,
        "missing_element_types": absence_missing_elements,
        "derived_facts": derived_facts,
        "entailment_status": "PASSED" if not missing and not unsupported_claim_ids and deduplicated else "FAILED",
    }


def _payment_calculation_evidence_ready(
    contract_text: str,
    payment: Dict[str, Any],
    bundle: Dict[str, Any],
) -> tuple[bool, List[str]]:
    """Require current-document source evidence before emitting a formula risk."""

    reasons: List[str] = []
    current_document_hash = hashlib.sha256(_compact(contract_text).encode("utf-8")).hexdigest()
    total_candidates = list(payment.get("contract_total_candidates") or [])
    nodes = list(payment.get("nodes") or [])
    if payment.get("status") != "INCONSISTENT":
        reasons.append("arithmetic result is not inconsistent")
    if payment.get("contract_total") is None or not total_candidates:
        reasons.append("contract total is absent")
    if len(nodes) < 2:
        reasons.append("fewer than two payment nodes were extracted")
    global_total_candidate = payment.get("global_total_candidate") or (total_candidates[0] if total_candidates else None)
    component_total_candidates = list(payment.get("component_total_candidates") or [])
    source_facts = [
        *([global_total_candidate] if global_total_candidate else []),
        *component_total_candidates,
        *nodes,
    ]
    if any(str(row.get("source_document") or "") != current_document_hash for row in source_facts):
        reasons.append("calculation inputs do not belong to the current document")
    if any(
        not str(row.get("raw_text") or "").strip()
        or row.get("start_offset") is None
        or row.get("end_offset") is None
        for row in source_facts
    ):
        reasons.append("one or more calculation inputs lack source spans")
    if bundle.get("entailment_status") != "PASSED" or bundle.get("missing_fact_types") or bundle.get("unsupported_claim_ids"):
        reasons.append("the calculation evidence bundle is not fully entailed")

    bundle_items = list(bundle.get("items") or [])
    input_items = [row for row in bundle_items if row.get("evidence_role") == "CALCULATION_INPUT"]
    expected_fact_types = {
        "contract_total",
        *{f"payment_base_{index}" for index in range(1, len(component_total_candidates) + 1)},
        *{f"payment_node_{index}" for index in range(1, len(nodes) + 1)},
    }
    bound_fact_types = {
        str(fact_type)
        for row in input_items
        for fact_type in (row.get("fact_types") or [row.get("fact_type")])
        if fact_type
    }
    if not expected_fact_types <= bound_fact_types:
        reasons.append("not every arithmetic input is bound to a contract clause")
    if any(
        not row.get("clause_id")
        or str(row.get("source_type") or "").upper() in {"", "CALCULATION", "SEARCH_AUDIT"}
        or not str(row.get("quoted_text") or "").strip()
        for row in input_items
    ):
        reasons.append("one or more arithmetic inputs are not formal contract evidence")

    calculation = next((row for row in bundle_items if row.get("evidence_role") == "CALCULATION_RESULT"), None)
    bound_input_ids = {str(row.get("evidence_id") or "") for row in input_items if row.get("evidence_id")}
    derived_ids = set(str(value) for value in (calculation or {}).get("derived_from_evidence_ids") or [] if value)
    if not calculation or not bound_input_ids or not bound_input_ids <= derived_ids:
        reasons.append("calculation result is not derived from every bound input")
    return not reasons, reasons


def _bind_structured_risk_evidence_lineage(
    item: ReviewItemResult,
    bundle: Dict[str, Any],
) -> ReviewItemResult:
    """Bind a deterministic risk to the exact facts that triggered it."""
    element_id = f"{item.risk_group}.adverse_arrangement"
    bundle_items = list(bundle.get("items") or [])
    positive = [row for row in bundle_items if row.get("evidence_role") != "ABSENCE_EVIDENCE"]
    absence = [row for row in bundle_items if row.get("evidence_role") == "ABSENCE_EVIDENCE"]
    source_clause_ids = list(dict.fromkeys(str(row.get("clause_id") or "") for row in positive if row.get("clause_id")))
    reasons: List[str] = []
    if bundle.get("entailment_status") != "PASSED":
        reasons.append("required fact claims are not fully supported")
    if item.risk_group == "personal_information_processing_gap" and (not positive or not absence):
        reasons.append("personal-data risk requires positive trigger evidence plus an absence-search result")
    if item.risk_group == "generic_demand_reduction_exit_cost" and len(source_clause_ids) != 1:
        reasons.append("demand-reduction mechanism must resolve to one coherent source clause")
    if item.risk_group == "generic_cumulative_liability_overlap":
        party_pairs = {
            (str(row.get("liable_party") or ""), str(row.get("beneficiary_party") or ""))
            for row in positive
        }
        if len(source_clause_ids) < 3:
            reasons.append("cumulative-liability risk requires multiple independent liability clauses")
        if len(party_pairs) != 1 or any(not liable or not beneficiary or liable == beneficiary for liable, beneficiary in party_pairs):
            reasons.append("cumulative-liability evidence must keep one consistent liable/beneficiary party pair")

    status = "PASSED" if not reasons else "EVIDENCE_INSUFFICIENT"
    evidence_rows: List[Dict[str, Any]] = []
    if status == "PASSED":
        for row in bundle_items:
            quote = str(row.get("quoted_text") or "")
            location = str(row.get("clause_number") or "")
            evidence_rows.append({
                "evidence_id": str(row.get("evidence_id") or ""),
                "clause_id": str(row.get("clause_id") or ""),
                "node_id": str(row.get("clause_node_id") or ""),
                "location": location,
                "heading_path": list(row.get("heading_path") or []),
                "source_full_path": list(row.get("heading_path") or []) + ([location] if location else []),
                "start_offset": int(row.get("start_offset") if row.get("start_offset") is not None else -1),
                "end_offset": int(row.get("end_offset") if row.get("end_offset") is not None else -1),
                "source_text_hash": str(row.get("quoted_text_hash") or _stable_hash(_compact(quote))),
                "source_identity": dict(row.get("source_identity") or {}),
                "text": quote,
                "quote": quote,
                "original_excerpt": quote,
                "source_type": str(row.get("source_type") or ""),
                "derived_from_evidence_ids": list(row.get("derived_from_evidence_ids") or []),
                "fact_type": str(row.get("fact_type") or ""),
                "fact_types": list(row.get("fact_types") or [row.get("fact_type")]),
                "matched_terms": list(row.get("fact_types") or [row.get("fact_type")]),
                "evidence_role": str(row.get("evidence_role") or "TRIGGER_FACT"),
                "support_type": "DIRECT",
                "supporting_element_ids": [element_id],
                "entailment_status": EVIDENCE_SUPPORTS,
                "semantic_score": float(row.get("entailment_score") or 1.0),
                "evidence_semantics": "ABSENCE_SEARCH" if row.get("evidence_role") == "ABSENCE_EVIDENCE" else "ACTUAL_RISK_CLAUSE",
                "affirmative_risk_evidence": row.get("evidence_role") != "ABSENCE_EVIDENCE",
                "selection_reason": "Selected from trigger-fact lineage; renderer-time keyword fallback is disabled.",
                "search_scope": str(row.get("search_scope") or row.get("searched_scope") or ""),
                "missing_elements": list(row.get("missing_elements") or []),
                "liable_party": str(row.get("liable_party") or ""),
                "beneficiary_party": str(row.get("beneficiary_party") or ""),
                "trigger": str(row.get("trigger") or ""),
                "breach_type": str(row.get("breach_type") or ""),
                "remedy_type": str(row.get("remedy_type") or ""),
                "amount_formula": str(row.get("amount_formula") or ""),
            })
        item.evidence_clauses = evidence_rows
        item.evidence_location = "；".join(dict.fromkeys(str(row.get("location") or "") for row in evidence_rows if row.get("location")))
        evidence_ids = [str(row.get("evidence_id") or "") for row in evidence_rows if row.get("evidence_id")]
        for element in item.coverage_elements or []:
            element["evidence_ids"] = evidence_ids
            element["supporting_evidence_ids"] = evidence_ids
            element["source_clause_ids"] = source_clause_ids
    else:
        # Keep the signal observable for manual review but never attach a
        # topic-similar clause as a substitute for missing source evidence.
        item.evidence_clauses = []
        item.evidence_location = ""
        item.needs_manual_review = True
        item.system_confidence = {"level": "low", "reason": "; ".join(reasons)}
        item.applicability = {
            "status": "CONDITIONALLY_APPLICABLE",
            "applicable": True,
            "reason": "风险信号已触发，但正式证据不足，需人工核对。",
            "depends_on": ["supporting evidence"],
        }

    item.decision_trace["evidence_consistency_gate"] = {
        "status": status,
        "reasons": reasons,
        "wrong_evidence_fallback_allowed": False,
        "required_fact_types": list(bundle.get("required_fact_types") or []),
        "covered_fact_types": list(bundle.get("covered_fact_types") or []),
        "source_clause_ids": source_clause_ids,
        "liability_cluster": dict(bundle.get("liability_cluster") or {}),
    }
    item.decision_trace["evidence_lineage"] = {
        "risk_id": item.item_id,
        "rule_id": item.item_id,
        "trigger_fact_ids": [str(row.get("claim_id") or "") for row in positive],
        "supporting_fact_ids": [str(row.get("claim_id") or "") for row in bundle_items],
        "source_clause_ids": source_clause_ids,
        "source_locations": list(dict.fromkeys(str(row.get("clause_number") or "") for row in positive)),
        "positive_evidence_ids": [str(row.get("evidence_id") or "") for row in positive],
        "absence_evidence_ids": [str(row.get("evidence_id") or "") for row in absence],
        "calculation_evidence_ids": [
            str(row.get("evidence_id") or "") for row in bundle_items
            if row.get("evidence_role") == "CALCULATION_RESULT"
        ],
        "confidence": "high" if status == "PASSED" else "low",
    }
    return item


