def _clean_evidence_text(text: str) -> str:
    return re.sub(r"\s+", " ", text or "").strip()


def is_semantically_filled_field(text: str, field_label: str) -> bool:
    """Return true only when a template field has substantive content."""
    lines = [line.strip() for line in str(text or "").splitlines()]
    placeholders = {
        "", "/", "／", "无", "待填写", "待补充", "不适用", "n/a", "na",
        "[]", "【】", "()", "（）", "□", "未选择",
    }

    def substantive(value: str) -> bool:
        cleaned = value.strip().strip("：:").strip()
        if cleaned.lower() in placeholders:
            return False
        if re.fullmatch(r"[_＿.。·\-—\s（）()【】\[\]/／]*", cleaned):
            return False
        return bool(re.search(r"[\u4e00-\u9fffA-Za-z0-9]", cleaned))

    for index, line in enumerate(lines):
        if field_label not in line:
            continue
        inline_value = re.split(r"[：:]", line, maxsplit=1)[1] if re.search(r"[：:]", line) else ""
        if substantive(inline_value):
            return True
        for following in lines[index + 1:]:
            if not following:
                continue
            if re.match(r"^(?:第[一二三四五六七八九十百]+条|\d+[．.、])", following):
                break
            if following.endswith(("：", ":")):
                break
            return substantive(following)
        return False
    return False


def extract_semantic_field_value(text: str, field_label: str) -> Dict[str, Any]:
    """Extract a filled template field together with its clause-local span."""
    source = str(text or "")
    lines = source.splitlines(keepends=True)
    offset = 0
    for index, raw_line in enumerate(lines):
        line = raw_line.rstrip("\r\n")
        label_match = re.search(rf"{re.escape(field_label)}\s*[：:]", line)
        if not label_match:
            offset += len(raw_line)
            continue
        colon = re.search(r"[：:]", line[label_match.start():])
        if colon:
            colon_end = label_match.start() + colon.end()
        else:
            colon_end = len(line)
        inline = line[colon_end:].strip()
        values = [inline] if inline else []
        value_start = offset + colon_end
        value_end = offset + len(line)
        for following in lines[index + 1:]:
            candidate = following.rstrip("\r\n").strip()
            if not candidate:
                value_end += len(following)
                continue
            if re.search(r"[：:]\s*$", candidate) or re.match(r"^(?:第[一二三四五六七八九十百]+条|\d+[．.、])", candidate):
                break
            values.append(candidate)
            value_end += len(following)
            if field_label == "保密期限":
                break
        value = " ".join(part for part in values if part).strip()
        filled = is_semantically_filled_field(f"{field_label}：\n{value}", field_label)
        return {
            "field_name": field_label,
            "field_value": value if filled else "",
            "is_filled": filled,
            "source_span": {"start_offset": value_start, "end_offset": value_end},
        }
    return {
        "field_name": field_label,
        "field_value": "",
        "is_filled": False,
        "source_span": {"start_offset": -1, "end_offset": -1},
    }


def _excerpt(text: str, limit: int = 180) -> str:
    cleaned = _clean_evidence_text(text)
    if len(cleaned) <= limit:
        return cleaned
    return f"{cleaned[:limit].rstrip()}..."


def _first_sentence(text: str) -> str:
    cleaned = _clean_evidence_text(text)
    if not cleaned:
        return ""
    parts = re.split(r"(?<=[。！？；;])", cleaned, maxsplit=1)
    return parts[0].strip() or cleaned[:120]


def _first_citation(item: ReviewItemResult) -> Dict[str, str]:
    evidences = item.evidence_clauses or []
    if not evidences:
        if item.coverage_status == INSUFFICIENT_CONTEXT:
            status = "INSUFFICIENT_CONTEXT"
            description = "现有合同材料不足以确认该事项是否适用，建议结合相关交易背景或补充材料核对。"
        elif item.coverage_status == COVERAGE_NOT_APPLICABLE:
            status = "NOT_APPLICABLE"
            description = "当前合同未触发该审查事项的适用条件。"
        elif (item.decision_trace or {}).get("review_polarity") == "NEGATIVE_CLAUSE_CHECK" and item.coverage_status == "通过":
            status = "NO_ADVERSE_CLAUSE_FOUND"
            description = "未发现该类不利约定。"
        elif item.coverage_status == "通过":
            status = "NO_CLAUSE_REQUIRED"
            description = "本项不需要额外定位缺失条款。"
        else:
            status = "NO_SUPPORTING_CLAUSE"
            description = "合同正文及附件中未找到对应约定。"
        return {
            "evidence_status": status,
            "clause_number": "无对应条款",
            "original_excerpt": "无正式条款证据",
            "position_description": description,
        }

    evidence = evidences[0]
    location = str(evidence.get("location") or item.evidence_location or "未标明条款编号").strip()
    text = str(evidence.get("text") or "").strip()
    sentence = str(evidence.get("quote") or "").strip() or _first_sentence(text)
    position = f"{location}第1句" if sentence else location
    document_type = evidence.get("source_document_type") or evidence.get("document_type") or "MAIN_CONTRACT"
    source_label = {
        "MAIN_CONTRACT": "合同正文",
        "SUPPLEMENTARY_TERMS": "补充条款",
        "APPENDIX": "附件",
        "AMENDMENT": "补充协议/修订文件",
        "SIDE_LETTER": "往来函件",
    }.get(document_type, "其他文件")
    return {
        "evidence_status": "FOUND_ADVERSE_CLAUSE" if item.coverage_status == "风险条款" else "FOUND_SUPPORTING_CLAUSE",
        "document_type": document_type,
        "source_document_type": document_type,
        "source_label": source_label,
        "clause_number": location,
        "original_excerpt": f"“{_excerpt(sentence or text)}”",
        "position_description": f"{source_label}，{position}",
    }


def _evidence_position_display(item: ReviewItemResult) -> str:
    if item.evidence_location:
        return item.evidence_location
    citation = item.citation or _first_citation(item)
    return citation.get("position_description") or "合同正文及附件中未找到对应约定。"


def _legal_rule_text(item: ReviewItemResult) -> str:
    basis = item.legal_basis_index or "相关法律规则"
    for article, rule in _LEGAL_RULE_HINTS.items():
        if article in basis:
            return f"依据{basis}，{rule}"
    return f"依据{basis}，合同应围绕“{item.title}”明确权利义务、适用条件、履行标准和处理后果，避免履行及举证不确定。"


def _judgment_text(item: ReviewItemResult, citation: Dict[str, str]) -> str:
    if item.coverage_status == COVERAGE_NOT_APPLICABLE:
        return f"该审查点当前不适用于本合同场景，原因：{item.applicability.get('reason') or item.reasoning_summary}"
    if item.coverage_status == "缺失":
        return (
            f"合同未设置能够直接覆盖“{item.title}”的正式条款。"
            f"该缺口对应的问题类型为“{item.issue_type}”，会造成：{item.legal_consequence_if_missing}"
        )
    if item.coverage_status == "部分覆盖":
        return (
            f"合同已在{citation['clause_number']}出现相关安排，但该安排只覆盖部分要素。"
            f"结合问题类型“{item.issue_type}”看，现有条款仍未完整满足该审查点要求：{item.reasoning_summary}"
        )
    if item.coverage_status == "风险条款":
        return (
            f"合同在{citation['clause_number']}出现与该审查点直接相关的约定，"
            f"但该约定本身构成需修改的风险表述：{item.risk_point_description}"
        )
    if item.coverage_status == "通过":
        if item.related_risks:
            return (
                f"合同在{citation['clause_number']}已覆盖该审查点的核心要求；"
                f"但同一风险组存在关联风险 {', '.join(item.related_risks)}，需结合相关风险发现处理。"
            )
        return f"合同在{citation['clause_number']}已覆盖该审查点的核心要求，当前无明显残余风险。"
    return f"当前覆盖状态为“{item.coverage_status}”，系统判断为：{item.reasoning_summary}"


def _conclusion_text(item: ReviewItemResult) -> str:
    if item.coverage_status == COVERAGE_NOT_APPLICABLE:
        return "本项不适用于当前合同，无需修改。"
    if item.coverage_status == "通过" and item.risk_level == "低":
        if item.related_risks:
            return "本项条款机制已覆盖，但同一事实或条款存在关联风险发现，详见核心风险摘要。"
        return "本项已覆盖，无需修改。"
    return f"本项覆盖状态为“{item.coverage_status}”，处理优先级由关联风险发现和行动优先级统一决定。"


def _user_facing_reasoning(text: str) -> str:
    cleaned = text or ""
    cleaned = re.sub(r"（?用户风险偏好已纳入后续优先级排序。?）?", "", cleaned)
    cleaned = re.sub(r"[a-z_]+\.[a-z_\.]+=\{[^。；]*\}[。；]?", "", cleaned)
    cleaned = re.sub(r"[a-z_]+\.[a-z_\.]+=[^。；，]*[。；]?", "", cleaned)
    cleaned = re.sub(r"金额测算\s*测算\s*\{[^。]*\}。?", "", cleaned)
    replacements = {
        "统一事实图谱提取": "根据合同原文可确认",
        "统一事实图谱识别": "根据合同原文可识别",
        "统一事实图谱显示": "根据合同原文显示",
        "统一事实图谱": "合同事实",
        "Fact Graph": "合同事实",
        "Scenario Engine": "金额测算",
        "Final Quality Gate": "最终校验",
        "Cross Review Consistency Verifier": "一致性校验",
        "rule_fallback": "自动审查",
        "LLM": "语义复核",
        "建议人工复核": "建议重点核对",
        "需要人工复核": "需要重点核对",
    }
    for old, new in replacements.items():
        cleaned = cleaned.replace(old, new)
    return _dedupe_narrative_sentences(re.sub(r"\s+", " ", cleaned).strip())


def _applicability_user_reason(item: ReviewItemResult) -> str:
    if item.coverage_status == INSUFFICIENT_CONTEXT or str((item.applicability or {}).get("status") or "").upper() == INSUFFICIENT_CONTEXT:
        return "现有合同材料不足以确认该事项是否适用，建议结合相关交易背景或补充材料核对。"
    return str(
        item.applicability.get("user_reason")
        or item.applicability.get("reason")
        or "当前合同未触发该审查事项的适用条件。"
    )


def _dedupe_narrative_sentences(text: str) -> str:
    parts = [part.strip() for part in re.split(r"(?<=[。；;])", text or "") if part.strip()]
    if not parts:
        return text or ""
    seen: set[str] = set()
    deduped: List[str] = []
    for part in parts:
        key = re.sub(r"\s+", "", part)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(part)
    return "".join(deduped)


MISSING_NARRATIVE_FORBIDDEN = ("已出现", "已覆盖", "已有明确约定", "已存在相关安排", "尚未完整覆盖", "部分相关安排")
PARTIAL_TOTAL_MISSING_PHRASES = ("完全未约定", "未约定该机制", "未约定质量异议处理机制", "未明确约定相关安排")


def _coverage_element_sets(item: ReviewItemResult) -> tuple[List[str], List[str]]:
    covered: List[str] = []
    missing: List[str] = []
    for element in item.coverage_elements or []:
        proposition = _display_element_label(
            element.get("proposition") or element.get("element_id") or ""
        ).strip("。")
        if (
            not proposition
            or element.get("internal_meta")
            or element.get("user_visible") is False
            or _is_internal_uncertainty_text(proposition)
        ):
            continue
        if element.get("status") in {"COVERED", "PARTIALLY_COVERED"}:
            covered.append(proposition)
        elif element.get("status") in {"MISSING", "UNCERTAIN"}:
            missing.append(proposition)
    return covered, missing


def _coverage_element_groups(item: ReviewItemResult) -> tuple[List[str], List[str], List[str], List[str]]:
    covered: List[str] = []
    partial: List[str] = []
    missing: List[str] = []
    adverse: List[str] = []
    for element in item.coverage_elements or []:
        proposition = str(element.get("proposition") or element.get("element_id") or "").strip("。")
        if (
            not proposition
            or element.get("internal_meta")
            or element.get("user_visible") is False
            or _is_internal_uncertainty_text(proposition)
        ):
            continue
        status = element.get("status")
        if status == "COVERED":
            covered.append(proposition)
        elif status in {"PARTIALLY_COVERED", "REFERENCED_BUT_NOT_PROVIDED"}:
            partial.append(proposition)
        elif status in {"MISSING", "UNCERTAIN"} and element.get("risk_relevant") is not False:
            missing.append(proposition)
        elif status in {"ADVERSE", "CONFLICTING"} and element.get("risk_relevant") is not False:
            adverse.append(proposition)
    return covered, partial, missing, adverse


def _element_narrative_label(proposition: str) -> str:
    label = proposition.strip("。")
    for prefix in (
        "合同已经明确约定", "合同已明确约定", "合同明确约定", "合同已经约定", "合同已约定",
        "已明确约定", "已约定", "合同已经明确", "合同已明确", "合同明确",
        "合同已经载明", "合同已载明", "合同载明", "合同存在",
    ):
        if label.startswith(prefix):
            label = label[len(prefix):].strip("“”")
            break
    generic = re.fullmatch(r"可验证的“([^”]+)”(?:对应的核心安排|实质条款内容)", label)
    if generic:
        return f"“{generic.group(1)}”事项"
    return label


def _missing_element_narrative_label(proposition: str) -> str:
    label = _element_narrative_label(proposition)
    # A negative proposition such as “复测机制未明确” is already the complete
    # user-facing gap.  Stripping the generic “明确” suffix here used to leave
    # the malformed fragment “复测机制未”.
    if not re.search(r"(?:未|尚未|没有|并未)明确(?:约定)?$", label):
        label = re.sub(r"(?:已经|已)?(?:充分|完整)?明确(?:约定)?$", "", label).strip("，；。 ")
    return label or _element_narrative_label(proposition)


def _partial_element_narrative_label(proposition: str) -> str:
    """Render a partial element without reusing a completed-coverage claim."""
    label = _element_narrative_label(proposition).strip("。；;，, ")
    # Some propositions already are complete user-facing PARTIAL judgments
    # (for example, "已有……，但……仍需完善"). Preserve their own gap
    # semantics; synthesize prose only for a neutral element name/requirement.
    if re.search(
        r"(?:部分|但|仍需|尚需|还需|仍未|尚未|未完整|未固定|"
        r"不完整|不充分|仍不足|尚不足|有待完善|需进一步)",
        label,
    ):
        return label
    completed = re.fullmatch(
        r"(.+?)(?:已经|已)(?:完整|完全|全面|充分)(列明|披露|说明|约定|明确|提供|覆盖)",
        label,
    )
    if completed:
        subject, action = completed.groups()
        return f"{subject}已有部分约定，但仍未完整{action}"
    stated = re.fullmatch(r"(.+?)(?:已经|已)(列明|披露|说明|约定|明确|提供|覆盖)", label)
    if stated:
        subject, action = stated.groups()
        return f"{subject}已有相关安排，但仍未充分{action}"
    verifiable = re.fullmatch(r"(.+?)(?:有|已有|具有)?可(?:供|独立)?核验(?:的)?(?:依据|材料)?", label)
    if verifiable:
        return f"{verifiable.group(1)}已有相关说明，但可核验依据仍不完整"
    if re.search(r"(?:对象|名称|名单|清单|项目)$", label):
        return f"{label}已有部分约定，但仍未完整列明"
    if re.search(r"(?:披露|许可|使用)安排$", label):
        return f"{label}已有部分约定，但仍未完整披露"
    return f"{label}已有部分约定，但完整性仍不足"


def _prioritized_missing_elements(item: ReviewItemResult) -> tuple[List[str], str]:
    """Resolve concrete gaps without letting an unknown fallback overwrite known facts."""
    trace = item.decision_trace or {}
    structured_from_elements = [
        _display_element_label(element.get("proposition") or element.get("element_id")).strip("。")
        for element in item.coverage_elements or []
        if element.get("status") in {"MISSING", "UNCERTAIN"}
        and element.get("risk_relevant") is not False
    ]
    candidates = (
        ("explicit_missing_elements", trace.get("explicit_missing_elements") or []),
        ("structured_missing_elements", trace.get("structured_missing_elements") or structured_from_elements),
        ("evidence_inferred_missing_elements", trace.get("evidence_inferred_missing_elements") or []),
    )
    for source, values in candidates:
        normalized = list(dict.fromkeys(
            str(value or "").strip("。；; ：:")
            for value in values
            if str(value or "").strip("。；; ：:")
            and not _is_internal_uncertainty_text(value)
        ))
        if normalized:
            return normalized, source
    return [], "fallback_unknown"


def _specific_gap_consequence(item: ReviewItemResult, gap_text: str) -> str:
    text = " ".join([item.title, item.node_id, item.risk_group, item.risk_point_description, gap_text])
    if item.item_id == "TC-06-04" or item.risk_group == "registration_feasibility_blocker":
        item.decision_trace.setdefault("field_provenance", {})["legal_consequence_source"] = (
            "rule_family:registration_feasibility_blocker"
        )
        return (
            "未取得质权人同意或未完成质押解除，可能导致专利权转让登记无法办理或被要求补正，"
            "使受让方无法按计划取得专利权，并引发付款、交割、退款及交易失败损失。"
        )
    if item.item_id == "TC-05-01":
        return (
            "各方资金、技术、人员、设备资源投入和具体研发模块无法量化时，项目延期或研发失败后难以判断"
            "由哪一方补足资源、承担赶工成本或对未完成模块负责。"
        )
    if item.item_id == "TC-05-02":
        return (
            "法定默认共有规则能够确定专利申请权的基本归属，但申请主体、费用、共同决策、放弃申请和转让程序不清时，"
            "仍可能造成申请延误、重复申报或程序争议。"
        )
    if item.item_id == "TC-04-03":
        return (
            "如未专项明确专利申请权及乙方协助义务，实际申请时可能出现申请主体、文件签署、"
            "发明人确认及权利登记配合争议，影响委托方顺利取得相关专利权。"
        )
    if item.item_id == "TC-04-04":
        return (
            "未约定无过错技术风险导致研发失败时的责任分配，可能导致双方对已发生研发费用、"
            "未完成阶段付款、阶段成果归属及项目终止后的资料交接产生争议。"
        )
    if item.item_id == "TC-05-04":
        subtype = str(((item.decision_trace or {}).get("subtype_rendering") or {}).get("primary_subtype") or "")
        if subtype == "COOPERATIVE_DEVELOPMENT" or item.risk_group == "cooperation_breach_and_exit":
            return (
                "一方迟延、停止投入或提前退出后，如未明确源代码、研发资料和阶段成果交接、未完成成果归属、"
                "费用结算及继续开发权，其余合作方可能无法接管项目，导致既有投入沉没或研发停摆。"
            )
        return (
            "提前解除后如未明确源代码、开发环境和研发资料的交接义务，以及未完成成果的使用和继续开发权限，"
            "委托方可能无法顺利接管项目或委托第三方继续开发，导致既有投入沉没或项目中断。"
        )
    if item.item_id == "TC-05-03" or item.risk_group == "technical_secret_result_rights":
        item.decision_trace["legal_consequence_mapping"] = {
            "semantic_domain": "SECRET_COPY_RETENTION",
            "source": "rule_id+risk_group+missing_atomic_element+contract_subtype",
            "missing_element_ids": [
                str(row.get("element_id") or "") for row in item.coverage_elements or []
                if row.get("status") in {"PARTIALLY_COVERED", "MISSING", "UNCERTAIN"}
            ],
        }
        if item.fallback_reason == "合作开发技术秘密成果使用处分原子要素规则":
            return (
                "合作结束后，如未明确各合作方对源代码、技术秘密及其他未公开技术资料的使用、留存、许可、"
                "转让及资料处置边界，可能增加未经授权继续使用、向第三方披露、后续商业利用、收益分配以及"
                "资料是否已返还或删除的争议。"
            )
        return (
            "项目结束后如未明确开发方可留存的源代码、技术秘密及其他未公开技术资料副本的范围、期限、"
            "安全措施和删除确认机制，可能增加未经授权继续使用、向第三方披露、后续商业利用及资料是否已删除的举证争议。"
        )
    if item.item_id == "TC-11-04" or item.risk_group == "confidentiality_breach_liability":
        propagation = (item.decision_trace or {}).get("general_breach_semantic_propagation") or {}
        item.decision_trace["legal_consequence_mapping"] = {
            "semantic_domain": "CONFIDENTIALITY_INCIDENT_REMEDIES",
            "source": "atomic_missing_remedies",
        }
        if propagation.get("classification") != "GENERAL_BREACH_CATCH_ALL":
            return (
                "合同虽有保密义务和一般违约条款，但尚无足够证据证明一般违约责任覆盖全部合同义务；"
                "泄密损失赔偿及停止披露、停止使用和补救机制不完整；资料返还销毁由TC-11-03独立审查。"
            )
        return (
            "合同已覆盖违反保密义务造成的损失赔偿，但泄密后的停止披露、停止使用和防止继续扩散机制不完整，"
            "可能导致损害持续扩大；资料返还销毁由TC-11-03独立审查。"
        )
    if item.item_id == "TC-12-02":
        direction_check = (item.decision_trace or {}).get("recommendation_direction_check") or {}
        if direction_check.get("review_role") == "SERVICE_PROVIDER":
            return (
                "从服务提供方立场，第三方主张的通知、抗辩控制和和解决策程序不清，"
                "可能导致服务接受方自行处置争议后再向服务提供方追偿；该程序缺口不等于应扩大服务提供方的退款或赔偿责任。"
            )
        element_tiers = (item.decision_trace or {}).get("third_party_claim_element_tiers") or {}
        if element_tiers.get("advanced_only_gap"):
            return (
                "合同已具备基本保护机制，剩余事项主要属于争议处理程序的进一步完善；"
                "补充抗辩控制、律师选择、和解决策、费用细化及替代修复安排，可提高复杂索赔中的决策和执行效率。"
            )
        transaction_object = str(((item.decision_trace or {}).get("subtype_rendering") or {}).get("transaction_object") or "相关合同技术")
        continuity = (
            "影响被许可方持续实施许可专利"
            if transaction_object == "许可专利"
            else f"影响持续使用或实施{transaction_object}"
        )
        return (
            f"发生第三方权利主张后，{gap_text.strip('。；; ')}尚未形成完整安排，"
            f"可能延误应对并扩大侵权损失或{continuity}。"
        )
    if item.item_id == "TC-09-03" or item.risk_group == "service_new_result_ownership":
        return (
            item.legal_consequence_if_missing
            or "服务中新成果的所有权、使用权、修改权、第三方授权及商业化边界未最终确定时，双方可能发生后续权属和使用争议。"
        )
    if item.item_id == "TC-12-04":
        if item.fallback_reason == "合作开发侵权责任与一般救济衔接规则":
            return (
                "侵权专项责任与合同中已经存在的一般损失赔偿，以及依法或其他合同条款可能适用的其他救济之间，"
                "如缺少适用顺序、累计关系和避免重复赔偿机制，可能产生救济路径冲突或同一损失重复计算争议。"
            )
        return (
            "侵权专项责任与一般损失赔偿、违约金、退款和继续履行等救济的适用顺序及累计关系不清时，"
            "可能引发救济路径冲突或同一损失重复计算争议。"
        )
    if item.item_id == "TC-11-03":
        return (
            "未约定合同终止或保密目的完成后的资料返还、复制件销毁和备份删除义务时，"
            "保密信息可能在项目结束后继续留存，增加后续泄露和举证争议。"
        )
    if item.item_id == "TC-13-03":
        return (
            "测试结果发生争议时如无第三方复测机构、启动程序、结果效力和费用承担安排，"
            "双方可能难以形成共同认可的验收结论，并影响尾款支付和项目交付。"
        )
    if item.item_id == "TC-13-04" or item.risk_group == "technology_import_export_control":
        item.decision_trace.setdefault("field_provenance", {})["legal_consequence_source"] = (
            "rule_family:technology_import_export_control"
        )
        return (
            "具体审批、登记、备案、许可和出口管制责任不清时，可能导致技术或技术资料跨境交付、"
            "许可履行及付款结算受阻，并引发履行暂停、费用承担、解除和结算争议。"
        )
    if item.item_id == "TC-10-03" or item.risk_group == "improvement_notification":
        subtype_rendering = (item.decision_trace or {}).get("subtype_rendering") or {}
        transaction_object = str(subtype_rendering.get("transaction_object") or "")
        has_follow_on_entitlement = bool(subtype_rendering.get("has_follow_on_entitlement"))
        if transaction_object == "许可专利":
            return (
                "改进成果形成后未及时通知时，被许可方可能无法判断成果是否依赖许可专利、是否影响既有实施权，"
                "以及是否需要协商交叉许可或优先许可；通知本身不当然改变成果归属或创设共有关系。"
            )
        if transaction_object == "受让专利权":
            return (
                "如双方另行约定对基于受让专利形成的后续改进享有分享、许可、返授或优先权，"
                "未及时通知可能影响该等权利的识别和行使；通知本身不当然改变成果归属或创设共有关系。"
            )
        if transaction_object == "委托开发成果":
            return (
                "如合同另行赋予一方对后续改进成果的分享、许可、返授或优先权，未及时通知可能影响该等权利的识别和行使；"
                + (
                    "现有证据显示合同存在此类持续权利，应同步明确通知范围和期限。"
                    if has_follow_on_entitlement
                    else "当前未识别到此类持续权利，通知义务缺失本身不创设共有、收益分配或其他新的权利关系。"
                )
            )
        if transaction_object == "合作开发成果" and has_follow_on_entitlement:
            return (
                "现有条款已配置合作开发成果的共有、分享、许可或收益权益；缺少改进成果通知可能影响相关共同权利的识别和行使。"
            )
        return (
            "如合同另行配置后续改进成果的分享、许可或优先权，未及时通知可能影响相应权利行使；"
            "通知义务本身不当然创设共有或收益分配关系。"
        )
    if item.risk_group == "acceptance_test_attachment":
        return (
            "缺少固定测试数据集、设备环境和操作步骤时，已约定的量化指标和测试报告可能难以稳定复现，"
            "争议发生后也难以核对双方是否采用相同测试条件。"
        )
    if item.risk_group == "technology_ip_rights_provenance":
        item.decision_trace.setdefault("field_provenance", {})["legal_consequence_source"] = "rule_family:technology_ip_rights_provenance"
        proof_subject = str(((item.decision_trace or {}).get("ip_proof_model") or {}).get("subject") or "")
        transaction_type = str(
            (item.decision_trace or {}).get("ip_proof_transaction_type")
            or ((item.decision_trace or {}).get("ip_proof_model") or {}).get("transaction_type")
            or ""
        )
        if proof_subject == "技术秘密转让":
            return (
                "技术来源、合法持有和处分权限、共同持有人、历史披露及第三方保密义务材料不完整时，"
                "受让方可能无法核验交易范围和秘密性基础，并面临权属争议、第三方索赔、既有使用冲突或技术秘密丧失风险。"
            )
        if transaction_type == "TECHNOLOGY_LICENSE":
            return (
                "许可标的、授权链、既有许可或权利负担材料不完整时，被许可方可能无法充分核验许可方的许可权限，"
                "并面临上游授权瑕疵、独占或排他许可冲突及第三方权利主张风险。"
            )
        return (
            "权属、登记信息、权利负担或交易办理文件不足时，受让方可能无法充分核验让与方处分权，"
            "并增加转让登记补正、登记失败或交割后发现质押、既有许可及权属争议的风险。"
        )
    if any(term in text for term in ("知识产权", "侵权", "专利", "商标", "著作权")):
        if item.item_id.startswith("TC-") or item.item_id.startswith("TECH-"):
            return "第三方提出权利主张时，停用、替换成本和向责任方追偿的依据可能不够直接。"
        return "第三方提出侵权主张时，停用、下架、替换成本和对出卖人的追偿依据可能不够直接。"
    if any(term in text for term in ("包装", "运输损坏", "装箱", "防护")):
        return "运输损坏发生后，包装是否合格、损失原因和责任归属容易发生争议。"
    if any(term in text for term in ("权利瑕疵", "第三方权利", "权利负担")):
        return "第三方主张权利时，披露、排除妨碍、替换和赔偿路径不够直接。"
    if any(term in text for term in ("迟延受领", "拒收", "未提货")):
        return "买受人迟延受领后的费用、保管和风险分配主要依赖法定规则，写入合同前需确认是否会扩大当前客户责任。"
    if any(term in text for term in ("可得利益", "预期利益")):
        return "可得利益赔偿仍受违约因果关系、可预见性和证据证明约束；限制性写法可能缩小守约方救济。"
    if any(term in text for term in ("交付", "验收", "签收")):
        return "交付或验收节点不清时，风险转移、质量异议和付款条件容易被不同理解。"
    if any(term in text for term in ("付款", "价款", "结算")):
        return f"{gap_text}不清时，付款期限、逾期责任和对账依据容易产生争议。"
    return f"{gap_text}不清时，责任边界不够明确。"


def _build_narrative_state(item: ReviewItemResult) -> Dict[str, Any]:
    covered, partial, missing, adverse = _coverage_element_groups(item)
    external_material_rows = [
        element for element in item.coverage_elements or []
        if str(element.get("status") or "").upper() == "REFERENCED_BUT_NOT_PROVIDED"
    ]
    satisfaction = (item.decision_trace or {}).get("common_review_satisfaction") or {}
    active_paths = [row for row in satisfaction.get("satisfaction_paths", []) if row.get("applicable", True)]
    if active_paths and item.coverage_status in {"缺失", "部分覆盖"}:
        selected_path = max(
            active_paths,
            key=lambda row: (
                sum(status == "COVERED" for status in (row.get("statuses") or {}).values()),
                sum(status == "PARTIALLY_COVERED" for status in (row.get("statuses") or {}).values()),
                -sum(status in {"MISSING", "UNCERTAIN"} for status in (row.get("statuses") or {}).values()),
            ),
        )
        required_ids = set(selected_path.get("required_elements") or [])
        missing = [
            str(element.get("proposition") or element.get("element_id") or "").strip("。")
            for element in item.coverage_elements or []
            if element.get("element_id") in required_ids and element.get("status") in {"MISSING", "UNCERTAIN"}
        ]
        partial = [
            str(element.get("proposition") or element.get("element_id") or "").strip("。")
            for element in item.coverage_elements or []
            if element.get("element_id") in required_ids and element.get("status") == "PARTIALLY_COVERED"
        ]
    prioritized_missing, missing_source = _prioritized_missing_elements(item)
    if item.coverage_status in {"缺失", "部分覆盖"} and prioritized_missing:
        missing = prioritized_missing
    item.decision_trace["missing_element_resolution"] = {
        "priority": [
            "explicit_missing_elements", "structured_missing_elements",
            "evidence_inferred_missing_elements", "fallback_unknown",
        ],
        "selected_source": missing_source,
        "selected_elements": list(missing),
    }
    if getattr(item, "risk_group", "") == "indemnity_and_liability_cap" and item.coverage_status in {"缺失", "部分覆盖"}:
        generic_missing = not missing or all(
            element == item.title or "可验证的" in element or "实质条款内容" in element
            for element in missing
        )
        if generic_missing:
            missing = [
                "侵权专项责任与一般损失赔偿之间的适用关系",
                "违约金与损害赔偿是否累计及抵扣的关系",
                "退款、赔偿和其他救济之间的抵扣关系",
                "同一损失避免重复赔偿的规则",
            ]
            item.decision_trace["narrative_required_elements_source"] = "rule_family:indemnity_and_liability_cap"
    covered = list(dict.fromkeys(covered))
    partial = [value for value in dict.fromkeys(partial) if value not in covered]
    missing = [value for value in dict.fromkeys(missing) if value not in covered and value not in partial]
    adverse = [
        value for value in dict.fromkeys(adverse)
        if value not in covered and value not in partial and value not in missing
    ]
    covered_text = "；".join(_element_narrative_label(value) for value in covered)
    partial_text = "；".join(_partial_element_narrative_label(value) for value in partial)
    missing_text = "；".join(_missing_element_narrative_label(value) for value in missing)
    adverse_text = "；".join(_element_narrative_label(value) for value in adverse)
    applicability = str((item.applicability or {}).get("status") or "APPLICABLE").upper()
    polarity = str((item.decision_trace or {}).get("review_polarity") or "POSITIVE_REQUIREMENT")
    if item.coverage_status == INSUFFICIENT_CONTEXT:
        covered, partial, missing, adverse = [], [], [], []
        judgment = _applicability_user_reason(item)
        issue = judgment
        consequence = judgment
        recommendation = ""
    elif applicability == "NOT_APPLICABLE" or item.coverage_status == COVERAGE_NOT_APPLICABLE:
        covered, partial, missing, adverse = [], [], [], []
        judgment = _applicability_user_reason(item)
        issue = ""
        consequence = ""
        recommendation = ""
    elif item.coverage_status == "通过":
        if (item.decision_trace or {}).get("review_nature") == "INTERNAL_CLASSIFICATION":
            judgment = f"系统已完成“{item.title}”的内部法律定性；该结果用于后续规则适用，不要求合同正文单列分类表述。"
            consequence = "不形成独立合同风险。"
        elif polarity == "NEGATIVE_CLAUSE_CHECK":
            judgment = f"未发现“{item.title}”对应的不利条款或安排。"
            consequence = "未发现该不利安排，因此不形成对应风险。"
        else:
            judgment = f"合同已明确约定{covered_text}。" if covered_text else f"合同已覆盖{item.title}要求。"
            consequence = "无明显残余风险。"
        issue = ""
        recommendation = "无需修改。"
    elif item.coverage_status == "缺失":
        if not missing_text:
            judgment = "本项尚需人工复核，当前不作为确定性合同缺失输出。"
            issue = ""
            consequence = ""
            recommendation = ""
        else:
            judgment = f"合同未明确：{missing_text}。"
            issue = f"缺失：{missing_text}。"
            consequence = _specific_gap_consequence(item, missing_text)
            recommendation = _recommendation_from_missing_elements(missing)
    elif item.coverage_status == "部分覆盖":
        statements = []
        if covered_text:
            statements.append(f"已覆盖：{covered_text}")
        if partial_text:
            statements.append(f"仅部分明确：{partial_text}")
        if missing_text:
            statements.append(f"尚未覆盖：{missing_text}")
        if adverse_text:
            statements.append(f"存在不利或冲突安排：{adverse_text}")
        judgment = "；".join(statements) + "。" if statements else f"“{item.title}”仅得到部分证据支持，仍需补足关键要素。"
        incomplete_text = "；".join(value for value in (partial_text, missing_text, adverse_text) if value)
        if not incomplete_text:
            incomplete_text = next(
                (
                    value for value in (
                        str(item.risk_point_description or "").strip("。"),
                        str(item.legal_consequence_if_missing or "").strip("。"),
                        str(item.reasoning_summary or "").strip("。"),
                    )
                    if value
                    and not any(phrase in value for phrase in NON_CONCRETE_GAP_PHRASES)
                    and not any(marker in value for marker in ("已覆盖", "完整覆盖", "全部覆盖"))
                ),
                f"“{item.title}”现有条款仍存在需要处理的不完整安排",
            )
        issue = (
            str(item.risk_point_description or "").strip()
            if adverse_text and item.risk_point_description
            else f"仍需补足：{incomplete_text}。"
        )
        consequence = (
            str(item.legal_consequence_if_missing or "").strip()
            if adverse_text and item.legal_consequence_if_missing
            else _specific_gap_consequence(item, incomplete_text)
        )
        recommendation = (
            str(item.suggested_clause_example or "").strip()
            if adverse_text and item.suggested_clause_example
            else _recommendation_from_missing_elements(partial + missing or [incomplete_text])
        )
        if external_material_rows:
            issue = str(item.risk_point_description or "").strip()
            consequence = (
                "所引用材料未纳入本次审查范围时，正文所述事项与该材料的一致性、签署状态及其作为合同组成部分的效力"
                "缺少可直接审查的材料基础，可能影响后续履行和举证。"
            )
            recommendation = str(item.suggested_clause_example or "").strip()
    else:
        judgment = item.risk_point_description or f"“{item.title}”存在需要处理的风险条款。"
        issue = item.risk_point_description
        consequence = item.legal_consequence_if_missing
        recommendation = item.suggested_clause_example
    if item.item_id == "TC-08-03" and item.coverage_status == "缺失":
        issue = (
            "合同未明确委托方向咨询方提供开展技术咨询所需资料、数据及相关信息的义务，"
            "资料提供范围、期限以及真实性、完整性责任不够明确。"
        )
        judgment = issue
        recommendation = (
            "建议明确委托方应提供的资料、数据或相关信息范围、提供期限及真实性、完整性要求，"
            "并约定因迟延提供或资料存在缺陷而影响咨询工作的责任承担。"
        )
    positive_markers = ("已明确约定", "已完整覆盖", "无需修改", "已充分约定")
    missing_scope = " ".join((judgment, issue))
    if item.coverage_status == "缺失" and any(marker in missing_scope for marker in positive_markers):
        cleaned_missing = missing_text or _missing_element_narrative_label(item.title)
        judgment = f"合同未明确：{cleaned_missing}。"
        issue = f"缺失：{cleaned_missing}。"
        item.decision_trace["narrative_status_consistency"] = {"status": "NORMALIZED", "from": "positive_phrase_in_missing"}
    elif item.coverage_status == "通过" and any(marker in judgment for marker in ("尚未覆盖", "缺失", "未明确")):
        judgment = f"合同已覆盖{item.title}要求。"
        item.decision_trace["narrative_status_consistency"] = {"status": "NORMALIZED", "from": "missing_phrase_in_pass"}
    else:
        item.decision_trace["narrative_status_consistency"] = {"status": "PASS"}
    return {
        "review_id": item.item_id,
        "applicability": applicability,
        "polarity": polarity,
        "coverage_status": item.coverage_status,
        "covered_elements": covered,
        "partial_elements": partial,
        "missing_elements": missing,
        "adverse_elements": adverse,
        "finding_exists": item.coverage_status in {"缺失", "部分覆盖", "风险条款"} and applicability in {"APPLICABLE", "CONDITIONALLY_APPLICABLE"},
        "judgment": judgment,
        "issue": issue,
        "consequence": consequence,
        "recommendation": recommendation,
        "result": judgment,
    }


def _partial_element_narrative(item: ReviewItemResult) -> str:
    state = item.narrative_state or _build_narrative_state(item)
    return str(state["judgment"])


def _apply_element_level_narratives(items: List[ReviewItemResult]) -> List[ReviewItemResult]:
    for item in items:
        internal_rows = []
        for element in item.coverage_elements or []:
            if (
                element.get("internal_meta")
                or _is_internal_uncertainty_text(element.get("proposition") or element.get("reason"))
            ):
                element.update({
                    "internal_meta": True,
                    "user_visible": False,
                })
                internal_rows.append({
                    "element_id": str(element.get("element_id") or ""),
                    "status": str(element.get("status") or ""),
                    "internal_reason": str(
                        element.get("internal_reason")
                        or element.get("reason")
                        or element.get("proposition")
                        or ""
                    ),
                })
        if internal_rows:
            item.decision_trace["internal_uncertainty_metadata"] = {
                "excluded_from_user_risk_output": True,
                "elements": internal_rows,
            }
        state = _build_narrative_state(item)
        for key in ("judgment", "issue", "consequence", "recommendation", "result"):
            state[key] = _strip_internal_uncertainty_fragments(state.get(key))
        state["missing_elements"] = [
            value for value in state.get("missing_elements") or []
            if not _is_internal_uncertainty_text(value)
        ]
        item.narrative_state = state
        item.decision_trace["narrative_elements"] = state
        for field_name in (
            "risk_point_description", "legal_consequence_if_missing", "suggested_clause_example",
        ):
            value = _strip_internal_uncertainty_fragments(getattr(item, field_name, ""))
            setattr(item, field_name, value)
        external_material_rows = [
            element for element in item.coverage_elements or []
            if str(element.get("status") or "").upper() == "REFERENCED_BUT_NOT_PROVIDED"
        ]
        if external_material_rows:
            # A referenced-but-unprovided exhibit is an external material state,
            # not retrieval uncertainty and not an ordinary missing clause. Keep
            # that single residual gap authoritative through the finding layer.
            external_consequence = (
                "所引用材料未纳入本次审查范围时，正文所述事项与该材料的一致性、签署状态及其作为合同组成部分的效力"
                "缺少可直接审查的材料基础，可能影响后续履行和举证。"
            )
            item.legal_consequence_if_missing = external_consequence
            state.update({
                "issue": item.risk_point_description,
                "consequence": external_consequence,
                "recommendation": item.suggested_clause_example,
            })
            item.narrative_state = state
            item.decision_trace["narrative_elements"] = state
        if item.item_id == "TC-08-03" and item.coverage_status == "缺失":
            item.risk_point_description = str(state["issue"])
            item.suggested_clause_example = str(state["recommendation"])
    return items


def _report_semantic_consistency_gate(
    items: List[ReviewItemResult],
    findings: List[RiskFinding],
    perspective_resolution: Dict[str, Any],
) -> Dict[str, Any]:
    """Audit reconciled report semantics without blocking unrelated report output."""
    warnings: List[Dict[str, Any]] = []
    item_by_id = {item.item_id: item for item in items}
    finding_by_id = {finding.finding_id: finding for finding in findings}
    for item in items:
        covered_ids = {
            str(row.get("element_id") or "") for row in item.coverage_elements or []
            if row.get("status") == "COVERED" and row.get("element_id")
        }
        missing_ids = {
            str(row.get("element_id") or "") for row in item.coverage_elements or []
            if row.get("status") in {"MISSING", "UNCERTAIN"} and row.get("element_id")
        }
        if covered_ids & missing_ids:
            warnings.append({
                "invariant": "PARTIAL_ELEMENT_DELTA",
                "review_id": item.item_id,
                "conflicting_element_ids": sorted(covered_ids & missing_ids),
            })
        for risk_id in item.related_risks:
            finding = finding_by_id.get(risk_id)
            if not finding or item.item_id not in finding.source_review_ids:
                continue
            if item.coverage_status == "通过" and finding.issue_type in {
                "PARTIAL", "MISSING", "ADVERSE", "ASYMMETRIC", "CONFLICTING",
            }:
                warnings.append({
                    "invariant": "PASS_WITH_SAME_SCOPE_FINDING",
                    "review_id": item.item_id,
                    "risk_id": risk_id,
                })
        if item.item_id == "TC-10-03":
            consequence = str((item.narrative_state or {}).get("consequence") or "")
            leaked = [term for term in ("验收节点", "质量异议", "付款条件", "风险转移") if term in consequence]
            if leaked:
                warnings.append({
                    "invariant": "CONSEQUENCE_GROUNDING",
                    "review_id": item.item_id,
                    "leaked_terms": leaked,
                })
        consequence = " ".join(filter(None, (
            str((item.narrative_state or {}).get("consequence") or ""),
            *[
                str(finding_by_id[risk_id].consequence or "")
                for risk_id in item.related_risks if risk_id in finding_by_id
            ],
        )))
        forbidden_by_review = {
            "TC-05-03": ("风险转移", "质量异议", "付款条件", "付款期限", "价格"),
            "TC-11-04": ("一般违约责任需明确延伸", "损失赔偿机制未完整约定"),
            "TC-12-04": ("缺少责任上限", "没有责任上限", "责任总额可能难以预估", "责任总额难以预估"),
        }
        forbidden = list(forbidden_by_review.get(item.item_id, ()))
        subtype_rendering = (item.decision_trace or {}).get("subtype_rendering") or {}
        if item.item_id == "TC-10-03" and subtype_rendering.get("primary_subtype") == "ENTRUSTED_DEVELOPMENT":
            if not subtype_rendering.get("has_follow_on_entitlement"):
                forbidden.extend(("合作核心技术", "主张共有", "收益分配等合同权利"))
        leaked_domains = [term for term in forbidden if term in consequence]
        if leaked_domains:
            warnings.append({
                "invariant": "LEGAL_CONSEQUENCE_DOMAIN_MISMATCH",
                "review_id": item.item_id,
                "leaked_terms": leaked_domains,
                "expected_domain": {
                    "TC-05-03": "SECRET_COPY_RETENTION",
                    "TC-10-03": "FOLLOW_ON_ENTITLEMENT_NOTIFICATION",
                    "TC-11-04": "CONFIDENTIALITY_INCIDENT_REMEDIES",
                    "TC-12-04": "INFRINGEMENT_REMEDY_COORDINATION",
                }.get(item.item_id, "RULE_SEMANTIC_DOMAIN"),
            })
    for finding in findings:
        if finding.risk_group == "asymmetric_breach_liability" and any(
            str(review_id).startswith("TECH-GEN-") for review_id in finding.source_review_ids
        ) and finding.party_effect not in {"FAVORABLE", "ADVERSE", "NEUTRAL", "MIXED"}:
            warnings.append({
                "invariant": "PARTY_EFFECT_REQUIRED",
                "risk_id": finding.finding_id,
                "party_effect": finding.party_effect,
            })
        for review_id in finding.source_review_ids:
            item = item_by_id.get(review_id)
            if not item:
                continue
            expected = ISSUE_TO_COVERAGE_STATUS.get(finding.issue_type)
            if expected and item.coverage_status not in {expected, COVERAGE_NOT_APPLICABLE}:
                warnings.append({
                    "invariant": "CANONICAL_COVERAGE_ALIGNMENT",
                    "risk_id": finding.finding_id,
                    "review_id": review_id,
                    "expected": expected,
                    "actual": item.coverage_status,
                })
    subtype = str(perspective_resolution.get("contract_subtype") or "")
    display_role = str(perspective_resolution.get("display_role") or "")
    if subtype == "COOPERATIVE_DEVELOPMENT" and any(
        token in display_role for token in ("专利权受让方", "专利权让与方", "许可方", "被许可方", "委托方", "受托方")
    ):
        warnings.append({
            "invariant": "SUBTYPE_ROLE_COMPATIBILITY",
            "contract_subtype": subtype,
            "display_role": display_role,
        })
    return {
        "status": "PASS" if not warnings else "WARNING",
        "non_fatal": True,
        "report_blocked": False,
        "warning_count": len(warnings),
        "warnings": warnings,
        "gate_results": {
            "REPORT_SEMANTIC_CONSISTENCY": "PASS" if not warnings else "WARNING",
            "FINDING_CONSEQUENCE_CONSISTENCY_GATE": "PASS" if not any(
                row.get("invariant") == "LEGAL_CONSEQUENCE_DOMAIN_MISMATCH" for row in warnings
            ) else "WARNING",
        },
    }


def _technology_transaction_consistency_gate(
    items: List[ReviewItemResult],
    findings: List[RiskFinding],
    classification: Dict[str, Any],
    perspective_resolution: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Enforce subtype applicability and coverage/evidence invariants before rendering."""
    if not classification:
        return {
            "status": "REPORT_READY",
            "failures": [],
            "rows": [],
            "gate_results": {"TECHNOLOGY_TRANSACTION_CONSISTENCY": "NOT_APPLICABLE"},
        }

    active_types = set(classification.get("active_transaction_types") or [])
    ancillary_type_map = {
        "technical_service": "TECHNICAL_SERVICE",
        "technical_guidance": "TECHNICAL_GUIDANCE",
        "technical_secret": "TECHNICAL_SECRET",
        "acceptance": "ACCEPTANCE",
        "technical_material_delivery": "TECHNICAL_MATERIAL_DELIVERY",
    }
    active_types.update(
        ancillary_type_map[value]
        for value in classification.get("sub_transactions") or []
        if value in ancillary_type_map
    )
    pure_patent_license = (
        str(classification.get("tertiary_subtype") or "") == "PATENT_LICENSE"
        and not classification.get("involves_software_or_data")
        and "COMMISSIONED_DEVELOPMENT" not in set(classification.get("secondary_modules") or [])
    )
    expected_by_prefix = {
        "TC-04": {"ENTRUSTED_DEVELOPMENT"},
        "TC-06": {"TECHNOLOGY_TRANSFER"},
        "TC-07": {"TECHNOLOGY_LICENSE"},
        "TC-08": {"TECHNICAL_CONSULTING"},
        "TC-09": {"TECHNICAL_SERVICE"},
    }
    expected_by_item = {
        "TC-05-01": {"COOPERATIVE_DEVELOPMENT"},
        "TC-05-02": {"COOPERATIVE_DEVELOPMENT"},
        "TC-05-03": {"COOPERATIVE_DEVELOPMENT", "ENTRUSTED_DEVELOPMENT"},
        "TC-05-04": {"COOPERATIVE_DEVELOPMENT", "ENTRUSTED_DEVELOPMENT"},
    }
    failures: List[Dict[str, Any]] = []
    rows: List[Dict[str, Any]] = []
    item_by_id = {item.item_id: item for item in items}
    gate_failures = {
        "CLASSIFICATION_NARRATIVE_CONSISTENCY": False,
        "EVIDENCE_JUDGMENT_CONSISTENCY": False,
        "ATOMIC_ELEMENT_CONSISTENCY": False,
        "CROSS_RULE_EVIDENCE_CONSISTENCY": False,
        "PARTY_DIRECTION_CONSISTENCY": False,
        "SUBTYPE_RENDERING_CONSISTENCY": False,
        "EVIDENCE_PROVENANCE_CONSISTENCY": False,
        "EMPTY_FIELD_CONSISTENCY": False,
        "REPORT_EVIDENCE_CONSISTENCY": False,
        "EVIDENCE_POLARITY_CONSISTENCY": False,
    }
    warnings: List[Dict[str, Any]] = []

    def add_failure(category: str, failure: Dict[str, Any]) -> None:
        gate_failures[category] = True
        failures.append(failure)

    def required_types(item_id: str) -> set[str]:
        if item_id in expected_by_item:
            return expected_by_item[item_id]
        return next((types for prefix, types in expected_by_prefix.items() if item_id.startswith(prefix)), set())

    for item in items:
        narrative_text = _compact(" ".join([
            str(item.reasoning_summary or ""),
            str(item.risk_point_description or ""),
            str((item.applicability or {}).get("reason") or ""),
            str((item.applicability or {}).get("machine_reason") or ""),
            str((item.applicability or {}).get("user_reason") or ""),
        ]))
        evidence_polarities = {
            str(row.get("evidence_polarity") or "") for row in item.evidence_clauses or []
            if row.get("evidence_polarity")
        }
        if item.coverage_status == "通过" and (item.decision_trace or {}).get("review_polarity") != "NEGATIVE_CLAUSE_CHECK":
            if evidence_polarities and "SUPPORTS_COVERAGE" not in evidence_polarities:
                add_failure("EVIDENCE_POLARITY_CONSISTENCY", {
                    "requirement": "PASS_REQUIRES_COVERAGE_POLARITY",
                    "failure_stage": "Evidence Polarity Gate",
                    "root_cause": f"{item.item_id} 输出 PASS，但证据极性不能证明保护要素已覆盖。",
                    "entity_type": "review", "entity_id": item.item_id,
                    "evidence_polarities": sorted(evidence_polarities), "severity": "blocking",
                })
        for row in item.evidence_clauses or []:
            if str(row.get("evidence_type") or "") == EvidenceType.SEARCH_AUDIT and row.get("evidence_polarity") != "SUPPORTS_ABSENCE":
                add_failure("EVIDENCE_POLARITY_CONSISTENCY", {
                    "requirement": "SEARCH_AUDIT_IS_ABSENCE_EVIDENCE",
                    "failure_stage": "Evidence Polarity Gate",
                    "root_cause": f"{item.item_id} 的 SEARCH_AUDIT 被错误标记为非缺失证据。",
                    "entity_type": "review", "entity_id": item.item_id,
                    "evidence_id": row.get("evidence_id"), "severity": "blocking",
                })
        if str(classification.get("primary_contract_type") or "").startswith("technology_license") and any(
            phrase in narrative_text
            for phrase in ("当前主交易为技术转让", "当前主交易为既有技术权利转让")
        ):
            add_failure("CLASSIFICATION_NARRATIVE_CONSISTENCY", {
                "requirement": "STALE_TRANSACTION_TYPE_NARRATIVE",
                "failure_stage": "Technology Classification Narrative Audit",
                "root_cause": f"{item.item_id} 使用了与统一技术许可分类冲突的技术转让文案。",
                "entity_type": "review",
                "entity_id": item.item_id,
                "severity": "blocking",
            })

        if item.coverage_status != COVERAGE_NOT_APPLICABLE and pure_patent_license:
            polluted_terms = [
                term for term in ("软件持续使用", "合作核心技术", "共有成果", "委托开发")
                if term in narrative_text
            ]
            if polluted_terms:
                gate_failures["SUBTYPE_RENDERING_CONSISTENCY"] = True
                warnings.append({
                    "requirement": "SUBTYPE_NARRATIVE_POLLUTION",
                    "review_id": item.item_id,
                    "terms": polluted_terms,
                    "reason": "专利实施许可审查结果包含无独立交易证据支持的其他技术合同场景文案。",
                })

        for evidence in (item.evidence_clauses or []) if pure_patent_license else []:
            validation = validate_evidence_provenance(evidence)
            if validation["status"] == "FAIL":
                add_failure("EVIDENCE_PROVENANCE_CONSISTENCY", {
                    "requirement": "EVIDENCE_PROVENANCE_INVALID",
                    "failure_stage": "Evidence Provenance Gate",
                    "root_cause": f"{item.item_id} 的证据来源校验失败：{', '.join(validation['errors'])}。",
                    "entity_type": "review",
                    "entity_id": item.item_id,
                    "evidence_id": evidence.get("evidence_id") or evidence.get("clause_id"),
                    "severity": "blocking",
                })

        if pure_patent_license and item.item_id in {"TC-11-01", "TC-11-02", "TC-11-04"}:
            display_text = _compact(" ".join(
                str(row.get("quote") or row.get("text") or "") for row in item.evidence_clauses or []
            ))
            raw_text = "\n".join(str(row.get("raw_text") or "") for row in item.evidence_clauses or [])
            required_labels = (
                ("保密义务适用于",)
                if item.item_id == "TC-11-01"
                else ("保密义务适用于", "保密期限")
            )
            missing_display_values = []
            for label in required_labels:
                field = extract_semantic_field_value(raw_text, label)
                value = str(field.get("field_value") or "")
                if field.get("is_filled") and value and _compact(value) not in display_text:
                    missing_display_values.append(label)
            if missing_display_values:
                add_failure("REPORT_EVIDENCE_CONSISTENCY", {
                    "requirement": "REPORT_EVIDENCE_INCONSISTENT",
                    "failure_stage": "Evidence Display Consistency Audit",
                    "root_cause": f"{item.item_id} 的判断依赖已填写字段，但报告证据未展示：{'、'.join(missing_display_values)}。",
                    "entity_type": "review",
                    "entity_id": item.item_id,
                    "severity": "blocking",
                })

        if item.item_id in {"TC-11-01", "TC-11-02"} and item.coverage_status == "通过":
            empty_check = (item.decision_trace or {}).get("empty_field_detection") or {}
            required_flags = (
                [empty_check.get("confidentiality_scope_filled")]
                if item.item_id == "TC-11-01"
                else [empty_check.get("confidentiality_scope_filled"), empty_check.get("confidentiality_period_filled")]
            )
            if empty_check and not all(required_flags):
                add_failure("EMPTY_FIELD_CONSISTENCY", {
                    "requirement": "EMPTY_TEMPLATE_FIELD_CANNOT_PASS",
                    "failure_stage": "Empty Field Detection Gate",
                    "root_cause": f"{item.item_id} 的保密字段仅有标签或占位内容，却被判定为通过。",
                    "entity_type": "review",
                    "entity_id": item.item_id,
                    "severity": "blocking",
                })

        required = required_types(item.item_id)
        if required:
            route_matches = bool(required & active_types)
            actually_applicable = (
                item.coverage_status != COVERAGE_NOT_APPLICABLE
                and (item.applicability or {}).get("applicable") is True
            )
            rows.append({
                "review_id": item.item_id,
                "required_transaction_types": sorted(required),
                "active_transaction_types": sorted(active_types),
                "route_matches": route_matches,
                "coverage_status": item.coverage_status,
            })
            if actually_applicable and not route_matches:
                add_failure("CLASSIFICATION_NARRATIVE_CONSISTENCY", {
                    "requirement": "SUBTYPE_RULE_APPLICABILITY",
                    "failure_stage": "Technology Applicability Gate",
                    "root_cause": f"{item.item_id} 已执行，但当前主/附属交易类型不包含其适用类型。",
                    "entity_type": "review",
                    "entity_id": item.item_id,
                    "severity": "blocking",
                })

        if item.coverage_status == "风险条款" and "TECHNOLOGY_LICENSE" in active_types:
            evidence_judgment = (item.decision_trace or {}).get("evidence_judgment") or {}
            evidence_semantics = str(evidence_judgment.get("evidence_semantics") or "")
            affirmative_ids = [
                str(value) for value in evidence_judgment.get("affirmative_risk_evidence_ids") or [] if value
            ]
            affirmative_rows = [
                row for row in item.evidence_clauses or []
                if row.get("affirmative_risk_evidence") is True
                or str(row.get("evidence_semantics") or "") == "ACTUAL_RISK_CLAUSE"
            ]
            has_affirmative_evidence = bool(item.evidence_clauses) and bool(affirmative_rows or affirmative_ids)
            if evidence_semantics in {"PROTECTIVE_CLAUSE", "RISK_EVENT_MENTION"} or not has_affirmative_evidence:
                add_failure("EVIDENCE_JUDGMENT_CONSISTENCY", {
                    "requirement": "RISK_CLAUSE_REQUIRES_AFFIRMATIVE_RISK_EVIDENCE",
                    "failure_stage": "Evidence Judgment Gate",
                    "root_cause": f"{item.item_id} 输出风险条款，但没有能够证明合同本身存在不利安排的 affirmative risk evidence。",
                    "entity_type": "review",
                    "entity_id": item.item_id,
                    "evidence_semantics": evidence_semantics or "UNCLASSIFIED",
                    "severity": "blocking",
                })

        if item.item_id == "TC-12-02":
            element_states = {
                str(row.get("element_id") or ""): str(row.get("status") or "")
                for row in item.coverage_elements or []
            }
            evidence_fragments = [
                fragment
                for row in item.evidence_clauses or []
                for fragment in re.split(r"[。；;\n]", str(row.get("quote") or row.get("text") or ""))
                if any(term in _compact(fragment) for term in (
                    "第三方权利主张", "第三方索赔", "第三方知识产权", "知识产权纠纷", "权利瑕疵",
                ))
            ]
            evidence_text = _compact(" ".join(evidence_fragments))
            affirmative_notification = bool(re.search(
                r"(?:应|须|应当|需|必须|负责).{0,20}通知|"
                r"(?:收到|接到|知悉)[^。；]{0,30}(?:\d+个?工作日|\d+日)内通知",
                evidence_text,
            ))
            notification_found = affirmative_notification
            deadline_found = affirmative_notification and bool(re.search(r"\d+个?工作日|\d+日内", evidence_text))
            notification_conflict = notification_found and element_states.get("notification_requirement") != "COVERED"
            deadline_conflict = deadline_found and element_states.get("notification_deadline") != "COVERED"
            if notification_conflict or deadline_conflict:
                add_failure("ATOMIC_ELEMENT_CONSISTENCY", {
                    "requirement": "ATOMIC_NOTIFICATION_CONSISTENCY",
                    "failure_stage": "Atomic Element Consistency Audit",
                    "root_cause": "TC-12-02 的合同证据已包含通知义务或期限，但对应原子要素未标记为 COVERED。",
                    "entity_type": "review",
                    "entity_id": item.item_id,
                    "element_states": element_states,
                    "severity": "blocking",
                })

        semantic_lookup = (item.decision_trace or {}).get("semantic_evidence_lookup") or {}
        if item.coverage_status == "缺失" and semantic_lookup.get("reused_clause_ids"):
            evaluated_ids = set(semantic_lookup.get("evaluated_clause_ids") or [])
            reused_ids = set(semantic_lookup.get("reused_clause_ids") or [])
            if not reused_ids.issubset(evaluated_ids):
                add_failure("CROSS_RULE_EVIDENCE_CONSISTENCY", {
                    "requirement": "CROSS_RULE_EVIDENCE_NOT_EVALUATED",
                    "failure_stage": "Semantic Evidence Reuse Audit",
                    "root_cause": f"{item.item_id} 在宣告缺失前未评价 Evidence Store 中已有的相关条款。",
                    "entity_type": "review",
                    "entity_id": item.item_id,
                    "source_clause_ids": sorted(reused_ids),
                    "severity": "blocking",
                })

        if item.coverage_status != "缺失":
            continue
        positive_rows = [
            row for row in item.evidence_clauses or []
            if str(row.get("source_type") or "") != "SEARCH_AUDIT"
            and not any(
                marker in _compact(f"{row.get('quote') or ''} {row.get('text') or ''}")
                for marker in ("未约定", "没有约定", "未找到", "未发现", "不包含", "不涉及", "尚未约定")
            )
            and (
                str(row.get("support_type") or "") == "DIRECT"
                or str(row.get("entailment_status") or "") in {EVIDENCE_SUPPORTS, EVIDENCE_PARTIAL_SUPPORT}
            )
            and (
                row.get("supporting_element_ids")
                or row.get("matched_terms")
                or row.get("claim_support_type") == "DIRECT"
            )
        ]
        if positive_rows:
            add_failure("CROSS_RULE_EVIDENCE_CONSISTENCY", {
                "requirement": "MISSING_WITH_POSITIVE_EVIDENCE",
                "failure_stage": "Technology Coverage Consistency",
                "root_cause": f"{item.item_id} 已有同一审查事项的正向证据，禁止输出‘未找到对应约定’。",
                "entity_type": "review",
                "entity_id": item.item_id,
                "source_clause_ids": [
                    str(row.get("clause_id") or row.get("evidence_id") or "") for row in positive_rows
                ],
                "severity": "blocking",
            })

    for finding in findings:
        direction = str((finding.risk_direction or {}).get("direction") or "")
        if pure_patent_license and direction in {"FAVORABLE", "NEUTRAL"}:
            add_failure("PARTY_DIRECTION_CONSISTENCY", {
                "requirement": "NON_ADVERSE_FINDING_EMITTED",
                "failure_stage": "Party Direction Gate",
                "root_cause": f"风险 {finding.finding_id} 对当前审查方并非不利，不得作为真实修改风险输出。",
                "entity_type": "finding",
                "entity_id": finding.finding_id,
                "severity": "blocking",
            })
        bundle_rows = list((finding.evidence_bundle or {}).get("items") or [])
        factual_rows = bundle_rows or list(finding.evidence or [])
        if (
            pure_patent_license
            and factual_rows
            and all(str(row.get("evidence_type") or "") == "DERIVED_FINDING" for row in factual_rows)
        ):
            add_failure("EVIDENCE_PROVENANCE_CONSISTENCY", {
                "requirement": "DERIVED_FINDING_SELF_SUPPORT",
                "failure_stage": "Evidence Provenance Gate",
                "root_cause": f"风险 {finding.finding_id} 仅由 DERIVED_FINDING 支撑，构成循环证明。",
                "entity_type": "finding",
                "entity_id": finding.finding_id,
                "severity": "blocking",
            })
        if pure_patent_license:
            for row in factual_rows:
                validation = validate_evidence_provenance(row)
                if validation["status"] == "FAIL":
                    add_failure("EVIDENCE_PROVENANCE_CONSISTENCY", {
                        "requirement": "FINDING_EVIDENCE_PROVENANCE_INVALID",
                        "failure_stage": "Evidence Provenance Gate",
                        "root_cause": f"风险 {finding.finding_id} 的证据来源校验失败：{', '.join(validation['errors'])}。",
                        "entity_type": "finding",
                        "entity_id": finding.finding_id,
                        "evidence_id": row.get("evidence_id"),
                        "severity": "blocking",
                    })
        for review_id in finding.source_review_ids:
            item = item_by_id.get(review_id)
            if item and item.coverage_status == COVERAGE_NOT_APPLICABLE:
                add_failure("CLASSIFICATION_NARRATIVE_CONSISTENCY", {
                    "requirement": "FINDING_FROM_NOT_APPLICABLE_RULE",
                    "failure_stage": "Technology Finding Consistency",
                    "root_cause": f"风险 {finding.finding_id} 来源规则 {review_id} 已判定不适用。",
                    "entity_type": "finding",
                    "entity_id": finding.finding_id,
                    "review_id": review_id,
                    "severity": "blocking",
                })

    conflict_exists = bool((classification.get("contract_type_conflict") or {}).get("exists"))
    conflict_findings = [finding for finding in findings if finding.risk_group == "contract_type_conflict"]
    if conflict_exists != bool(conflict_findings):
        add_failure("CLASSIFICATION_NARRATIVE_CONSISTENCY", {
            "requirement": "CONTRACT_TYPE_CONFLICT_PROJECTION",
            "failure_stage": "Technology Classification Consistency",
            "root_cause": (
                "分类器识别到合同性质冲突，但报告未生成对应冲突发现。"
                if conflict_exists else "分类器未识别合同性质冲突，但报告存在冲突发现。"
            ),
            "entity_type": "classification",
            "entity_id": str(classification.get("primary_contract_type") or "technology"),
            "severity": "blocking",
        })

    canonical_role = str((perspective_resolution or {}).get("canonical_role") or "")
    tc1204 = item_by_id.get("TC-12-04")
    if (
        pure_patent_license
        and canonical_role == "PATENT_LICENSEE"
        and tc1204
        and tc1204.risk_group == "indemnity_and_liability_cap"
    ):
        elements = {str(row.get("element_id") or ""): row for row in tc1204.coverage_elements or []}
        licensor_cap = elements.get("licensor_liability_cap") or {}
        cap_facts = dict((tc1204.decision_trace or {}).get("liability_cap_facts") or {})
        explicit_low_counterparty_cap = bool(
            cap_facts.get("liable_party") == "LICENSOR"
            and cap_facts.get("low_cap")
            and cap_facts.get("cap_imbalance")
        )
        direction = tc1204.risk_direction or {}
        recommendation_text = _compact(f"{tc1204.suggested_clause_example} {tc1204.action_suggestion}")
        narrows_licensor_remedy = any(
            phrase in recommendation_text
            for phrase in ("建议限制许可方", "应限制许可方", "建议设置许可方责任上限", "应设置许可方责任上限")
        )
        expected_cap_direction = "UNFAVORABLE" if explicit_low_counterparty_cap else "FAVORABLE"
        expected_risk_relevant = explicit_low_counterparty_cap
        if licensor_cap and (
            licensor_cap.get("direction") != expected_cap_direction
            or bool(licensor_cap.get("risk_relevant")) != expected_risk_relevant
            or narrows_licensor_remedy
        ):
            add_failure("PARTY_DIRECTION_CONSISTENCY", {
                "requirement": "LICENSEE_REMEDY_NARROWING_RECOMMENDATION",
                "failure_stage": "Party Direction Gate",
                "root_cause": (
                    "被许可方视角下，许可方已存在的低额责任上限应识别为压缩追偿空间的不利安排。"
                    if explicit_low_counterparty_cap else
                    "被许可方视角下，许可方责任无上限应视为有利，不得建议主动限制许可方赔偿责任。"
                ),
                "entity_type": "review",
                "entity_id": "TC-12-04",
                "risk_direction": direction,
                "severity": "blocking",
            })

    return {
        "status": "REPORT_READY" if not failures else "BLOCKED",
        "failures": failures,
        "rows": rows,
        "primary_contract_type": classification.get("primary_contract_type"),
        "secondary_contract_types": classification.get("secondary_contract_types") or [],
        "active_transaction_types": sorted(active_types),
        "contract_type_conflict": classification.get("contract_type_conflict") or {},
        "warnings": warnings,
        "gate_results": {
            "TECHNOLOGY_TRANSACTION_CONSISTENCY": "PASS" if not failures else "FAIL",
            **{
                name: (
                    "WARNING" if name == "SUBTYPE_RENDERING_CONSISTENCY" and failed and not failures
                    else "FAIL" if failed else "PASS"
                )
                for name, failed in gate_failures.items()
            },
        },
    }


def _coverage_safe_reasoning(item: ReviewItemResult, text: str) -> str:
    if item.narrative_state:
        return str(item.narrative_state.get("judgment") or text)
    cleaned = _user_facing_reasoning(text)
    if item.coverage_status == "部分覆盖" and any(phrase in cleaned for phrase in PARTIAL_TOTAL_MISSING_PHRASES):
        return _partial_element_narrative(item)
    if item.coverage_status == "缺失" and any(phrase in cleaned for phrase in MISSING_NARRATIVE_FORBIDDEN):
        return f"未在合同正文及附件中定位到“{item.title}”对应的明确约定。"
    if item.coverage_status == COVERAGE_NOT_APPLICABLE:
        return _applicability_user_reason(item)
    return cleaned


def _coverage_narrative_template(item: ReviewItemResult) -> str:
    if item.coverage_status == "通过":
        if item.related_risks:
            return "PASS_WITH_RELATED_FINDING"
        return "PASS"
    if item.coverage_status == "部分覆盖":
        return "PARTIAL"
    if item.coverage_status == "缺失":
        return "MISSING"
    if item.coverage_status == COVERAGE_NOT_APPLICABLE:
        return "NOT_APPLICABLE"
    if item.coverage_status == "风险条款":
        return "RISK_CLAUSE"
    return "UNCERTAIN"


def _format_money(value: Any) -> str:
    try:
        amount = float(value)
    except (TypeError, ValueError):
        return ""
    return f"{amount:,.0f}"


def _finding_economic_text(finding: RiskFinding, item_by_id: Dict[str, ReviewItemResult]) -> str:
    if finding.risk_group == "early_termination_financial_exposure":
        scenario_item = item_by_id.get("HL-039")
        cases = ((scenario_item.scenario_analysis or {}).get("cases") or []) if scenario_item else []
        parts = []
        for case in cases:
            amount = _format_money(case.get("estimated_penalty") or case.get("penalty") or case.get("amount"))
            if amount:
                parts.append(f"剩余{case.get('remaining_days')}天：约{amount}元")
        max_loss = _format_money((finding.economic_impact or {}).get("estimated_max_loss"))
        monthly_multiple = (finding.economic_impact or {}).get("monthly_payment_multiple")
        if parts:
            tail = f"最高约{max_loss}元" if max_loss else ""
            if monthly_multiple is not None:
                tail = f"{tail}，约相当于{monthly_multiple:g}个月当前月租金" if tail else f"约相当于{monthly_multiple:g}个月当前月租金"
            return f"按合同公式测算：{'；'.join(parts)}。{tail}。该计算方式不是普通固定倍数违约金，会随剩余租期变化。"
    economic = finding.economic_impact or {}
    if economic.get("has_direct_financial_exposure") and economic.get("direct_amount") is not None:
        amount = _format_money(economic.get("direct_amount"))
        percentage = economic.get("percentage_of_contract")
        ratio_text = f"，占合同总价{percentage:g}%" if percentage is not None else ""
        return f"直接资金暴露为{amount}元{ratio_text}。"
    if economic.get("impact_type") == "LIABILITY_ASYMMETRY":
        return str(economic.get("description") or "可确定责任比例存在明显不对称。")
    if economic.get("estimated_max_loss"):
        amount = _format_money(economic.get("estimated_max_loss"))
        monthly_multiple = economic.get("monthly_payment_multiple")
        if monthly_multiple is not None:
            return f"最大经济暴露约{amount}元，约相当于{monthly_multiple:g}个月当前月租金。"
        return f"最大经济暴露约{amount}元。"
    return ""


def _finding_legal_basis_text(finding: RiskFinding) -> str:
    values = [
        str(row.get("text") or "").strip()
        for row in finding.legal_basis or []
        if str(row.get("text") or "").strip()
    ]
    return "；".join(dict.fromkeys(values))


def _finding_evidence_text(finding: RiskFinding) -> str:
    bundle_items = [
        row for row in list((finding.evidence_bundle or {}).get("items") or [])
        if str(row.get("quoted_text") or row.get("quote") or row.get("text") or "").strip()
    ]
    # Confidentiality findings have a two-clause semantic chain whose roles are
    # more informative than the generic bundle listing.  Keep that explanation
    # even after the final-risk evidence invariant attaches a bundle.
    if bundle_items and finding.risk_group != "confidentiality_breach_liability":
        parts = []
        for row in bundle_items[:8]:
            quote = str(row.get("quoted_text") or "").strip()
            if len(quote) > 120:
                quote = quote[:120] + "..."
            supported = "、".join(str(value).rsplit(":", 1)[-1] for value in row.get("supports_claim_ids") or [])
            parts.append(
                f"[{row.get('evidence_id')}] {row.get('clause_number') or '结构化计算'}"
                f"{f' [支持：{supported}]' if supported else ''}：{quote}"
            )
        return (
            f"证据包ID：{finding.evidence_bundle.get('bundle_id')}；关键证据："
            + "；".join(parts)
        )
    evidence = finding.supporting_evidence or finding.evidence or []
    if not evidence:
        return "关键依据：合同保护机制不完整，建议结合相关条款范围核对。"
    if finding.risk_group == "confidentiality_breach_liability":
        evidence_by_role = {
            str(row.get("evidence_role") or ""): row
            for row in evidence
            if row.get("evidence_role")
        }
        confidentiality = evidence_by_role.get("CONFIDENTIALITY_OBLIGATION")
        liability = evidence_by_role.get("GENERAL_BREACH_LIABILITY")
        if confidentiality and liability:
            confidentiality_quote = _excerpt(str(confidentiality.get("quote") or confidentiality.get("text") or ""), 180)
            liability_quote = _excerpt(str(liability.get("quote") or liability.get("text") or ""), 180)
            bundle_prefix = (
                f"证据包ID：{finding.evidence_bundle.get('bundle_id')}；"
                if finding.evidence_bundle and finding.evidence_bundle.get("bundle_id")
                else ""
            )
            catch_all = (
                liability.get("claim_support_type") == "DIRECT_FOR_DAMAGES"
                or "GENERAL_BREACH_CATCH_ALL" in set(liability.get("fact_types") or [])
            )
            return (
                bundle_prefix
                + f"关键证据：合同文件{confidentiality.get('location') or '保密条款'}，\"{confidentiality_quote}\""
                " [支持：存在保密义务]；"
                f"合同文件{liability.get('location') or '违约责任条款'}，\"{liability_quote}\""
                + (
                    " [支持：一般违约 catch-all 覆盖违反保密义务造成的损失赔偿，但不替代行为性专项救济]；"
                    "综合判断：损失赔偿已覆盖，但停止披露、停止使用、防止继续扩散、资料处置及书面确认机制仍不完整，因此属于部分覆盖。"
                    if catch_all else
                    " [支持：仅约定一般/专项违约责任，未明确适用于保密义务]；"
                    "综合判断：合同存在保密义务，但现有违约责任未形成覆盖全部合同义务的兜底，泄密责任机制仍不完整。"
                )
            )
    first = evidence[0]
    location = first.get("location") or first.get("clause_number") or "合同相关条款"
    source_label = {
        "MAIN_CONTRACT": "合同正文",
        "SUPPLEMENTARY_TERMS": "补充条款",
        "APPENDIX": "附件",
        "AMENDMENT": "补充协议/修订文件",
        "SIDE_LETTER": "往来函件",
    }.get(first.get("source_document_type") or first.get("document_type"), "合同文件")
    text = (first.get("quote") or first.get("text") or "").strip()
    if len(text) > 80:
        text = text[:80] + "..."
    return f"关键证据：{source_label}{location}，{text}" if text else f"关键证据：{source_label}{location}。"


def _related_bundle_findings(
    item: ReviewItemResult,
    finding_by_id: Dict[str, RiskFinding],
) -> List[RiskFinding]:
    return [
        finding_by_id[risk_id]
        for risk_id in item.related_risks
        if risk_id in finding_by_id and finding_by_id[risk_id].evidence_bundle
    ]


def _bundle_position_display(findings: List[RiskFinding]) -> str:
    positions = [
        str(row.get("clause_number") or "结构化计算")
        for finding in findings
        for row in (finding.evidence_bundle.get("items") or [])
        if str(row.get("quoted_text") or row.get("quote") or row.get("text") or "").strip()
    ]
    return "；".join(dict.fromkeys(positions)) or "未定位到正式风险证据"


def _render_review_risk_bundles(findings: List[RiskFinding]) -> List[str]:
    lines = ["【证据定位】"]
    for finding in findings:
        bundle = finding.evidence_bundle
        bundle_items = [
            row for row in bundle.get("items") or []
            if str(row.get("quoted_text") or row.get("quote") or row.get("text") or "").strip()
        ]
        if not bundle_items:
            continue
        lines.extend([
            f"- 关联风险：{finding.title}",
            f"- 证据包ID：{bundle.get('bundle_id')}",
            f"- 证据ID：{'、'.join(str(row.get('evidence_id')) for row in bundle_items)}",
        ])
        for row in bundle_items:
            supported = "、".join(str(value).rsplit(":", 1)[-1] for value in row.get("supports_claim_ids") or [])
            lines.append(
                f"- {row.get('clause_number') or '结构化计算'}"
                f"{f' [支持：{supported}]' if supported else ''}: {row.get('quoted_text')}"
            )
    lines.append("")
    return lines


def _render_confidentiality_liability_evidence_chain(item: ReviewItemResult) -> List[str]:
    if item.item_id != "TC-11-04" or item.coverage_presence not in {"PARTIAL", "MISSING"}:
        return []
    evidence_by_role = {
        str(row.get("evidence_role") or ""): row
        for row in item.evidence_clauses or []
        if row.get("evidence_role")
    }
    ordered = [
        evidence_by_role[role]
        for role in ("CONFIDENTIALITY_OBLIGATION", "GENERAL_BREACH_LIABILITY")
        if role in evidence_by_role
    ]
    if not ordered:
        return []
    lines = ["【证据定位】", "- 依据来源：合同文件"]
    for index, row in enumerate(ordered, 1):
        quote = _excerpt(str(row.get("quote") or row.get("text") or ""), 240)
        lines.extend([
            f"- 证据{index}：{row.get('location') or '合同相关条款'}",
            f"- 原文片段：\"{quote}\"",
            f"- 支持：{row.get('support_summary') or '该条款构成专项判断的上下文证据。'}",
        ])
    propagation = (item.decision_trace or {}).get("general_breach_semantic_propagation") or {}
    if item.coverage_presence == "PARTIAL" and propagation.get("classification") == "GENERAL_BREACH_CATCH_ALL":
        lines.append("- 综合判断：一般违约责任已覆盖违反保密义务造成的损失赔偿；停止披露、停止使用、防止继续扩散、资料处置及书面确认机制仍不完整，因此属于部分覆盖。")
    elif item.coverage_presence == "PARTIAL":
        lines.append("- 综合判断：合同存在保密义务，但现有违约责任未形成覆盖全部合同义务的兜底，泄密损失赔偿及专项救济机制仍不完整，因此属于部分覆盖。")
    else:
        lines.append("- 综合判断：合同涉及保密事项，但未找到对应泄密责任机制，因此属于缺失。")
    lines.append("")
    return lines


def _report_evidence_projection(
    findings: List[RiskFinding],
    items: List[ReviewItemResult],
) -> Dict[str, Dict[str, Any]]:
    review_risks = {
        risk_id
        for item in items
        for risk_id in item.related_risks
    }
    rows: Dict[str, Dict[str, Any]] = {}
    for finding in findings:
        bundle = finding.evidence_bundle or {}
        if not bundle:
            continue
        evidence_ids = [str(row.get("evidence_id")) for row in bundle.get("items") or []]
        bundle_id = str(bundle.get("bundle_id") or "")
        rows[finding.finding_id] = {
            "risk_id": finding.finding_id,
            "bundle_id": bundle_id,
            "summary_bundle_id": bundle_id,
            "risk_detail_bundle_id": bundle_id,
            "review_detail_bundle_id": bundle_id if finding.finding_id in review_risks or not finding.source_review_ids else "",
            "summary_evidence_ids": evidence_ids,
            "risk_detail_evidence_ids": evidence_ids,
            "review_detail_evidence_ids": evidence_ids if finding.finding_id in review_risks or not finding.source_review_ids else [],
        }
    return rows


def _report_view_model(
    findings: List[RiskFinding],
    dispositions: Optional[List[FinalDisposition]] = None,
    summary_limit: int = 10,
) -> Dict[str, Any]:
    displayed = min(len(findings), summary_limit)
    remaining = max(0, len(findings) - displayed)
    rows = dispositions or []
    service_scope = _is_service_disposition_scope(rows)
    recommended = (
        [row for row in rows if row.include_in_priority_changes]
        if service_scope else
        [
            row for row in rows
            if row.report_visibility == "VISIBLE"
            and row.final_action in {DISPOSITION_MUST_CHANGE, DISPOSITION_SHOULD_CHANGE}
        ]
    )
    optional = (
        _visible_optional_dispositions(rows)
        if service_scope else
        [
            row for row in rows
            if row.report_visibility == "VISIBLE"
            and row.final_action == DISPOSITION_OPTIONAL_IMPROVEMENT
        ]
    )
    return {
        "summary_total_count": len(findings),
        "summary_displayed_count": displayed,
        "summary_remaining_count": remaining,
        "summary_is_truncated": remaining > 0,
        "recommended_total": len(recommended),
        "recommended_display_total": len(recommended),
        "recommended_remaining_count": 0,
        "recommended_truncated": False,
        "recommended_risk_ids": [row.risk_id for row in recommended],
        "optional_total": len(optional),
        "optional_display_total": len(optional),
        "optional_remaining_count": 0,
        "optional_truncated": False,
        "optional_risk_ids": [row.risk_id for row in optional],
    }


def _recommendation_component_lines(recommendation: Recommendation) -> List[str]:
    components = recommendation.components or recommendation.clauses or []
    if not components:
        return [recommendation.proposed_change or recommendation.suggested_text]
    lines: List[str] = []
    for component in components:
        source_type = component.get("source_type")
        proposition = component.get("proposition") or component.get("text") or ""
        if not proposition:
            continue
        if source_type in {"STATUTORY_RULE", "STATUTORY_DEFAULT"}:
            continue
        elif source_type == "CONTRACT_RULE":
            lines.append(f"【合同规则】：{proposition}")
        elif source_type in {"DRAFTING_CHOICE", "BUSINESS_PREFERENCE"}:
            lines.append(f"【起草建议】：{proposition}")
        else:
            lines.append(f"【风险缓释】：{proposition}")
    return lines or [recommendation.proposed_change or recommendation.suggested_text]


def _recommendation_inline_text(recommendation: Recommendation) -> str:
    return "；".join(_recommendation_component_lines(recommendation))


def _top_risk_line(
    finding: RiskFinding,
    item_by_id: Dict[str, ReviewItemResult],
    recommendation: Optional[Recommendation] = None,
    final_action: str = "",
) -> str:
    importance = finding.consequence or finding.issue
    economic_text = _finding_economic_text(finding, item_by_id)
    evidence_text = _finding_evidence_text(finding)
    cluster = dict((finding.aggregation_signals or {}).get("user_visible_risk_cluster") or {})
    public_label = str(cluster.get("title") or _finding_public_label(finding))
    pieces = [
        f"- **{public_label}**：{_final_action_label(final_action) if final_action else _recommendation_heading(finding.priority)}。",
        f"核心问题：{finding.issue}",
        f"重要性：{importance}",
    ]
    if economic_text:
        pieces.append(economic_text)
    pieces.append(evidence_text)
    if recommendation:
        pieces.append(f"建议：{_recommendation_inline_text(recommendation)}")
    return " ".join(piece for piece in pieces if piece)


def _economic_display(value: str) -> str:
    return {
        "none": "无明显直接金额影响",
        "low": "低",
        "medium": "中",
        "high": "高",
        "critical": "重大",
        "": "无明显直接金额影响",
    }.get(value or "", value)


def _contract_allocation_display(value: str) -> str:
    return {
        ALLOCATION_POSITIVE_OBLIGATION: "明确承担义务",
        ALLOCATION_NEGATIVE_OBLIGATION: "明确排除义务",
        ALLOCATION_NO_OBLIGATION: "明确约定无义务",
        ALLOCATION_RESERVED_RIGHT: "明确保留权利",
        ALLOCATION_PROHIBITION: "明确禁止",
        ALLOCATION_CONDITIONAL_OBLIGATION: "附条件义务",
    }.get(value or "", "")


def _professional_item_conclusion(item: ReviewItemResult) -> str:
    if item.item_id == "HL-039" and item.scenario_analysis:
        cases = item.scenario_analysis.get("cases") or []
        amounts = []
        for case in cases:
            amount = _format_money(case.get("estimated_penalty") or case.get("penalty") or case.get("amount"))
            if amount:
                amounts.append(f"剩余{case.get('remaining_days')}天约{amount}元")
        scenario_text = "；".join(amounts)
        prefix = f"按合同公式测算，{scenario_text}。" if scenario_text else ""
        return f"{prefix}该公式不是普通固定倍数违约金，而是会随剩余租期增加而放大，建议结合实际损失和金额上限处理。"
    if item.narrative_state:
        return str(item.narrative_state.get("judgment") or "")
    if item.coverage_status == INSUFFICIENT_CONTEXT:
        return _applicability_user_reason(item)
    if item.coverage_status == "通过":
        if item.related_risks:
            return "该审查事项已覆盖，但相关条款参与形成不利或冲突风险，应结合关联风险修改。"
        return "该审查事项已覆盖，无需修改。"
    if item.coverage_status == COVERAGE_NOT_APPLICABLE:
        return _applicability_user_reason(item)
    if item.coverage_status == "部分覆盖":
        return _partial_element_narrative(item)
    if item.coverage_status == "缺失":
        return f"未在合同正文及附件中定位到“{item.title}”对应的明确约定。"
    if item.coverage_status == "风险条款":
        return f"合同虽有相关条款，但条款内容本身可能引发执行争议，应按关联风险发现处理。"
    return _conclusion_text(item)


_SECTION_NUMERALS = "一二三四五六七八九十"


def _section_title(index: int, title: str) -> str:
    numeral = _SECTION_NUMERALS[index - 1] if 1 <= index <= len(_SECTION_NUMERALS) else str(index)
    return f"## {numeral}、{title}"


def _production_profile_lines(profile: UserRiskProfile, contract_type_name: str, perspective_resolution: Dict[str, Any]) -> List[str]:
    stance = str(perspective_resolution.get("display_role") or "合同当事人")
    lines = [f"- 审查立场：{stance}"]
    if profile.contract_scenario:
        lines.append(f"- 使用场景：{profile.contract_scenario}")
    return lines


def _report_context_profile_lines(profile: UserRiskProfile, report_context: Dict[str, Any], perspective_resolution: Dict[str, Any]) -> List[str]:
    lines = _production_profile_lines(profile, report_context["contract_type_label"], perspective_resolution)
    return [
        f"- 使用场景：{report_context['scenario_label']}" if line.startswith("- 使用场景：") else line
        for line in lines
    ]


_GAP_CONSEQUENCE_STUTTER = re.compile(
    r"(?:不完整|缺失|未明确|不足|未约定)不清(?:时)?"
)


def _display_legal_consequence(item: ReviewItemResult) -> tuple[str, str]:
    if item.coverage_status == INSUFFICIENT_CONTEXT:
        return "适用说明", _applicability_user_reason(item)
    if item.coverage_status == COVERAGE_NOT_APPLICABLE:
        return "适用说明", _applicability_user_reason(item)
    if item.coverage_status == "通过":
        if item.related_risks:
            return "处理结论", "本项已覆盖，但相关条款参与形成不利或冲突风险，应结合关联风险修改。"
        if (item.decision_trace or {}).get("review_polarity") == "NEGATIVE_CLAUSE_CHECK":
            return "处理结论", "未发现该不利安排，不形成对应风险。"
        return "处理结论", "已覆盖，无需修改。"
    if item.coverage_status == "部分覆盖" and item.narrative_state:
        narrative_consequence = str(item.narrative_state["consequence"] or "").strip()
        structured_consequence = str(item.legal_consequence_if_missing or "").strip()
        if _GAP_CONSEQUENCE_STUTTER.search(narrative_consequence):
            if structured_consequence and not _GAP_CONSEQUENCE_STUTTER.search(structured_consequence):
                return "缺失的法律后果", structured_consequence
            narrative_consequence = _GAP_CONSEQUENCE_STUTTER.sub("约定不完整，", narrative_consequence)
        return "缺失的法律后果", narrative_consequence
    return "缺失的法律后果", item.legal_consequence_if_missing


def _rendered_finding_party_effect(finding: RiskFinding) -> str:
    """Project an already-computed risk direction without changing risk decisions."""
    direct_effect = str(finding.party_effect or "UNKNOWN").upper()
    if direct_effect in {"ADVERSE", "FAVORABLE", "MIXED"}:
        return direct_effect
    risk_direction = finding.risk_direction or {}
    review_position = str(
        risk_direction.get("review_position")
        or risk_direction.get("review_position_code")
        or finding.review_party
        or ""
    ).strip().upper()
    direction = str(risk_direction.get("direction") or "").upper()
    if review_position and review_position not in {"UNKNOWN", "NONE"}:
        if direction in {"UNFAVORABLE", "ADVERSE"}:
            return "ADVERSE"
        if direction in {"FAVORABLE", "BENEFICIAL"}:
            return "FAVORABLE"
        if direction == "MIXED":
            return "MIXED"
        # An ADVERSE finding is already the result of the substantive rule's
        # party-aware evaluation.  A stale/structural NEUTRAL projection must
        # not make the renderer claim that no directional conclusion exists
        # once the review party is known.
        if finding.issue_type == "ADVERSE" and direction in {"", "NEUTRAL", "UNKNOWN"}:
            return "ADVERSE"
    return "UNKNOWN"


def _trusted_legal_basis_display(item: ReviewItemResult) -> str:
    legal_time_context = (item.decision_trace or {}).get("legal_time_context") or {}
    if legal_time_context.get("display_text"):
        return str(legal_time_context["display_text"])
    claims = item.legal_references or []
    direct = [
        claim for claim in claims
        if claim.get("support_type") in {"DIRECT_SUPPORT", "PARTIAL_SUPPORT"}
        and claim.get("freshness_status") not in {"OUTDATED_REFERENCE", "REPEALED"}
        and claim.get("law_name")
        and claim.get("claim_type") != "DRAFTING_RECOMMENDATION"
    ]
    routed_basis = (item.decision_trace or {}).get("legal_basis_applicability") or {}
    if routed_basis.get("status") in {"ROUTED", "PASSTHROUGH"} and item.legal_basis_index:
        # The scene router is the single source of truth for technology-law
        # applicability.  Keep the same routed basis in the finding and the
        # complete review detail; LegalClaim rows remain available for audit.
        return str(item.legal_basis_index)
    if direct:
        has_partial = any(claim.get("support_type") == "PARTIAL_SUPPORT" for claim in direct)
        authorities = list(dict.fromkeys(
            f"《{claim.get('law_name')}》{claim.get('article') or ''}" for claim in direct
        ))[:3]
        authority_text = "；".join(authorities)
        if has_partial:
            return authority_text
        return authority_text
    return ""


_CIVIL_CODE_EFFECTIVE_DATE = datetime(2021, 1, 1)
_TECHNOLOGY_HISTORICAL_LAW_MAPPINGS = {
    "第584条": {
        "historical_law": "中华人民共和国合同法",
        "historical_article": "第113条",
        "current_law": "中华人民共和国民法典",
        "current_article": "第584条",
        "description": "违约损害赔偿的一般规则",
    },
    "第881条": {
        "historical_law": "中华人民共和国合同法",
        "historical_article": "第359条",
        "current_law": "中华人民共和国民法典",
        "current_article": "第881条",
        "description": "技术咨询合同决策风险承担规则",
    },
}


def _extract_contract_sign_date(contract_text: str) -> Optional[datetime]:
    patterns = (
        r"(?:签署日期|签订日期|签订时间|合同签署日|合同签订日)\s*[:：]?\s*(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日",
        r"(?:签署日期|签订日期|签订时间|合同签署日|合同签订日)\s*[:：]?\s*(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})",
    )
    for pattern in patterns:
        matched = re.search(pattern, contract_text or "")
        if not matched:
            continue
        try:
            return datetime(*(int(value) for value in matched.groups()))
        except ValueError:
            return None
    return None


def _apply_technology_legal_time_context(
    items: List[ReviewItemResult], contract_text: str,
) -> List[ReviewItemResult]:
    signed_at = _extract_contract_sign_date(contract_text)
    if signed_at is None:
        return items

    for item in items:
        basis_text = str(item.legal_basis_index or "")
        basis_text += " " + " ".join(
            f"{claim.get('law_name') or ''}{claim.get('article') or ''}"
            for claim in item.legal_references or []
        )
        mapping = next(
            (
                row for article, row in _TECHNOLOGY_HISTORICAL_LAW_MAPPINGS.items()
                if article in basis_text
            ),
            None,
        )
        if not mapping:
            continue

        current_reference = f"《{mapping['current_law']}》{mapping['current_article']}"
        context: Dict[str, Any] = {
            "signed_at": signed_at.strftime("%Y-%m-%d"),
            "law_effective_date": _CIVIL_CODE_EFFECTIVE_DATE.strftime("%Y-%m-%d"),
            "current_corresponding_law": f"{mapping['current_law']}{mapping['current_article']}",
        }
        if signed_at < _CIVIL_CODE_EFFECTIVE_DATE:
            historical_reference = f"《{mapping['historical_law']}》{mapping['historical_article']}"
            context.update({
                "status": "HISTORICAL_AT_SIGNING",
                "law_at_signing": mapping["historical_law"],
                "historical_reference": historical_reference,
                "current_reference": current_reference,
                "display_text": (
                    f"签署时法律依据：{historical_reference}（{mapping['description']}）；"
                    f"现行对应规则：{current_reference}；"
                    "具体争议适用法律仍应结合履行时间、争议事实及相关法律适用规则判断。"
                ),
            })
        else:
            context.update({
                "status": "CURRENT_LAW_AT_SIGNING",
                "law_at_signing": mapping["current_law"],
                "current_reference": current_reference,
                # This field describes the signing-time successor of the
                # historical provision.  The complete, scenario-routed legal
                # basis remains available in ``legal_references`` and must not
                # be folded into this narrower display context.
                "display_text": current_reference,
            })
        item.decision_trace["legal_time_context"] = context
        # Preserve the established public trace key while using one source.
        item.decision_trace["signing_law_context"] = dict(context)
    return items


def _practice_basis_display(item: ReviewItemResult) -> str:
    if item.coverage_status in {"通过", COVERAGE_NOT_APPLICABLE, INSUFFICIENT_CONTEXT}:
        return ""
    claims = item.legal_references or []
    drafting = [
        claim for claim in claims
        if claim.get("claim_type") == "DRAFTING_RECOMMENDATION"
        or claim.get("support_type") == "BACKGROUND_ONLY"
    ]
    if drafting:
        return "本项属于合同管理、商业风险控制或起草完整性建议。"
    return ""


def _apply_default_law_narratives(items: List[ReviewItemResult]) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for item in items:
        gap = (item.decision_trace or {}).get("effective_gap") or {}
        default_status = str(gap.get("statutory_default") or "UNCERTAIN_DEFAULT")
        contractual_missing = list(gap.get("contractual_missing_elements") or [])
        statutory_elements = list(gap.get("statutory_default_elements") or [])
        residual = list(gap.get("still_unprotected_elements") or [])
        applicability = str((item.applicability or {}).get("status") or "APPLICABLE").upper()
        polarity = str((item.decision_trace or {}).get("review_polarity") or "POSITIVE_REQUIREMENT")
        if applicability == "NOT_APPLICABLE" or item.coverage_status == COVERAGE_NOT_APPLICABLE:
            narrative = ""
        elif item.coverage_status == "通过" and polarity == "NEGATIVE_CLAUSE_CHECK":
            narrative = "未发现该不利安排，因此不形成对应风险。"
        elif item.coverage_status == "通过":
            narrative = "合同已明确约定该事项。"
        elif item.coverage_status == "风险条款":
            party_effect = str((item.decision_trace or {}).get("party_effect") or "UNKNOWN")
            if party_effect == "FAVORABLE":
                narrative = (
                    f"合同已明确约定该安排；条款客观上存在责任不对称，但金额上相对有利于当前审查方："
                    f"{item.risk_point_description}"
                )
            elif party_effect == "ADVERSE":
                narrative = f"合同已明确约定该安排，且该风险分配对当前审查方不利：{item.risk_point_description}"
            elif party_effect == "MIXED":
                narrative = f"合同已明确约定该安排；该限制或风险同时作用于双方：{item.risk_point_description}"
            else:
                narrative = f"合同已明确约定该安排；尚未形成可靠的审查方方向判断：{item.risk_point_description}"
        elif item.coverage_status == "部分覆盖" and (item.decision_trace or {}).get("deterministic_semantic_risk"):
            narrative = f"合同已涉及该事项，但保护要素尚不完整：{item.risk_point_description}"
        elif default_status in {"CLEAR_DEFAULT", "PARTIAL_DEFAULT"} and statutory_elements:
            contract_state = "合同文本未完整约定该事项" if item.coverage_status == "部分覆盖" else "合同文本未约定该事项"
            protection = "现行法律已提供相应默认处理规则，因此实际法律风险受到一定控制"
            practical = "如希望减少履行争议，可进一步合同化明确。" if residual else "当前无需仅为重复法定规则而修改合同。"
            narrative = f"{contract_state}，但{protection}。{practical}"
        else:
            narrative = "合同未明确约定，且未识别到足以补足该缺口的明确法定默认规则。"
        contradiction = item.coverage_status == "部分覆盖" and any(
            phrase in narrative for phrase in ("合同已完整覆盖", "合同已明确约定该事项", "合同已经完全覆盖")
        )
        row = {
            "review_id": item.item_id, "contract_coverage": item.coverage_status,
            "contractual_missing_elements": contractual_missing, "default_law_status": default_status,
            "statutory_default_elements": statutory_elements, "residual_gap": residual,
            "practical_value": gap.get("remaining_gap") or "",
            "generated_narrative": narrative, "contradiction": contradiction,
        }
        item.decision_trace["effective_gap_narrative"] = row
        rows.append(row)
    return rows


def _default_law_narrative_truth_gate(rows: List[Dict[str, Any]]) -> Dict[str, Any]:
    contradictions = [row for row in rows if row.get("contradiction")]
    return {
        "status": "BLOCKED" if contradictions else "REPORT_READY",
        "failures": [] if not contradictions else [{
            "requirement": "DEFAULT_LAW_NARRATIVE_TRUTH_GATE", "failure_stage": "Effective Gap Narrative",
            "root_cause": "Default Law narrative represented partial contract coverage as fully contractually covered.",
            "responsible_function": "_apply_default_law_narratives", "current_status": "FAIL",
        }],
        "gate_results": {"DEFAULT_LAW_NARRATIVE_TRUTH_GATE": "FAIL" if contradictions else "PASS"},
        "contradiction_count": len(contradictions), "rows": rows,
    }


def _legal_default_law_consistency_gate(items: List[ReviewItemResult]) -> Dict[str, Any]:
    rows: List[Dict[str, Any]] = []
    contradictions: List[Dict[str, Any]] = []
    composite_errors: List[Dict[str, Any]] = []
    for item in items:
        assessment = (item.decision_trace or {}).get("default_law_assessment") or {}
        rule = assessment.get("rule") or {}
        authority_ids = list(rule.get("authority_ids") or [])
        selected = [
            claim for claim in item.legal_references or []
            if claim.get("authority_id") in authority_ids
            and claim.get("support_type") in {"DIRECT_SUPPORT", "PARTIAL_SUPPORT", "SUPPORTING"}
            and claim.get("freshness_status") == "CURRENT"
        ]
        supplied = list(rule.get("supplied_element_ids") or [])
        missing_ids = [
            str(element.get("element_id") or "") for element in item.coverage_elements or []
            if element.get("status") in {"MISSING", "PARTIALLY_COVERED"}
        ]
        unsupplied = [element_id for element_id in missing_ids if element_id not in supplied]
        default_status = str(assessment.get("status") or "UNCERTAIN_DEFAULT")
        supported = bool(selected)
        default_capable = bool(rule.get("proposition_id") or supplied)
        exclusion_reason = ""
        if supported and not default_capable:
            exclusion_reason = "Authority supports a related legal principle but does not supply the missing contractual mechanism."
        elif supported and default_capable and not supplied:
            exclusion_reason = "The resolved rule is legally relevant but does not supply a tracked contractual element."
        contradiction = (
            supported and default_capable and default_status in {"NO_DEFAULT", "UNCERTAIN_DEFAULT"}
            and not exclusion_reason
        )
        row = {
            "review_id": item.item_id,
            "element_id": supplied[0] if len(supplied) == 1 else "",
            "proposition_id": rule.get("proposition_id") or "",
            "legal_statement": rule.get("proposition") or "",
            "authority_ids": authority_ids,
            "authority_entailment": "SUPPORTS" if supported else "NOT_EVALUATED" if not authority_ids else "UNCERTAIN",
            "resolved_legal_status": "SUPPORTED_BY_CURRENT_LAW" if supported else "UNCERTAIN",
            "is_default_law_capable": default_capable,
            "default_law_status": default_status,
            "supplied_elements": supplied,
            "unsupplied_elements": unsupplied,
            "exclusion_reason": exclusion_reason,
            "consistency_gate": "FAIL" if contradiction else "PASS",
        }
        rows.append(row)
        if contradiction:
            contradictions.append(row)
        for element in item.coverage_elements or []:
            if element.get("atomic", True) is False and not element.get("child_elements"):
                composite_errors.append({
                    "review_id": item.item_id, "original_element": element.get("proposition"),
                    "atomic": False, "child_elements": [], "element_id": element.get("element_id"),
                })
    failures = []
    if contradictions:
        failures.append({
            "requirement": "LEGAL_DEFAULT_LAW_CONSISTENCY_GATE", "failure_stage": "Resolved Legal Rule",
            "root_cause": "A supported default-law-capable proposition diverged from DefaultLawResult without an exclusion reason.",
            "responsible_function": "_legal_default_law_consistency_gate", "current_status": "FAIL",
        })
    if composite_errors:
        failures.append({
            "requirement": "ATOMIC_LEGAL_ELEMENT_GATE", "failure_stage": "Legal Element Composition",
            "root_cause": "A non-atomic legal element reached Default Law without child elements.",
            "responsible_function": "_legal_default_law_consistency_gate", "current_status": "FAIL",
        })
    return {
        "status": "BLOCKED" if failures else "REPORT_READY", "failures": failures,
        "gate_results": {
            "LEGAL_DEFAULT_LAW_CONSISTENCY_GATE": "FAIL" if contradictions else "PASS",
            "ATOMIC_LEGAL_ELEMENT_GATE": "FAIL" if composite_errors else "PASS",
        },
        "contradiction_count": len(contradictions), "composite_error_count": len(composite_errors),
        "rows": rows, "element_decomposition": [
            {
                "review_id": item.item_id,
                "original_element": element.get("proposition"),
                "atomic": element.get("atomic", True),
                "child_elements": element.get("child_elements") or [],
                "child": [{
                    "element_id": element.get("element_id"),
                    "proposition_id": (element.get("legal_proposition_ids") or [""])[0],
                    "authority_ids": list((((item.decision_trace or {}).get("default_law_assessment") or {}).get("rule") or {}).get("authority_ids") or []),
                    "default_law_status": (((item.decision_trace or {}).get("default_law_assessment") or {}).get("status")),
                }],
            }
            for item in items for element in item.coverage_elements or []
            if element.get("legal_proposition_ids") or element.get("atomic", True) is False
        ],
    }


def _review_report_section(report: str, review_id: str) -> str:
    marker = f"（{review_id}）"
    if marker not in report:
        return ""
    section = report.split(marker, 1)[1]
    return section.split("\n## ", 1)[0]


def _applicability_polarity_gates(
    items: List[ReviewItemResult], findings: List[RiskFinding], recommendations: List[Recommendation], report: str = "",
) -> Dict[str, Any]:
    finding_ids_by_review = {
        item.item_id: [finding.finding_id for finding in findings if item.item_id in finding.source_review_ids]
        for item in items
    }
    recommendation_ids_by_review = {
        item.item_id: [
            recommendation.recommendation_id for recommendation in recommendations
            if set(recommendation.target_finding_ids) & set(finding_ids_by_review[item.item_id])
        ]
        for item in items
    }
    na_rows: List[Dict[str, Any]] = []
    polarity_rows: List[Dict[str, Any]] = []
    na_gap_errors: List[Dict[str, Any]] = []
    na_narrative_errors: List[Dict[str, Any]] = []
    negative_narrative_errors: List[Dict[str, Any]] = []
    negative_false_passes: List[Dict[str, Any]] = []
    forbidden_na_terms = ("合同缺失", "尚未覆盖", "仍需补足", "未识别到足以补足", "建议新增", "建议补充")
    positive_negative_terms = ("合同已覆盖", "合同已明确约定该事项", "合同已明确覆盖")
    for item in items:
        applicability = str((item.applicability or {}).get("status") or "APPLICABLE").upper()
        polarity = str((item.decision_trace or {}).get("review_polarity") or "POSITIVE_REQUIREMENT")
        section = _review_report_section(report, item.item_id) if report else ""
        if applicability == "NOT_APPLICABLE" or item.coverage_status == COVERAGE_NOT_APPLICABLE:
            gap = (item.decision_trace or {}).get("effective_gap") or {}
            default_assessment = (item.decision_trace or {}).get("default_law_assessment") or {}
            gap_error = (
                gap.get("status") != "NOT_APPLICABLE"
                or bool(gap.get("contractual_missing_elements"))
                or bool(finding_ids_by_review[item.item_id])
                or bool(recommendation_ids_by_review[item.item_id])
                or default_assessment.get("executed") is not False
            )
            narrative_error = bool(section) and any(term in section for term in forbidden_na_terms)
            row = {
                "review_id": item.item_id, "applicability": "NOT_APPLICABLE",
                "reason": (item.applicability or {}).get("reason") or "",
                "coverage_evaluated": False, "default_law_evaluated": default_assessment.get("executed", False),
                "effective_gap_created": gap.get("status") != "NOT_APPLICABLE",
                "finding_created": bool(finding_ids_by_review[item.item_id]),
                "recommendation_created": bool(recommendation_ids_by_review[item.item_id]),
                "production_gap_narrative_present": narrative_error,
                "gate_result": "FAIL" if gap_error or narrative_error else "PASS",
            }
            na_rows.append(row)
            if gap_error:
                na_gap_errors.append(row)
            if narrative_error:
                na_narrative_errors.append(row)
        if polarity == "NEGATIVE_CLAUSE_CHECK":
            negative = (item.decision_trace or {}).get("negative_clause_check") or {}
            narrative = str((item.narrative_state or {}).get("judgment") or "")
            positive_narrative = item.coverage_status == "通过" and (
                any(term in narrative for term in positive_negative_terms)
                or bool(section) and any(term in section for term in positive_negative_terms)
            )
            false_pass = item.coverage_status == "通过" and not (
                negative.get("adverse_clause_exists") is False
                and negative.get("search_coverage") == "SUFFICIENT"
                and negative.get("confidence") in {"medium", "high"}
            )
            row = {
                "review_id": item.item_id, "review_title": item.title, "polarity": polarity,
                "coverage": item.coverage_status, "evidence_state": negative,
                "expected_pass_semantics": "NO_ADVERSE_CLAUSE_FOUND",
                "generated_conclusion": narrative,
                "generated_exposure": ((item.decision_trace or {}).get("effective_gap_narrative") or {}).get("generated_narrative", ""),
                "gate_result": "FAIL" if positive_narrative or false_pass else "PASS",
            }
            polarity_rows.append(row)
            if positive_narrative:
                negative_narrative_errors.append(row)
            if false_pass:
                negative_false_passes.append(row)
    failures = []
    for requirement, errors, stage in (
        ("NOT_APPLICABLE_NARRATIVE_GATE", na_narrative_errors, "Applicability-aware Narrative"),
        ("NOT_APPLICABLE_GAP_GATE", na_gap_errors, "Applicability Gap Stop"),
        ("REVIEW_POLARITY_NARRATIVE_GATE", negative_narrative_errors, "Review Polarity Narrative"),
        ("NEGATIVE_CHECK_PASS_GATE", negative_false_passes, "Negative Clause Verification"),
    ):
        if errors:
            failures.append({
                "requirement": requirement, "failure_stage": stage,
                "root_cause": f"{len(errors)} review(s) violated applicability or polarity semantics.",
                "responsible_function": "_applicability_polarity_gates", "current_status": "FAIL",
            })
    return {
        "status": "BLOCKED" if failures else "REPORT_READY", "failures": failures,
        "gate_results": {
            "NOT_APPLICABLE_NARRATIVE_GATE": "FAIL" if na_narrative_errors else "PASS",
            "NOT_APPLICABLE_GAP_GATE": "FAIL" if na_gap_errors else "PASS",
            "REVIEW_POLARITY_NARRATIVE_GATE": "FAIL" if negative_narrative_errors else "PASS",
            "NEGATIVE_CHECK_PASS_GATE": "FAIL" if negative_false_passes else "PASS",
        },
        "not_applicable_gap_narrative_count": len(na_narrative_errors),
        "not_applicable_finding_count": sum(1 for row in na_rows if row["finding_created"]),
        "not_applicable_recommendation_count": sum(1 for row in na_rows if row["recommendation_created"]),
        "negative_review_positive_narrative_count": len(negative_narrative_errors),
        "negative_check_false_pass_count": len(negative_false_passes),
        "not_applicable_rows": na_rows, "polarity_rows": polarity_rows,
    }


def _display_suggested_clause(item: ReviewItemResult) -> tuple[str, str]:
    if item.coverage_status == COVERAGE_NOT_APPLICABLE:
        return "", ""
    if item.coverage_status == "通过":
        if item.risk_level == "低":
            return "", ""
        return "可选优化", item.suggested_clause_example
    if item.coverage_status == "部分覆盖":
        return "建议补充", str((item.narrative_state or {}).get("recommendation") or item.suggested_clause_example)
    if item.coverage_status == "风险条款":
        return "建议修改原条款", item.suggested_clause_example
    return "建议新增", item.suggested_clause_example


def _build_reasoning_text(item: ReviewItemResult, citation: Dict[str, str]) -> str:
    evidence_text = (
        f"{citation['clause_number']}：{citation['original_excerpt']}"
        if citation["original_excerpt"] != "无正式条款证据"
        else "未在正式合同条款或附件中召回可验证证据。"
    )
    return "\n".join(
        [
            "【推理过程】",
            f"证据：{evidence_text}",
            "↓",
            f"规则：{_legal_rule_text(item)}",
            "↓",
            f"判断：{_judgment_text(item, citation)}",
            "↓",
            f"结论：{_conclusion_text(item)}",
        ]
    )


def _enrich_reasoning_and_citation(items: List[ReviewItemResult]) -> List[ReviewItemResult]:
    for item in items:
        if item.risk_level not in _TRACEABLE_REASONING_RISK_LEVELS:
            item.reasoning = ""
            item.citation = {}
            continue

        citation = _first_citation(item)
        item.citation = citation
        item.reasoning = _build_reasoning_text(item, citation)
    return items


def _apply_final_quality_gate(
    items: List[ReviewItemResult],
    facts: Optional[HouseLeaseContractFacts],
    contract_type_key: str,
) -> tuple[List[ReviewItemResult], Dict[str, Any]]:
    flags: List[Dict[str, Any]] = []
    by_id = {item.item_id: item for item in items}

    for item in items:
        entails, evidence_type, semantic_reason = _semantic_entailment_for_item(item)
        if evidence_type:
            item.evidence_type = evidence_type
        if entails is not None:
            item.semantic_entailment = entails
        if entails is False and item.coverage_status in {"通过", "部分覆盖", "风险条款"}:
            flag = {
                "item_id": item.item_id,
                "type": "semantic_entailment_failed",
                "message": semantic_reason or "证据条款与审查点法律功能不匹配，已撤销覆盖结论并标记人工复核。",
                "recommended_action": "auto_fix",
            }
            flags.append(flag)
            item.quality_flags.append(flag)
            item.needs_manual_review = False
            item.quality_gate_failure_reason = ""
            item.review_status = "已自动修正"
            item.coverage_status = "缺失"
            item.status = "缺失或不明确"
            item.issue_type = "完全缺失"
            item.evidence_clauses = []
            item.evidence_location = ""
            item.risk_point_description = "未在正式合同条款中找到能覆盖该审查点法律功能的有效约定；已排除语义不匹配证据。"
            item.reasoning_summary = f"证据实质性匹配失败：{flag['message']} 未在正式合同条款中找到能覆盖该审查点的有效约定。"
        if item.coverage_status in {"通过", "部分覆盖", "风险条款"} and not item.evidence_clauses:
            # Low-risk pass without evidence is acceptable only for applicability or source exemptions.
            if item.coverage_status == "通过" and item.risk_level == "低":
                continue
            if item.coverage_status == "通过" and item.fallback_reason in {"案件文书摘录来源豁免"}:
                continue
            flag = {
                "item_id": item.item_id,
                "type": "evidence_missing",
                "message": "审查项存在覆盖结论但未附带正式条款或事实图谱证据，已标记人工复核。",
                "recommended_action": "human_review",
            }
            flags.append(flag)
            item.quality_flags.append(flag)
            item.review_status = "待人工复核"

    if contract_type_key == "lease":
        if facts:
            for field_name, node in facts.nodes.items():
                if node.value is not None and not node.evidence:
                    flags.append(
                        {
                            "item_id": "",
                            "type": "fact_without_provenance",
                            "field": field_name,
                            "message": f"Fact Graph 字段 {field_name} 有值但无 provenance，禁止作为高置信事实。",
                            "recommended_action": "retrieval_verify",
                        }
                    )

        if facts and facts.early_termination.exists and (item := by_id.get("HL-030")) and item.coverage_status != COVERAGE_NOT_APPLICABLE:
            flag = {
                "item_id": "HL-030",
                "type": "applicability_conflict",
                "message": "Fact Graph 显示存在提前退租条款，但 HL-030 仍在执行无提前退租补位审查，已自动改为不适用。",
                "recommended_action": "auto_fix",
            }
            flags.append(flag)
            _set_item_not_applicable(item, flag["message"])
            item.quality_flags.append(flag)

        hl015 = by_id.get("HL-015")
        hl017 = by_id.get("HL-017")
        if facts and facts.termination.rent_default.exists and hl015 and hl015.coverage_status == "缺失":
            flag = {
                "item_id": "HL-015",
                "type": "cross_review_consistency_auto_fix",
                "message": "Fact Graph 显示 termination.tenant.rent_default.exists=true，但 HL-015 仍为缺失，已按事实图谱 provenance 自动重审为通过。",
                "recommended_action": "auto_fix",
            }
            flags.append(flag)
            threshold = facts.termination.rent_default
            _set_item_pass_from_fact(
                hl015,
                facts,
                "termination.tenant.rent_default.exists",
                f"Final Quality Gate 读取 termination.tenant.rent_default.exists=true，threshold_type={threshold.threshold_type}，threshold_value={threshold.threshold_value}，threshold_unit={threshold.threshold_unit}，effect={threshold.effect}，修复欠租重大违约标准漏召回。",
                "合同已明确欠租达到一定期间或程度时可解除，欠租重大违约标准已覆盖。",
            )
            hl015.quality_flags.append(flag)

        if hl015 and hl017 and hl015.coverage_status == "缺失" and hl017.coverage_status == "通过":
            hl017_text = " ".join(clause.get("text", "") for clause in hl017.evidence_clauses)
            if any(term in hl017_text for term in ("欠租", "逾期不支付租金", "拖欠租金")):
                flag = {
                    "item_id": "HL-015",
                    "type": "cross_review_contradiction",
                    "message": "HL-017 已识别欠租解除事由，但 HL-015 仍称欠租标准缺失；已复用 HL-017 明确原文自动重审 HL-015。",
                    "recommended_action": "auto_fix",
                }
                flags.append(flag)
                hl015.risk_level = "低"
                hl015.status = "已覆盖"
                hl015.coverage_status = "通过"
                hl015.issue_type = "通过"
                hl015.evidence_clauses = hl017.evidence_clauses[:1]
                hl015.evidence_location = hl017.evidence_location
                hl015.reasoning_summary = "Cross Review Consistency Verifier 发现 HL-017 已基于同一解除条款识别欠租解除事由，HL-015 不得再判定为完全缺失。"
                hl015.risk_point_description = "合同已明确欠租达到一定期间或程度时可解除，欠租重大违约标准已覆盖。"
                hl015.fallback_reason = "Cross Review Consistency Verifier"
                hl015.quality_flags.append(flag)

        natural_wear_landlord = bool(facts and facts.repair.natural_wear == LANDLORD)
        if natural_wear_landlord:
            for item_id in ("HL-026", "HL-034"):
                item = by_id.get(item_id)
                if item and item.coverage_status == "缺失":
                    flag = {
                        "item_id": item_id,
                        "type": "cross_item_fact_conflict",
                        "message": "Fact Graph 明确 repair.natural_wear=landlord，但该审查项仍为缺失，已标记人工复核。",
                        "recommended_action": "human_review",
                    }
                    flags.append(flag)
                    item.quality_flags.append(flag)
                    item.review_status = "待人工复核"

        if facts and facts.deposit.amount and facts.deposit.return_deadline is None and (item := by_id.get("HL-043")) and item.risk_level == "高":
            flag = {
                "item_id": "HL-043",
                "type": "severity_anomaly_auto_fix",
                "message": "押金约为普通押金且仅缺少具体返还天数，不应自动高于剩余租期租金倍数违约金风险，已校准为中风险。",
                "recommended_action": "auto_fix",
            }
            flags.append(flag)
            item.risk_level = "中"
            item.quality_flags.append(flag)

        if (item := by_id.get("HL-039")) and item.scenario_analysis:
            impact = _economic_impact_for_penalty(item.scenario_analysis)
            if impact:
                item.economic_impact = impact
            formula = item.scenario_analysis.get("formula") or {}
            if impact == "high" and item.risk_level == "中" and _formula_requires_high_severity(formula):
                flag = {
                    "item_id": "HL-039",
                    "type": "severity_anomaly_auto_fix",
                    "message": "Scenario Engine 显示提前退租公式在长剩余租期下经济影响为 high，已从中风险校准为高风险。",
                    "recommended_action": "auto_fix",
                }
                flags.append(flag)
                item.risk_level = "高"
                item.quality_flags.append(flag)

        if facts and facts.jurisdiction.type == "arbitration" and facts.jurisdiction.arbitration_body is None:
            flags.append(
                {
                    "item_id": "HL-001",
                    "type": "fact_validation",
                    "message": "管辖事实包含未填写或未选中的仲裁机构，禁止作为有效管辖结论。",
                    "recommended_action": "ignore_unselected_option",
                }
            )

        apply_claims(items)
        for conflict in verify_consistency(items):
            flags.append(conflict)
            for claim in conflict.get("claims", []):
                item = by_id.get(claim.get("source_item_id"))
                if item:
                    item.quality_flags.append(conflict)
                    item.needs_manual_review = True
                    item.quality_gate_failure_reason = "Cross Review Consistency Verifier 发现同一事实存在相互冲突的审查结论。"

    if contract_type_key == "lease":
        _apply_high_risk_reason_gate(items)
    if contract_type_key != "lease":
        apply_claims(items)
    for item in items:
        if item.needs_manual_review and item.quality_gate_failure_reason:
            continue
        human_flags = [flag for flag in item.quality_flags if flag.get("recommended_action") == "human_review"]
        if human_flags:
            item.needs_manual_review = True
            item.quality_gate_failure_reason = human_flags[-1].get("message", "")

    return items, {
        "passed": not any(flag["recommended_action"] == "human_review" for flag in flags),
        "flags": flags,
        "flag_count": len(flags),
        "claims_count": sum(len(item.claims) for item in items),
    }


def _sanitize_review_report(report: str) -> str:
    cleaned = report
    cleaned = re.sub(
        r"建议补充明确合同存在可验证的“([^”]+)”(?:对应的核心安排|实质条款内容)",
        r"建议明确“\1”的具体权利义务、触发条件和执行程序",
        cleaned,
    )
    cleaned = re.sub(
        r"(?:合同存在)?可验证的“([^”]+)”(?:对应的核心安排|实质条款内容)",
        r"“\1”事项",
        cleaned,
    )
    cleaned = cleaned.replace("”对应的核心安排", "”具体修改依据")
    cleaned = cleaned.replace("对应的具体未明要素", "尚无法从现有材料确定的具体内容")
    cleaned = cleaned.replace("具体未明要素", "尚无法从现有材料确定的具体内容")
    cleaned = cleaned.replace("其余关键要素", "尚无法从现有材料确定的具体内容")
    cleaned = cleaned.replace("合同已明确覆盖：", "合同已明确约定")
    cleaned = cleaned.replace("合同已明确约定合同已约定", "合同已约定")
    cleaned = cleaned.replace("合同已明确约定已明确约定", "合同已明确约定")
    cleaned = cleaned.replace("合同已明确约定合同已限定", "合同已限定")
    cleaned = cleaned.replace("合同已明确约定合同未约定", "合同未约定")
    cleaned = cleaned.replace("合同已明确约定合同设置了", "合同设置了")
    cleaned = cleaned.replace("已明确约定合同已", "合同已")
    cleaned = cleaned.replace("合同已约定合同", "合同")
    cleaned = cleaned.replace("已经明确已经", "已经")
    cleaned = re.sub(r"合同已明确约定合同(?=[\u4e00-\u9fff])", "合同", cleaned)
    cleaned = cleaned.replace("建议建议", "建议")
    cleaned = cleaned.replace("无无需", "无需")
    cleaned = cleaned.replace("。。", "。")
    cleaned = cleaned.replace("；；", "；")
    cleaned = re.sub(r"已覆盖：已覆盖[:：]?", "已覆盖：", cleaned)
    cleaned = re.sub(r"缺失：缺失[:：]?", "缺失：", cleaned)
    cleaned = re.sub(r"：：+", "：", cleaned)
    cleaned = re.sub(r"([^。！？\n]{4,80}[。！？])\1+", r"\1", cleaned)
    return cleaned


def _report_text_validation_gate(report: str) -> Dict[str, Any]:
    patterns = {
        "BROKEN_QUOTE_CORE_ARRANGEMENT": r"”对应的核心安排",
        "DUPLICATE_COLON": r"：：+",
        "DUPLICATE_COVERED": r"已覆盖：已覆盖",
        "DUPLICATE_MISSING": r"缺失：缺失",
        "DUPLICATE_CONTRACT_COVERED": r"合同已明确约定合同|已明确约定合同已|合同已约定合同|已经明确已经",
        "DUPLICATE_SUGGEST": r"建议建议",
        "DUPLICATE_CLARIFY": r"明确明确",
        "DUPLICATE_SHOULD": r"应应",
        "DUPLICATE_CONTRACT": r"合同合同",
        "DUPLICATE_NO_ACTION": r"无无需",
        "DUPLICATE_PUNCTUATION": r"。。|；；",
        "UNREPLACED_TEMPLATE": r"\{[a-zA-Z_][a-zA-Z0-9_]*\}|<[^>\n]+>",
        "INTERNAL_ENUM_LEAK": r"\b(?:A_CORE|B_PRACTICAL|C_OPTIMIZATION|MUST_CHANGE|SHOULD_CHANGE|OPTIONAL_IMPROVEMENT|KEEP_CURRENT|DO_NOT_ADD|MANUAL_REVIEW|FOUND_SUPPORTING_CLAUSE|NO_SUPPORTING_CLAUSE)\b",
        "LEGACY_PRACTICE_AS_LEGAL": r"法律依据】：合同管理实务建议|法律依据】：相关法律规则参考",
        "PASS_PRACTICE_NOISE": r"当前未匹配到足够直接的现行具体条文",
        "DUPLICATE_EVIDENCE_TEXT": r"合同正文及附件中未找到对应约定；未在合同正文及附件中定位到对应安排",
        "NA_ALWAYS_APPLICABLE_CONTRADICTION": r"覆盖状态：不适用[\s\S]{0,240}【适用条件】：始终适用",
        "LEGACY_NOT_FOUND": r"未召回正式条款",
        "RECOMMENDATION_PLACEHOLDER_TEXT": r"对应安排|实质条款内容|具体未明要素|其余关键要素|可验证的“[^”]+”实质条款内容|“[^”]+”相关事项|建议[^\n。；]{0,80}相关事项",
    }
    failures: List[Dict[str, Any]] = []
    for name, pattern in patterns.items():
        matches = re.findall(pattern, report or "")
        if matches:
            failures.append({
                "requirement": "REPORT_TEXT_VALIDATION",
                "failure_stage": "Report Rendering",
                "root_cause": name,
                "count": len(matches),
                "current_status": "FAIL",
            })
    return {
        "status": "REPORT_READY" if not failures else "BLOCKED",
        "failures": failures,
        "gate_results": {"REPORT_TEXT_VALIDATION": "PASS" if not failures else "FAIL"},
        "broken_template_text_count": sum(failure["count"] for failure in failures),
    }


def _report_disposition_projection_gate(
    report: str,
    dispositions: List[FinalDisposition],
    risk_themes: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    def section_text(title: str) -> str:
        marker = f"、{title}"
        if marker not in report:
            return ""
        return report.split(marker, 1)[1].split("\n## ", 1)[0]

    def section_item_count(*titles: str) -> int:
        section = next((section_text(title) for title in titles if section_text(title)), "")
        return sum(1 for line in section.splitlines() if line.startswith("- **"))

    themes = risk_themes or []
    technical_theme_projection = _risk_theme_projection_is_technical(themes)
    theme_summary = _risk_theme_summary(themes)
    service_scope = _is_service_disposition_scope(dispositions)
    expected_optional = (
        theme_summary["optional_improvement"]
        if technical_theme_projection else
        len(_visible_optional_dispositions(dispositions))
        if service_scope else
        sum(
            1 for row in dispositions
            if row.report_visibility == "VISIBLE" and row.final_action == DISPOSITION_OPTIONAL_IMPROVEMENT
        )
    )
    actual_optional = section_item_count("可选优化事项")
    expected_priority = (
        theme_summary["must_change"] + theme_summary["should_change"]
        if technical_theme_projection else
        sum(1 for row in dispositions if row.include_in_priority_changes)
        if service_scope else
        sum(
            1 for row in dispositions
            if row.report_visibility == "VISIBLE"
            and row.final_action in {DISPOSITION_MUST_CHANGE, DISPOSITION_SHOULD_CHANGE}
        )
    )
    actual_priority = section_item_count("建议修改事项", "建议优先修改")
    expected_keep = sum(1 for row in dispositions if row.final_action in {DISPOSITION_KEEP_CURRENT, DISPOSITION_DO_NOT_ADD})
    actual_keep = section_item_count("建议保持现状")
    hidden_optional_count = sum(
        1 for row in dispositions
        if row.final_action == DISPOSITION_OPTIONAL_IMPROVEMENT
        and row not in _visible_optional_dispositions(dispositions)
    )
    mismatches = [
        {"section": "optional_improvement", "expected": expected_optional, "actual": actual_optional},
        {"section": "priority_changes", "expected": expected_priority, "actual": actual_priority},
        {"section": "keep_current", "expected": expected_keep, "actual": actual_keep},
    ]
    mismatches = [row for row in mismatches if row["expected"] != row["actual"]]
    priority_section = section_text("建议修改事项") or section_text("建议优先修改")
    optional_section = section_text("可选优化事项")
    missing_priority_risk_ids = [
        str(theme.get("theme_id") or "") for theme in themes
        if technical_theme_projection
        and theme.get("final_action") in {DISPOSITION_MUST_CHANGE, DISPOSITION_SHOULD_CHANGE}
        and str(theme.get("title") or "") not in priority_section
    ] if technical_theme_projection else [
        getattr(row, "risk_id", "") for row in dispositions
        if (
            row.include_in_priority_changes
            if service_scope else
            row.report_visibility == "VISIBLE"
            and row.final_action in {DISPOSITION_MUST_CHANGE, DISPOSITION_SHOULD_CHANGE}
        )
        and getattr(row, "risk_title", "")
        and getattr(row, "risk_title", "") not in priority_section
    ]
    missing_optional_risk_ids = [
        str(theme.get("theme_id") or "") for theme in themes
        if technical_theme_projection
        and theme.get("final_action") == DISPOSITION_OPTIONAL_IMPROVEMENT
        and str(theme.get("title") or "") not in optional_section
    ] if technical_theme_projection else [
        getattr(row, "risk_id", "") for row in dispositions
        if (
            row in _visible_optional_dispositions(dispositions)
            if service_scope else
            row.report_visibility == "VISIBLE" and row.final_action == DISPOSITION_OPTIONAL_IMPROVEMENT
        )
        and getattr(row, "risk_title", "")
        and getattr(row, "risk_title", "") not in optional_section
    ]
    if missing_priority_risk_ids:
        mismatches.append({"section": "priority_risk_ids", "missing": missing_priority_risk_ids})
    if missing_optional_risk_ids:
        mismatches.append({"section": "optional_risk_ids", "missing": missing_optional_risk_ids})
    if hidden_optional_count and _is_service_disposition_scope(dispositions):
        mismatches.append({"section": "hidden_optional", "expected": 0, "actual": hidden_optional_count})
    failures = [{
        "requirement": "REPORT_DISPOSITION_PROJECTION_INVARIANT",
        "failure_stage": "Report Projection",
        "root_cause": "FinalDisposition counts do not match visible report section items.",
        "current_status": "FAIL",
        "mismatches": mismatches,
    }] if mismatches else []
    return {
        "status": "REPORT_READY" if not failures else "BLOCKED",
        "failures": failures,
        "gate_results": {"REPORT_DISPOSITION_PROJECTION_INVARIANT": "PASS" if not failures else "FAIL"},
        "optional_improvement_count": expected_optional,
        "optional_section_item_count": actual_optional,
        "recommended_count": expected_priority,
        "recommended_section_item_count": actual_priority,
        "missing_priority_risk_ids": missing_priority_risk_ids,
        "missing_optional_risk_ids": missing_optional_risk_ids,
        "hidden_optional_item_count": hidden_optional_count,
        "mismatches": mismatches,
    }


